(window.__XDATA=window.__XDATA||{})["xmvkq5l1e"]={"ch":["Anatomie-physiologie respiratoire","Pneumonie franche lobaire aiguë (PFLA)","Bronchite aiguë","Pleurésies et ponction pleurale","Insuffisance respiratoire aiguë et chronique","Gazométrie sanguine","BPCO : DDB, bronchite chronique, asthme, emphysème","OAP – volet pneumologie","Cancers bronchopulmonaires","Tuberculose","Test tuberculinique (IDR)","Hypertension artérielle","Insuffisance veineuse des membres inférieurs","Thrombose veineuse profonde","AOMI","Embolie pulmonaire","OAP – volet cardiologie","Insuffisance ventriculaire gauche","Insuffisance ventriculaire droite","Insuffisance cardiaque globale","Angine de poitrine","Syndrome coronarien aigu","Péricardite aiguë","Anatomie et sémiologie digestive","Reflux gastro-œsophagien","Ulcère gastroduodénal et gastrite","Hépatites virales","Rôle infirmier dans les hépatites (+ colopathie fonctionnelle)","Cirrhoses","Ponction d'ascite","Aspirations digestives","Cancers primitifs du foie","Lithiase biliaire","Lithiase urinaire","Infections des voies urinaires","Infections urinaires chroniques","Tuberculose uro-génitale","Insuffisance rénale aiguë","Insuffisance rénale chronique","Syndrome néphrotique","Néphropathie gravidique"],"q":[{"c":0,"q":"Quelle est la longueur de la trachée selon le cours ?","x":"La trachée est un conduit long de 12 centimètres qui fait suite au larynx et se divise en deux bronches souches.","mn":"Trachée = 12 comme les 12 côtes.","kid":"La trachée est un tuyau de la longueur d'une règle d'écolier qui amène l'air aux poumons.","t":"qcm","o":["12 cm","5 cm","20 cm","30 cm"],"a":0},{"c":0,"q":"Combien de lobes possède le poumon droit ?","x":"Deux scissures (grande et petite) divisent le poumon droit en trois lobes ; à gauche une seule scissure donne deux lobes.","mn":"Droit = 3 (D comme « Davantage »), gauche = 2 (place laissée au cœur).","kid":"Le poumon de droite a trois parts, celui de gauche deux, car le cœur prend de la place à gauche.","t":"qcm","o":["3 lobes","2 lobes","4 lobes","5 lobes"],"a":0},{"c":0,"q":"Quel est le volume courant normal selon le cours ?","x":"Le volume courant est le volume d'air inspiré et expiré au cours d'un cycle respiratoire normal sans effort : environ 0,5 l.","mn":"Courant = « coup » léger : un demi-litre.","kid":"Quand tu respires tranquillement, tu fais entrer à peu près une demi-bouteille d'eau d'air.","t":"qcm","o":["Environ 0,5 litre","Environ 2 litres","Environ 1,5 litre","Environ 5 litres"],"a":0},{"c":0,"q":"L'expiration normale est un phénomène actif mettant en jeu les muscles inspirateurs.","x":"Les muscles (diaphragme, intercostaux) travaillent à l'inspiration ; à l'expiration la cage revient passivement.","mn":"InspirAction (active) / ExpiRelax (passive).","kid":"Pour gonfler le ballon, tu forces ; pour le dégonfler, tu le laisses partir tout seul.","t":"vf","v":0},{"c":0,"q":"Le médiastin contient notamment le cœur, la trachée, l'œsophage et le canal thoracique.","x":"Le médiastin est la région médiane du thorax qui sépare les deux régions pleuro-pulmonaires ; il contient cœur, gros vaisseaux, trachée, œsophage, canal thoracique, nerfs, ganglions.","mn":"Médiastin = « milieu » du thorax où passent les tuyaux.","kid":"C'est le couloir au milieu de la poitrine où passent le cœur et plein de tuyaux.","t":"vf","v":1},{"c":0,"q":"Comment s'appellent les deux feuillets de la plèvre ?","x":"Chaque plèvre comprend un feuillet viscéral qui tapisse le poumon et un feuillet pariétal appliqué sur la paroi thoracique.","mn":"ViScéral = sur le poumon (Viscère) ; Pariétal = sur la Paroi.","kid":"C'est comme un sac en deux couches : une collée au poumon, l'autre collée aux côtes.","t":"open","r":"Viscéral et pariétal","acc":["Viscéral et pariétal","pariétal et viscéral","feuillet viscéral et feuillet pariétal","visceral","parietal"]},{"c":0,"q":"Quels muscles le cours cite-t-il comme muscles ventilatoires ?","x":"Au niveau des mécanismes des mouvements respiratoires interviennent le diaphragme et les muscles intercostaux, sous le contrôle des centres respiratoires.","mn":"DI-IN : DIaphragme + INtercostaux.","kid":"Le diaphragme est comme un trampoline sous les poumons, et les petits muscles entre les côtes ouvrent la cage.","s":"En TP, un étudiant observe un patient au repos qui respire calmement. Le formateur lui demande quels muscles assurent les mouvements respiratoires.","t":"qcm","o":["Le diaphragme et les muscles intercostaux","Le sterno-cléido-mastoïdien seul","Les muscles abdominaux seuls","Le grand pectoral et le deltoïde"],"a":0},{"c":0,"q":"Quel est ce volume et sa valeur selon le cours ?","x":"Le volume de réserve expiratoire est le volume maximum que l'on peut expirer après une expiration normale (≈ 1,5 l) ; la réserve inspiratoire ≈ 2 l.","mn":"Réserve EXPI = 1,5 ; réserve INSPI = 2 (on inspire plus qu'on n'expire).","kid":"Après avoir soufflé normalement, tu peux encore souffler fort environ une bouteille et demie.","s":"Lors d'un cours de physiologie, on mesure chez un sujet sain le volume maximal expiré après une expiration normale.","t":"qcm","o":["Volume de réserve expiratoire, environ 1,5 l","Volume de réserve inspiratoire, environ 2 l","Volume courant, environ 0,5 l","Volume résiduel, environ 5 l"],"a":0},{"c":1,"q":"Quel est le principal germe de la pneumonie franche lobaire aiguë ?","x":"La PFLA est causée principalement (80-90 % des cas) par une bactérie du genre pneumocoque.","mn":"PFLA = Pneumocoque First.","kid":"C'est une petite bactérie appelée pneumocoque qui infecte un morceau du poumon.","t":"qcm","o":["Le pneumocoque","Le bacille de Koch","Le staphylocoque doré exclusivement","Le virus de la grippe"],"a":0},{"c":1,"q":"Quelle est l'aspect typique de la fièvre à la phase d'état de la PFLA ?","x":"À la phase d'état, en l'absence de traitement : fièvre en plateau à 40°, tachycardie, oligurie, asthénie, langue saburrale…","mn":"PFLA = Plateau Fébrile à 40.","kid":"La fièvre monte très haut, à 40, et reste en haut comme un plateau.","t":"qcm","o":["Fièvre en plateau à 40 °C","Fièvre ondulante","Fièvre modérée à 38 °C inconstante","Hypothermie"],"a":0},{"c":1,"q":"Quel aspect radiologique est caractéristique de la PFLA ?","x":"La radiographie montre une opacité dense, homogène, systématisée, lobaire ou segmentaire, plus fréquente à droite, avec bronchogramme aérien.","mn":"Opacité « 3 H » : dense, Homogène, systématisée + bronchogramme.","kid":"Sur la photo des poumons, un morceau devient tout blanc et on voit les tuyaux de l'air à l'intérieur.","t":"qcm","o":["Opacité dense, homogène, systématisée avec bronchogramme aérien","Images en « nid d'abeille » bilatérales","Hyperclarté diffuse sans opacité","Ligne bordante pleurale isolée"],"a":0},{"c":1,"q":"Le traitement de la PFLA repose sur l'antibiothérapie (pénicilline, quinolone) pendant 7 à 14 jours, voire trois semaines.","x":"Le cours indique : antibiothérapie (pénicilline, quinolone), durée 7 à 14 jours voire trois semaines jusqu'à guérison totale.","mn":"Pneumocoque → Pénicilline.","kid":"On donne des médicaments qui tuent la bactérie pendant une à deux semaines.","t":"vf","v":1},{"c":1,"q":"Bien traitée, la PFLA évolue habituellement vers l'abcès du poumon.","x":"Les complications suppuratives concernent la PFLA non traitée.","mn":"Traitée = guérie ; négligée = suppurée.","kid":"Si on soigne bien, le poumon guérit ; si on oublie, il peut se remplir de pus.","t":"vf","v":0},{"c":1,"q":"Comment appelle-t-on la visibilité nette des bronches sur la radiographie d'une PFLA ?","x":"On parle de bronchogramme aérien lorsque les bronches sont nettement visibles : l'air alvéolaire est remplacé par des cellules ou du liquide.","mn":"Bronche + gramme (image) d'air.","kid":"Les tuyaux d'air deviennent visibles parce que tout autour est rempli de liquide.","t":"open","r":"Bronchogramme aérien","acc":["Bronchogramme aérien","bronchogramme aerique","bronchogramme","bronchogramme"]},{"c":1,"q":"Quel est le diagnostic le plus probable ?","x":"Terrain à risque (âge, diabète), fièvre à 40°, expectoration rouillée (pneumocoque) et râles crépitants évoquent la PFLA.","mn":"Rouillé = pneumocoque.","kid":"Ce monsieur a une infection dans un morceau du poumon, causée par une bactérie, qui donne des crachats couleur rouille.","s":"M. K., 68 ans, diabétique, présente depuis 24 h un frisson solennel, une fièvre à 40 °C, un point de côté et une toux avec expectoration rouillée. L'auscultation retrouve des râles crépitants.","t":"qcm","o":["Pneumonie franche lobaire aiguë","Bronchite aiguë","Asthme","Pleurésie sèche"],"a":0},{"c":1,"q":"Quelle conduite infirmière est conforme au cours ?","x":"Le rôle infirmier : mettre le malade à jeun, éliminer les expectorations salivaires, effectuer le prélèvement trois fois de suite (sur trois jours) et transporter au laboratoire dans l'heure.","mn":"3 × 3 : 3 jours, à jeun, < 1 heure.","kid":"On recueille les vrais crachats du matin pendant trois jours et on les porte vite au labo.","s":"Un patient hospitalisé pour PFLA doit avoir un examen bactériologique des crachats.","t":"qcm","o":["Patient à jeun, éliminer la salive, prélever 3 jours de suite et acheminer au laboratoire dans l'heure","Prélever une seule fois la salive après le repas","Conserver les crachats 48 h au réfrigérateur avant envoi","Prélever uniquement après le début des antibiotiques"],"a":0},{"c":2,"q":"Quelle est l'origine la plus fréquente de la bronchite aiguë ?","x":"La bronchite aiguë est une maladie virale le plus souvent, banale et bénigne, au diagnostic purement clinique.","mn":"Bronchite aiguë = Banale, Bénigne, virale.","kid":"C'est souvent un virus, comme un rhume qui descend dans les bronches.","t":"qcm","o":["Virale","Bactérienne à pneumocoque","Parasitaire","Allergique"],"a":0},{"c":2,"q":"Quel est le signe principal de la bronchite aiguë ?","x":"La toux est le signe principal, parfois précédée d'une infection des voies respiratoires supérieures.","mn":"Bronchite = Toux.","kid":"Le corps tousse pour nettoyer les bronches irritées.","t":"qcm","o":["La toux","L'hémoptysie massive","La matité thoracique","Les œdèmes des membres inférieurs"],"a":0},{"c":2,"q":"Chez l'adulte sain atteint de bronchite aiguë, quelle est la règle concernant les antibiotiques ?","x":"L'abstention de toute prescription antibiotique est la règle chez l'adulte sain ; leur efficacité n'est démontrée ni sur la durée ni sur la prévention des complications.","mn":"Virus ≠ antibiotique.","kid":"Les antibiotiques ne tuent pas les virus, donc on n'en donne pas.","t":"qcm","o":["Abstention de toute prescription antibiotique","Antibiotique systématique dès J1","Corticoïdes systématiques","Antibiotique si fièvre à 38 °C"],"a":0},{"c":2,"q":"La bronchite aiguë s'accompagne d'une atteinte du parenchyme pulmonaire.","x":"L'atteinte du parenchyme correspond à la pneumonie, pas à la bronchite.","mn":"Bronchite = tuyaux ; pneumonie = éponge.","kid":"Seuls les tuyaux sont irrités, pas les petits sacs à air.","t":"vf","v":0},{"c":2,"q":"Dans la phase sèche de la bronchite aiguë, la fièvre est rarement supérieure à 38 °C et la toux est sèche, quinteuse, avec brûlure rétrosternale.","x":"Phase sèche : hyperthermie rarement > 38 °C, toux sèche quinteuse rauque épuisante avec douleur rétrosternale à type de brûlures.","mn":"Phase sèche = toux qui brûle.","kid":"Au début la toux pique et brûle derrière le sternum, sans crachat.","t":"vf","v":1},{"c":2,"q":"Citez les classes d'antibiotiques prescrits d'emblée quand une antibiothérapie est indiquée dans la bronchite aiguë.","x":"D'emblée : macrolides ou cyclines ; d'autres molécules en cas de surinfection.","mn":"MC d'emblée : Macrolides-Cyclines.","kid":"Quand il faut vraiment un antibiotique, on choisit d'abord ces deux familles.","t":"open","r":"Macrolides ou cyclines","acc":["Macrolides ou cyclines","cyclines ou macrolides","macrolides et cyclines","macrolide","cycline"]},{"c":2,"q":"Que prévoit le cours ?","x":"Antibiothérapie en cas d'association des 3 éléments : tabagisme, toux persistante et expectoration purulente au-delà de J7, râles bronchiques diffus.","mn":"Les 3 T : Tabac, Toux > J7, Râles.","kid":"Ici le monsieur fume, tousse depuis longtemps et ses poumons font du bruit : là on donne un antibiotique.","s":"M. A., 45 ans, fumeur, tousse depuis 10 jours avec une expectoration purulente ; l'auscultation retrouve des râles bronchiques diffus.","t":"qcm","o":["Une antibiothérapie, car les 3 critères (tabagisme, toux purulente > J7, râles diffus) sont réunis","Aucun traitement, la bronchite est toujours virale","Une corticothérapie seule","Une ponction pleurale"],"a":0},{"c":2,"q":"Pourquoi cet enfant est-il à risque de bronchite aiguë ?","x":"Le cours cite comme terrains favorisants : jeunes enfants et personnes âgées, déficit immunitaire génétique, défaut des cils bronchiques.","mn":"Petits, vieux, défenses faibles.","kid":"Son corps a du mal à se défendre, donc le virus descend plus facilement dans les bronches.","s":"Une infirmière accueille un enfant de 6 ans ayant un déficit immunitaire génétique, enrhumé depuis 3 jours, qui tousse maintenant.","t":"qcm","o":["Les jeunes enfants et les déficits immunitaires génétiques sont des facteurs favorisants","Parce que les enfants n'ont pas de bronches","Parce que la bronchite est héréditaire","Parce que la rhinite protège des bronchites"],"a":0},{"c":3,"q":"Quels sont les trois signes physiques majeurs de la pleurésie ?","x":"L'examen met en évidence : abolition des vibrations vocales à la palpation, abolition du murmure vésiculaire, matité à la percussion.","mn":"Triade du silence : pas de vibration, pas de murmure, mat.","kid":"Le liquide fait écran : on ne sent plus vibrer, on n'entend plus l'air, et ça sonne plein.","t":"qcm","o":["Abolition des vibrations vocales, abolition du murmure vésiculaire, matité","Râles crépitants, tympanisme, sibilants","Frottement péricardique, souffle tubaire, cyanose","Hippocratisme digital, œdèmes, ascite"],"a":0},{"c":3,"q":"À quoi ressemble le frottement pleural entendu au début d'une pleurésie ?","x":"Au début, un frottement pleural ressemblant à un bruit de « cuir neuf » peut être entendu : frottement des deux feuillets de la plèvre.","mn":"Cuir neuf = feuillets qui frottent.","kid":"Les deux couches de la plèvre se frottent comme des chaussures neuves qui grincent.","t":"qcm","o":["À un bruit de « cuir neuf »","À un bruit de « pluie sur un toit »","À un sifflement musical","À un bruit de « galop »"],"a":0},{"c":3,"q":"Quel accident grave peut survenir lors d'une ponction pleurale selon le cours ?","x":"Incidents : ponction blanche, lipothymie. Accidents : œdème aigu du poumon, embolie gazeuse.","mn":"Incidents légers (blanche, malaise) ; accidents graves (OAP, embolie gazeuse).","kid":"Si on enlève le liquide trop vite, le poumon peut se remplir d'eau ; ou de l'air peut entrer dans le sang.","t":"qcm","o":["Œdème aigu du poumon ou embolie gazeuse","Fracture de côte","Pneumonie franche lobaire","Hépatite"],"a":0},{"c":3,"q":"Pendant une ponction pleurale, la survenue de malaise, sueur, dyspnée ou toux impose l'arrêt de la ponction.","x":"Éléments de surveillance : survenue de malaise, sueur, dyspnée, toux : dans ce cas il faut faire arrêter la ponction.","mn":"Toux + sueur = STOP.","kid":"Si le patient se sent mal ou tousse, on arrête tout de suite.","t":"vf","v":1},{"c":3,"q":"La douleur de la pleurésie s'accentue généralement à mesure que l'épanchement augmente.","x":"Le liquide sépare les feuillets qui ne frottent plus, d'où une douleur moindre.","mn":"Le liquide calme le frottement.","kid":"Quand le liquide arrive, il fait coussin entre les couches, donc ça fait moins mal.","t":"vf","v":0},{"c":3,"q":"Comment s'appelle l'acte consistant à introduire une aiguille dans la cavité pleurale pour prélever son contenu ?","x":"La ponction pleurale consiste à introduire une aiguille dans la cavité pleurale en vue de prélever le contenu ; but diagnostique, évacuateur ou thérapeutique.","mn":"Ponction pleurale = Diagnostic, Évacuation, Thérapeutique (DET).","kid":"On pique doucement entre les côtes pour retirer le liquide.","t":"open","r":"Ponction pleurale","acc":["Ponction pleurale","ponction de plevre","thoracentese","ponction pleurale exploratrice","ponction"]},{"c":3,"q":"Quel diagnostic évoquer en premier ?","x":"La triade abolition des VV + abolition du MV + matité est celle de l'épanchement pleural liquidien.","mn":"Mat + silencieux = liquide.","kid":"Il y a de l'eau entre le poumon et la paroi, ce qui étouffe les bruits.","s":"Mme T., 40 ans, présente une dyspnée et un point de côté droit. À l'examen : vibrations vocales abolies, murmure vésiculaire absent et matité de la base droite.","t":"qcm","o":["Pleurésie avec épanchement liquidien","Pneumothorax","Bronchite aiguë","Asthme"],"a":0},{"c":3,"q":"Quelle vérification infirmière est prioritaire selon le cours ?","x":"Préparation du malade : informer, expliquer, rassurer, vérifier les radiographies, s'assurer qu'il n'y a pas de risque hémorragique (anticoagulant), prémédication.","mn":"Avant de piquer : radio + saignement.","kid":"On vérifie que le sang coagule bien pour éviter un saignement.","s":"Un médecin programme une ponction pleurale chez un patient sous anticoagulant.","t":"qcm","o":["S'assurer de l'absence de risque hémorragique (traitement anticoagulant)","Faire boire 3 litres d'eau avant le geste","Mettre le patient en décubitus ventral","Réaliser une IDR à la tuberculine"],"a":0},{"c":4,"q":"Quel examen permet seul d'apprécier objectivement l'insuffisance respiratoire ?","x":"Seul le dosage des gaz du sang artériel permet d'apprécier objectivement l'insuffisance respiratoire.","mn":"IR = Gaz du sang.","kid":"Pour savoir si le sang a assez d'oxygène, on le mesure directement dans une artère.","t":"qcm","o":["Le dosage des gaz du sang artériel","La radiographie pulmonaire","L'ECG","La NFS"],"a":0},{"c":4,"q":"À quel type de syndrome correspondent les affections neuromusculaires et la cyphoscoliose ?","x":"Syndromes restrictifs (affections neuromusculaires, cyphoscoliose) : anomalie de la pompe respiratoire réduisant les volumes mobilisés.","mn":"Restrictif = la pompe est « restreinte ».","kid":"La cage ou les muscles ne s'ouvrent pas assez, donc moins d'air entre.","t":"qcm","o":["Syndrome restrictif","Syndrome obstructif","Syndrome mixte","Syndrome néphrotique"],"a":0},{"c":4,"q":"En attendant le médecin, à quel débit l'infirmier administre-t-il l'oxygène par sonde nasale à un insuffisant respiratoire ?","x":"Administrer de l'oxygène à faible débit par sonde nasale 0,5 à 1 l/mn en attendant l'arrivée du médecin.","mn":"Faible débit : un demi à un litre.","kid":"On donne un tout petit filet d'oxygène dans le nez en attendant le docteur.","t":"qcm","o":["0,5 à 1 l/min","5 à 10 l/min","15 l/min au masque","Pas d'oxygène avant le médecin"],"a":0},{"c":4,"q":"Chez l'insuffisant respiratoire chronique, une fréquence respiratoire > 25-30 cycles/min au repos avec tirage est un signe de gravité.","x":"Le cours précise : FR > 25 ou 30 cycles/mn au repos avec tirage = signes de gravité.","mn":"25-30 + tirage = danger.","kid":"S'il respire très vite même assis et que ses côtes se creusent, c'est grave.","t":"vf","v":1},{"c":4,"q":"L'insuffisance respiratoire chronique restrictive est due principalement à l'asthme et à la bronchite chronique.","x":"Obstructif = bronches ; restrictif = cage/plèvre.","mn":"Obstrué = tuyau bouché ; restreint = cage coincée.","kid":"L'asthme bouche les tuyaux, la scoliose serre la cage.","t":"vf","v":0},{"c":4,"q":"Quels signes cardiaques droits peuvent s'associer à une décompensation d'IRC (citez-en deux) ?","x":"La décompensation peut s'accompagner de signes d'insuffisance ventriculaire droite : œdème des membres inférieurs, gros foie, tachycardie.","mn":"Cœur droit fatigué → jambes gonflées + gros foie.","kid":"Le côté droit du cœur s'épuise, l'eau stagne dans les jambes et le foie grossit.","t":"open","r":"Œdèmes des membres inférieurs et gros foie","acc":["Œdèmes des membres inférieurs et gros foie","oedeme des membres inferieurs, hepatomegalie","oedemes et gros foie","oedeme","foie"]},{"c":4,"q":"Quelle est la conduite infirmière adaptée ?","x":"Le cours prévoit : O2 faible débit 0,5-1 l/mn, contrôle de la cyanose, de la FR, de la conscience/agitation (transfert réanimation), prélèvement pour gazométrie.","mn":"Asseoir – O2 doux – Surveiller – Gaz du sang.","kid":"On l'assoit, on lui donne un peu d'oxygène et on le surveille de près.","s":"M. B., BPCO connu, arrive cyanosé, polypnéique, agité. Le médecin n'est pas encore là.","t":"qcm","o":["Installer en position demi-assise, O2 0,5-1 l/min par sonde nasale, surveiller conscience et constantes, préparer la gazométrie","Allonger à plat et administrer 15 l/min d'O2","Donner un sédatif pour calmer l'agitation","Attendre le médecin sans intervenir"],"a":0},{"c":4,"q":"Quel conseil d'éducation figure dans le cours ?","x":"Prévention : faire attention au changement de climat, éviter les infections, consultation obligatoire une fois par an, vaccination antigrippale, suivre le traitement.","mn":"Grippe-Vaccin, Climat, Contrôle annuel.","kid":"Elle doit se protéger des microbes, se faire vacciner et voir le médecin chaque année.","s":"Mme D., insuffisante respiratoire, retourne à domicile.","t":"qcm","o":["Vaccination antigrippale, éviter les infections, consultation une fois par an, suivre le traitement","Arrêter l'oxygène dès qu'elle se sent mieux","Faire du sport intensif en altitude","Supprimer toute consultation de suivi"],"a":0},{"c":5,"q":"Quelle est la valeur normale du pH artériel selon le cours ?","x":"pH : 7,38 à 7,42 ; < 7,38 = acidose ; > 7,42 = alcalose.","mn":"7,40 ± 0,02.","kid":"Le sang doit rester très légèrement basique, autour de 7,4.","t":"qcm","o":["7,38 à 7,42","7,00 à 7,20","7,50 à 7,60","6,80 à 7,00"],"a":0},{"c":5,"q":"Quelle est la valeur normale de la PaO2 selon le cours ?","x":"PaO2 : 90 +/- 5 mmHg ; PaCO2 : 38 à 42 mmHg ; HCO3- : 22 à 25 mmol/l ; saturation 97 à 100 %.","mn":"O2 = 90, CO2 = 40.","kid":"L'oxygène dans le sang artériel tourne autour de 90.","t":"qcm","o":["90 ± 5 mmHg","40 mmHg","150 mmHg","22 mmHg"],"a":0},{"c":5,"q":"Quel test est obligatoire avant le premier prélèvement à l'artère radiale ?","x":"Le test d'Allen vérifie que l'artère cubitale peut prendre le relais en cas de lésion de la radiale.","mn":"Allen = Artère cubitale de secours.","kid":"On vérifie que la main a un deuxième tuyau de sang avant de piquer le premier.","t":"qcm","o":["Le test d'Allen","Le test de Bishop","L'IDR à la tuberculine","Le test de Schilling"],"a":0},{"c":5,"q":"Lors d'une gazométrie, il faut avertir le laboratoire car le dosage se fait immédiatement, et éviter d'introduire de l'air.","x":"Précautions : avertir le laboratoire (dosage immédiat), éviter l'air, respecter l'asepsie, établir une fiche.","mn":"Pas d'air, pas d'attente.","kid":"Une bulle d'air ou du retard fausse le résultat.","t":"vf","v":1},{"c":5,"q":"Une PaCO2 élevée correspond à une hypoxie.","x":"Ne pas confondre les deux gaz.","mn":"CO2 haut = hyperCApnie ; O2 bas = hypOxie.","kid":"Trop de gaz « poubelle » = hypercapnie ; pas assez d'oxygène = hypoxie.","t":"vf","v":0},{"c":5,"q":"Quelle est la valeur normale de la saturation artérielle en oxygène selon le cours (en %) ?","x":"Saturation : 97 à 100 %.","mn":"Presque plein : 97 à 100.","kid":"Les globules rouges sont presque tous chargés d'oxygène.","t":"open","r":"97 à 100 %","acc":["97 à 100 %","97-100","97 a 100","97","100"]},{"c":5,"q":"Comment interpréter ce résultat selon les normes du cours ?","x":"pH < 7,38 = acidose ; PaCO2 > 42 = hypercapnie ; PaO2 < 85 = hypoxie.","mn":"pH bas + CO2 haut = acidose respiratoire.","kid":"Il garde trop de CO2 qui rend le sang acide, et manque d'oxygène.","s":"Un patient BPCO a une gazométrie : pH 7,32 ; PaCO2 55 mmHg ; PaO2 60 mmHg.","t":"qcm","o":["Acidose avec hypercapnie et hypoxie","Alcalose avec hypocapnie","Gazométrie normale","Hypoxie isolée sans trouble du pH"],"a":0},{"c":5,"q":"Quelle est la cause la plus probable selon le cours ?","x":"Incidents : hématome secondaire à une mauvaise compression ou à des essais infructueux ; thrombose ; ischémie ; piqûre du nerf radial ; résultats erronés.","mn":"Hématome = Compression insuffisante.","kid":"Si on n'appuie pas assez longtemps après la piqûre, le sang sort sous la peau.","s":"Après une gazométrie à l'artère radiale, l'infirmier constate un hématome au point de ponction.","t":"qcm","o":["Mauvaise compression ou essais de ponction infructueux","Présence de bulles d'air dans la seringue","Retard d'acheminement","Test d'Allen positif"],"a":0},{"c":6,"q":"Quelles sont les quatre affections regroupées sous le terme BPCO dans le cours ?","x":"Le cours retient quatre affections : dilatations des bronches, bronchite chronique, asthme, emphysème.","mn":"« DBAE » : Dilatation, Bronchite, Asthme, Emphysème.","kid":"Quatre maladies qui bouchent les bronches longtemps.","t":"qcm","o":["DDB, bronchite chronique, asthme, emphysème","PFLA, bronchite aiguë, pleurésie, OAP","Tuberculose, cancer, asthme, OAP","Pleurésie, pneumothorax, emphysème, PFLA"],"a":0},{"c":6,"q":"Comment le cours définit-il la bronchite chronique ?","x":"Bronchite chronique : toux productive pendant trois mois consécutifs depuis au moins deux années consécutives, avec augmentation permanente de la sécrétion bronchique.","mn":"3 mois × 2 ans.","kid":"On tousse et crache trois mois par an, deux ans de suite.","t":"qcm","o":["Toux productive pendant 3 mois consécutifs depuis au moins 2 années consécutives","Toux sèche depuis 15 jours","Crises de dyspnée sifflante nocturnes","Destruction des parois alvéolaires avec bulles"],"a":0},{"c":6,"q":"Par quoi débute le traitement de la crise d'asthme selon le cours ?","x":"Le traitement débute par un ou plusieurs aérosols de bêta-2 mimétiques (salbutamol, Ventoline, Bricanyl) associés au bromure d'ipratropium ; en cas d'échec bêta-2 IV/SC + corticoïde.","mn":"Crise = Bêta-2 d'abord.","kid":"On donne un spray qui ouvre vite les bronches.","t":"qcm","o":["Aérosols de bêta-2 mimétiques (salbutamol) ± bromure d'ipratropium","Antibiotique IV d'emblée","Diurétique IV (furosémide)","Anticoagulant"],"a":0},{"c":6,"q":"Quel type de dyspnée caractérise la crise d'asthme ?","x":"L'asthme se traduit par une bradypnée expiratoire et sifflante : l'expiration est plus lente, pénible et longue ; râles sibilants à l'auscultation.","mn":"Asthme = expiration lente qui siffle.","kid":"L'air a du mal à sortir et ça siffle comme un ballon qu'on dégonfle doucement.","t":"qcm","o":["Bradypnée expiratoire sifflante","Polypnée superficielle inspiratoire","Dyspnée de Kussmaul","Dyspnée de Cheyne-Stokes"],"a":0},{"c":6,"q":"Lors d'une crise d'asthme, il faut allonger le malade à plat pour le reposer.","x":"La position assise facilite la ventilation.","mn":"Asthmatique = assis.","kid":"Assis, on respire mieux ; couché, on étouffe.","t":"vf","v":0},{"c":6,"q":"Le tabagisme actif et passif est responsable d'environ 90 % des BPCO selon le cours.","x":"Facteurs : tabagisme (90 % des BPCO), pollution environnementale, pollution professionnelle (10 %), déficit en alpha-1 antitrypsine (1 %).","mn":"90 tabac / 10 travail / 1 enzyme.","kid":"La cigarette est la grande coupable.","t":"vf","v":1},{"c":6,"q":"L'emphysème pulmonaire correspond à une dilatation réversible des bronches moyennes.","x":"Ne pas confondre emphysème (alvéoles) et DDB (bronches).","mn":"Emphysème = bulles ; DDB = bronches dilatées.","kid":"Dans l'emphysème, les petits sacs à air éclatent et forment de grosses bulles.","t":"vf","v":0},{"c":6,"q":"Quel est le symptôme principal de la dilatation des bronches ?","x":"Les signes fonctionnels de la DDB sont dominés par la bronchorrhée purulente, abondante, quotidienne, surtout matinale.","mn":"DDB = crachats abondants le matin.","kid":"Les bronches abîmées fabriquent beaucoup de crachats sales, surtout le matin.","t":"open","r":"La bronchorrhée purulente","acc":["La bronchorrhée purulente","bronchorrhee","bronchorrhee purulente abondante matinale","bronchorrhee"]},{"c":6,"q":"De quelle complication s'agit-il ?","x":"L'état de mal asthmatique associe signes de gravité : dyspnée intense avec tirage, cyanose, tachycardie > 130/mn ; aboutissement d'une attaque négligée.","mn":"Tirage + cyanose + > 130 = état de mal.","kid":"La crise ne s'arrête plus et devient dangereuse.","s":"Mme S., asthmatique, est en crise depuis plusieurs heures malgré son aérosol. Elle a un tirage sus-sternal, une cyanose et un pouls à 140/min.","t":"qcm","o":["État de mal asthmatique","Crise d'asthme simple","Bronchite aiguë","Pleurésie"],"a":0},{"c":6,"q":"Quel conseil d'éducation figure dans le cours ?","x":"Éducation : alimentation équilibrée sans colorant, activité sportive (natation), dangers de l'automédication, reconnaître les allergènes, traiter les foyers infectieux.","mn":"Allergène évité, natation, pas d'automédication.","kid":"Il doit connaître ce qui déclenche ses crises et l'éviter.","s":"Un jeune asthmatique sort de l'hôpital après une crise.","t":"qcm","o":["Reconnaître et éviter les allergènes, éviter l'automédication, natation conseillée","Arrêter tout traitement de fond","Éviter toute activité physique à vie","Consommer des aliments riches en colorants"],"a":0},{"c":7,"q":"Comment le cours définit-il l'OAP ?","x":"L'OAP est une insuffisance cardiaque gauche aiguë caractérisée par une inondation des alvéoles pulmonaires par le plasma qui ne peut revenir vers le cœur.","mn":"OAP = Le cœur gauche ne pompe plus, l'eau Aux Poumons.","kid":"Le cœur n'arrive plus à pomper et l'eau déborde dans les petits sacs à air.","t":"qcm","o":["Une insuffisance cardiaque gauche aiguë avec inondation des alvéoles par le plasma","Une infection bactérienne du poumon","Une obstruction de l'artère pulmonaire par un caillot","Une inflammation de la plèvre"],"a":0},{"c":7,"q":"À quoi ressemblent les expectorations de l'OAP ?","x":"Quintes de toux ramenant des expectorations abondantes, mousseuses, rappelant le blanc d'œuf battu.","mn":"OAP = Œufs battus.","kid":"Il crache une mousse blanche comme quand on bat un blanc d'œuf.","t":"qcm","o":["Mousseuses, rappelant le blanc d'œuf battu","Rouillées","Purulentes verdâtres","Noires"],"a":0},{"c":7,"q":"Quel débit d'oxygène le cours préconise-t-il dans l'OAP ?","x":"Traitement : position assise jambes pendantes, diurétique IV (Lasilix), dérivés nitrés, oxygénothérapie à fort débit (6 l/mn).","mn":"OAP = 6 litres.","kid":"Dans l'OAP, on donne beaucoup d'oxygène.","t":"qcm","o":["Fort débit, 6 l/min","0,5 l/min","1 l/min","Pas d'oxygène"],"a":0},{"c":7,"q":"Dans l'OAP, l'auscultation retrouve des râles crépitants diffus « en marée montante » et un bruit de galop.","x":"Pulmonaire : râles crépitants diffus comme une marée montante ; cardiaque : tachycardie avec bruit de galop.","mn":"Marée montante + galop.","kid":"L'eau monte dans les poumons comme la mer qui monte.","t":"vf","v":1},{"c":7,"q":"Les perfusions et transfusions trop abondantes et trop rapides ne peuvent pas provoquer d'OAP.","x":"Surcharge volémique = cause iatrogène d'OAP.","mn":"Trop vite, trop plein = OAP.","kid":"Si on remplit trop vite les tuyaux, l'eau déborde dans les poumons.","t":"vf","v":0},{"c":7,"q":"Quel paramètre urinaire l'infirmier recueille-t-il pour apprécier l'effet des diurétiques dans l'OAP ?","x":"Recueillir les urines émises et noter la diurèse permet d'apprécier l'effet des diurétiques.","mn":"Diurétique → Diurèse.","kid":"On mesure combien il fait pipi pour voir si le médicament marche.","t":"open","r":"La diurèse","acc":["La diurèse","diurese","volume urinaire","quantite d urines","diurese"]},{"c":7,"q":"Quel diagnostic ?","x":"Début brutal nocturne, sensation d'étouffement, orthopnée, expectoration mousseuse et crépitants diffus chez un hypertendu = OAP.","mn":"Nuit + mousse + crépitants = OAP.","kid":"Son cœur fatigué laisse l'eau envahir ses poumons pendant la nuit.","s":"M. Y., 62 ans, hypertendu, se réveille la nuit en étouffant, assis au bord du lit, polypnéique, crachant une mousse blanche. Crépitants aux deux bases.","t":"qcm","o":["Œdème aigu du poumon","Crise d'asthme","PFLA","Embolie pulmonaire"],"a":0},{"c":7,"q":"Quelle installation l'infirmier réalise-t-il ?","x":"Placer le malade en position assise, ½ assise jambes pendantes : réduit le retour veineux et soulage les poumons.","mn":"Jambes pendantes = moins d'eau vers le cœur.","kid":"En laissant pendre les jambes, le sang reste en bas et le cœur souffle.","s":"Un patient en OAP arrive aux urgences.","t":"qcm","o":["Position assise ou ½ assise, jambes pendantes","Décubitus dorsal strict, jambes surélevées","Position de Trendelenburg","Décubitus latéral gauche à plat"],"a":0},{"c":8,"q":"Quel pourcentage de cancers bronchiques est lié au tabac selon le cours ?","x":"80 à 90 % des cancers bronchiques sont liés au tabac ; 20 % des cancers des non-fumeurs sont liés au tabagisme passif.","mn":"8 à 9 sur 10 = tabac.","kid":"Presque tous les cancers du poumon viennent de la cigarette.","t":"qcm","o":["80 à 90 %","10 à 20 %","30 %","50 %"],"a":0},{"c":8,"q":"Quel est le signe le plus précoce et principal du cancer bronchique ?","x":"Une toux persistante, principal signe et le plus précoce, rebelle aux traitements.","mn":"Toux qui ne passe pas chez un fumeur = alerte.","kid":"Une toux qui ne guérit jamais chez un fumeur doit faire peur.","t":"qcm","o":["Une toux persistante rebelle","Une hématurie","Un ictère","Des œdèmes des membres inférieurs"],"a":0},{"c":8,"q":"À quoi est due la dysphonie dans le cancer bronchopulmonaire ?","x":"Modification de la voix ou dysphonie due à une compression du nerf récurrent.","mn":"Voix cassée = nerf récurrent comprimé.","kid":"La tumeur appuie sur le petit nerf qui commande la voix.","t":"qcm","o":["À la compression du nerf récurrent","À une laryngite virale","À la toux sèche","À une hypocalcémie"],"a":0},{"c":8,"q":"À tabagisme égal, le risque de cancer bronchique est plus élevé chez la femme que chez l'homme.","x":"Le cours le précise explicitement.","mn":"Femme + tabac = risque majoré.","kid":"Pour la même quantité de cigarettes, les femmes risquent plus.","t":"vf","v":1},{"c":8,"q":"Le diagnostic de cancer bronchique repose uniquement sur l'ECG.","x":"L'ECG n'explore pas les bronches.","mn":"Radio – Scanner – Fibro.","kid":"Pour voir la tumeur, on fait des photos des poumons et on regarde dans les bronches avec une caméra.","t":"vf","v":0},{"c":8,"q":"Quel examen permet de visualiser directement l'intérieur des bronches dans le cancer bronchique ?","x":"La fibroscopie bronchique fait partie des examens paracliniques avec radiographie et scanner.","mn":"Fibro = caméra dans les bronches.","kid":"On passe un tuyau fin avec une caméra pour regarder dans les bronches.","t":"open","r":"Fibroscopie bronchique","acc":["Fibroscopie bronchique","fibroscopie","bronchoscopie","fibroscopie"]},{"c":8,"q":"Que doit-on suspecter selon le cours ?","x":"Signe de suspicion : altération de l'état général chez un grand fumeur.","mn":"AEG + fumeur = cancer jusqu'à preuve du contraire.","kid":"Il fume beaucoup, maigrit et tousse : il faut chercher une tumeur.","s":"M. N., 58 ans, grand fumeur, présente depuis 2 mois une altération de l'état général, un amaigrissement inexpliqué et une toux rebelle.","t":"qcm","o":["Un cancer bronchopulmonaire","Une bronchite aiguë virale","Un asthme allergique","Un OAP"],"a":0},{"c":8,"q":"Quels soins de support le cours prévoit-il ?","x":"Soins de support : prise en charge globale et pluridisciplinaire : accompagnement psychologique du patient et de l'entourage, douleur, dyspnée, dénutrition.","mn":"Soutien = Psy + Douleur + Dyspnée + Dénutrition.","kid":"On l'aide à moins souffrir, à mieux respirer, à manger et on la soutient.","s":"Mme K., traitée pour cancer bronchopulmonaire, est dénutrie, dyspnéique et douloureuse.","t":"qcm","o":["Accompagnement psychologique, lutte contre la douleur, la dyspnée et la dénutrition","Arrêt de toute alimentation","Uniquement la chirurgie","Isolement respiratoire strict"],"a":0},{"c":9,"q":"Quel est l'agent principal de la tuberculose humaine ?","x":"Mycobacterium tuberculosis hominis ou bacille de Koch, découvert en 1882 ; autres : M. africanum, M. canetti, M. bovis.","mn":"BK = Koch 1882.","kid":"Un microbe très résistant appelé bacille de Koch.","t":"qcm","o":["Mycobacterium tuberculosis (bacille de Koch)","Streptococcus pneumoniae","Haemophilus influenzae","Escherichia coli"],"a":0},{"c":9,"q":"Quelle coloration met en évidence le bacille tuberculeux ?","x":"Les mycobactéries sont visibles après coloration de Ziehl-Nielsen : non décolorées par l'alcool et l'acide (BAAR).","mn":"Ziehl = BAAR.","kid":"On colore en rouge et le microbe garde la couleur même lavé à l'acide.","t":"qcm","o":["Ziehl-Nielsen","Gram","May-Grünwald-Giemsa","Encre de Chine"],"a":0},{"c":9,"q":"Quelle est la durée de la quadrithérapie dans le traitement de la tuberculose maladie ?","x":"Quadrithérapie (INH, RMP, EMB, PZA) pendant 2 mois puis bithérapie INH + RMP 4 à 10 mois (6 mois au total si TB pulmonaire).","mn":"2 mois à 4, puis 2 médicaments.","kid":"On prend 4 médicaments pendant 2 mois, puis 2 pendant plusieurs mois.","t":"qcm","o":["2 mois","6 mois","2 semaines","12 mois"],"a":0},{"c":9,"q":"Un examen direct négatif élimine le diagnostic de tuberculose.","x":"L'examen direct manque de sensibilité.","mn":"Négatif ≠ absent.","kid":"Ne pas voir le microbe au microscope ne veut pas dire qu'il n'est pas là.","t":"vf","v":0},{"c":9,"q":"Les antituberculeux se prennent en une prise le matin à jeun.","x":"Le cours précise : en une prise le matin à jeun.","mn":"Matin à jeun, tous les jours.","kid":"On les avale tous ensemble le matin avant de manger.","t":"vf","v":1},{"c":9,"q":"Quelle vitamine prévient la neuropathie périphérique due à l'isoniazide ?","x":"Vitamine B6 en prévention de la neuropathie périphérique causée par l'isoniazide chez les patients à risque.","mn":"INH → B6.","kid":"Une vitamine protège les nerfs abîmés par l'isoniazide.","t":"open","r":"Vitamine B6","acc":["Vitamine B6","B6","pyridoxine","b6"]},{"c":9,"q":"Quels prélèvements prévoir ?","x":"Si suspicion de TBC pulmonaire : 3 prélèvements 3 jours consécutifs des expectorations matinales ; LBA ou aspiration fibroscopique si expectorations négatives.","mn":"3 jours, 3 crachats, à jeun.","kid":"On recueille les crachats du matin trois jours de suite.","s":"M. O., 35 ans, VIH+, tousse depuis 6 semaines, maigrit, a des sueurs. Le médecin suspecte une tuberculose pulmonaire.","t":"qcm","o":["Expectorations matinales 3 jours consécutifs, à jeun","Une seule miction en fin d'après-midi","Une hémoculture unique","Une ponction lombaire systématique"],"a":0},{"c":9,"q":"Quelle interprétation et conduite ?","x":"Surveillance de l'observance : couleur des urines avec la rifampicine ; tolérance : allergie, hépatotoxicité (transaminases), troubles visuels (éthambutol).","mn":"Rifampicine = urines Rouge-orangé.","kid":"Le médicament colore le pipi, c'est normal : ça prouve qu'il est pris.","s":"Une patiente sous rifampicine signale des urines orangées.","t":"qcm","o":["C'est un signe d'observance normale ; rassurer et continuer le traitement","Arrêter immédiatement le traitement","C'est une hématurie à traiter en urgence","Doubler les doses"],"a":0},{"c":10,"q":"Que permet de savoir le test tuberculinique ?","x":"Ce sont des réactions cutanées qui permettent de savoir si un individu a déjà été en contact avec le BK ou pas.","mn":"IDR = Contact, pas forcément maladie.","kid":"Le test montre si le corps a déjà rencontré le microbe.","t":"qcm","o":["Si un individu a déjà été en contact avec le BK","Si un individu a une tuberculose active contagieuse","Le groupe sanguin","La fonction rénale"],"a":0},{"c":10,"q":"Quelle dose de tuberculine est injectée et où ?","x":"Injecter la dose recommandée soit 10 unités internationales en intradermique à la face antéro-externe de l'avant-bras.","mn":"10 UI, ID, avant-bras.","kid":"On pique tout juste sous la peau de l'avant-bras.","t":"qcm","o":["10 UI en intradermique à la face antéro-externe de l'avant-bras","1 ml en IM dans le deltoïde","10 UI en sous-cutané abdominal","5 ml en IV"],"a":0},{"c":10,"q":"Quand se fait de préférence la lecture de l'IDR ?","x":"La lecture se fait entre le 2e et le 4e jour, de préférence à la 72e heure, en mesurant l'induration dans son diamètre transversal.","mn":"72 h = 3 jours.","kid":"On regarde le bras trois jours après.","t":"qcm","o":["À la 72e heure","Après 15 minutes","Au 10e jour","Après 6 heures"],"a":0},{"c":10,"q":"La réaction tuberculinique est positive en présence d'un nodule érythémateux d'au moins 5 mm de diamètre.","x":"Positive : nodule érythémateux ≥ 5 mm ; négative : simple rougeur sans infiltration ou induration inférieure au diamètre exigé.","mn":"5 mm d'induration.","kid":"Si la bosse dure fait au moins 5 mm, c'est positif.","t":"vf","v":1},{"c":10,"q":"La lecture de l'IDR se fait en mesurant la rougeur.","x":"C'est l'induration qui compte, pas l'érythème.","mn":"On palpe, on ne regarde pas.","kid":"On mesure la partie dure qu'on sent avec le doigt, pas la couleur.","t":"vf","v":0},{"c":10,"q":"Une IDR positive signifie que le sujet a été en contact avec le BK ou qu'il a reçu quel vaccin ?","x":"L'IDR positive signifie que le sujet a été en contact avec le BK ou a été vacciné au BCG.","mn":"BCG = faux contact.","kid":"Le vaccin apprend au corps à reconnaître le microbe, donc le test réagit aussi.","t":"open","r":"BCG","acc":["BCG","vaccin BCG","le BCG","bcg"]},{"c":10,"q":"Que rappelle le cours ?","x":"N.B. : possibilité de négativation temporaire dans les semaines suivant une maladie infectieuse virale ou une vaccination par vaccin à virus vivant.","mn":"Rougeole = IDR muette.","kid":"Après une grosse maladie, le corps peut ne pas réagir pendant un moment.","s":"Une infirmière lit une IDR chez un enfant ayant eu la rougeole il y a 2 semaines : induration nulle.","t":"qcm","o":["Une négativation temporaire est possible après une maladie virale ou un vaccin vivant","Le résultat est forcément définitif","Il faut relire l'IDR à 15 minutes","Une rougeole rend toujours l'IDR positive"],"a":0},{"c":10,"q":"Que signifie cet aspect ?","x":"La distension des pores de la peau provoque une peau d'orange : signe d'une injection intradermique correcte (biseau vers le haut, 15°).","mn":"Peau d'orange = bonne IDR.","kid":"La petite bulle sous la peau montre que le produit est au bon endroit.","s":"Lors de l'injection de tuberculine, l'étudiant voit apparaître un aspect de peau d'orange.","t":"qcm","o":["L'injection est bien intradermique","L'injection est sous-cutanée, à refaire","C'est une réaction allergique grave","Le produit est périmé"],"a":0},{"c":11,"q":"Selon l'OMS (cours), l'HTA est définie par :","x":"HTA = PAS ≥ 140 mmHg et/ou PAD ≥ 90 mmHg chez un sujet au cours de deux consultations différentes au moins.","mn":"14/9 à deux reprises.","kid":"Quand la tension est trop forte (14/9 ou plus) à deux visites différentes.","t":"qcm","o":["PAS ≥ 140 mmHg et/ou PAD ≥ 90 mmHg lors d'au moins deux consultations différentes","PAS ≥ 120 et PAD ≥ 80 en une seule mesure","PAS ≥ 160 mmHg uniquement","PAD ≥ 110 mmHg uniquement"],"a":0},{"c":11,"q":"Quelle proportion des HTA est primaire (essentielle) selon le cours ?","x":"L'HTA primaire, encore appelée essentielle, représente 90 % des cas ; l'HTA secondaire résulte d'une maladie ou d'un médicament.","mn":"Essentielle = 9 sur 10.","kid":"Dans la plupart des cas, on ne trouve pas une cause unique.","t":"qcm","o":["90 %","10 %","50 %","25 %"],"a":0},{"c":11,"q":"Combien de temps le patient doit-il être au repos avant la mesure de la PA selon le cours ?","x":"Le patient doit être au repos assis ou couché pendant au moins 10 minutes et à distance des repas/excitants (café, tabac) 30 min avant.","mn":"10 min de repos, 30 min sans café/tabac.","kid":"On le laisse se calmer 10 minutes avant de mesurer.","t":"qcm","o":["Au moins 10 minutes","2 minutes","1 heure","Aucun repos nécessaire"],"a":0},{"c":11,"q":"Lequel est un signe fonctionnel d'HTA cité dans le cours ?","x":"Signes fonctionnels : céphalées occipitales matinales, acouphènes, phosphènes (mouches volantes), pollakiurie nocturne.","mn":"HTA : tête (céphalées), oreilles (acouphènes), yeux (mouches).","kid":"La tension trop forte donne mal à l'arrière de la tête le matin.","t":"qcm","o":["Céphalées occipitales matinales","Douleur rétrosternale constrictive à l'effort","Expectoration mousseuse","Ictère"],"a":0},{"c":11,"q":"L'HTA retentit sur trois organes nobles : le cœur, le cerveau et les reins.","x":"Complications sur le cœur (HVG, IVG, angor, IDM), le cerveau (AIT, AVC) et les reins.","mn":"CCR : Cœur, Cerveau, Reins.","kid":"La tension trop forte abîme le cœur, le cerveau et les reins.","t":"vf","v":1},{"c":11,"q":"L'accident ischémique transitoire se manifeste par un déficit neurologique permanent de plus de 24 heures.","x":"AIT = transitoire, AVC = permanent.","mn":"T de Transitoire = Temporaire.","kid":"Dans l'AIT, le bras ne marche plus quelques minutes puis ça revient.","t":"vf","v":0},{"c":11,"q":"Quel examen de rôle propre l'IDE réalise-t-il pour surveiller protéinurie et hématurie chez l'hypertendu ?","x":"L'IDE effectuera une bandelette urinaire (rôle propre) pour surveiller la protéinurie et l'hématurie (répercussions rénales).","mn":"BU = rein surveillé.","kid":"On trempe une petite bande dans le pipi pour voir s'il y a des protéines ou du sang.","t":"open","r":"Bandelette urinaire","acc":["Bandelette urinaire","bandelette","BU","labstix","bandelette"]},{"c":11,"q":"Que suspecter selon le cours ?","x":"Reconnaître un AVC : faire sourire (déviation de la bouche), répéter une phrase, lever les deux bras puis les jambes (difficulté).","mn":"Sourire – Parler – Lever les bras.","kid":"Le cerveau ne commande plus une moitié du corps : il faut appeler vite.","s":"Pendant une consultation, un hypertendu de 65 ans présente brutalement une déviation de la bouche et ne parvient pas à lever le bras droit.","t":"qcm","o":["Un AVC","Une crise d'angor","Un OAP","Une hypoglycémie certaine"],"a":0},{"c":11,"q":"Quelles mesures non médicamenteuses le cours propose-t-il ?","x":"Hygiène de vie : réduction pondérale, réduction du sel et des graisses, arrêt tabac, activité physique ; éducation à l'automesure et au suivi.","mn":"Moins de Sel, de Poids, de Tabac ; plus de Sport.","kid":"Il doit manger moins salé, perdre du poids et bouger.","s":"M. G., 50 ans, obèse, fumeur, découvre une HTA grade 1.","t":"qcm","o":["Réduction pondérale, réduction du sel, arrêt du tabac, activité physique, suivi régulier","Régime riche en sel","Arrêter toute consultation","Augmenter l'alcool"],"a":0},{"c":12,"q":"Quelle est l'origine des varices selon le cours ?","x":"Les clapets valvulaires sont anti-reflux ; leur altération est à l'origine des insuffisances veineuses ou varices.","mn":"Clapets cassés → sang qui redescend.","kid":"Les petites portes dans les veines ne ferment plus et le sang stagne dans les jambes.","t":"qcm","o":["L'altération des clapets valvulaires des veines","Une plaque d'athérome artérielle","Une infection bactérienne","Un caillot dans l'artère pulmonaire"],"a":0},{"c":12,"q":"Quel est le signe fonctionnel typique de l'insuffisance veineuse ?","x":"Sensation de jambes lourdes avec œdème vespéral, crampes, paresthésies nocturnes, douleurs majorées par l'orthostatisme et la chaleur.","mn":"Veines = soir lourd.","kid":"Le soir, les jambes sont lourdes et gonflées.","t":"qcm","o":["Jambes lourdes avec œdème vespéral","Claudication intermittente","Douleur rétrosternale","Hématurie"],"a":0},{"c":12,"q":"Quel est le principe de la contention veineuse ?","x":"Bas ou collants exerçant une pression sur les jambes pour stimuler le retour du sang et pallier l'insuffisance des clapets.","mn":"Serrer pour remonter.","kid":"Les bas serrés aident le sang à remonter vers le cœur.","t":"qcm","o":["Exercer une pression sur les jambes pour stimuler le retour veineux","Dilater les artères","Dissoudre les caillots","Augmenter la diurèse"],"a":0},{"c":12,"q":"Pour prévenir l'insuffisance veineuse, il faut éviter les vêtements trop serrés, la station debout prolongée et élever les membres au repos.","x":"Prévention : éviter l'orthostatisme prolongé, vêtements serrés, talons trop hauts ; marche, natation ; élever les membres ; éviter pilule + tabac.","mn":"Bouger, surélever, desserrer.","kid":"Il faut marcher, nager et mettre les jambes en l'air pour se reposer.","t":"vf","v":1},{"c":12,"q":"La jambite est une complication sans fièvre de l'insuffisance veineuse ne nécessitant jamais d'antibiotique.","x":"La jambite est infectieuse (strepto/staphylocoque).","mn":"Jambite = jambe rouge + fièvre = ATB.","kid":"La jambe devient rouge, chaude, et on a de la fièvre : il faut un antibiotique.","t":"vf","v":0},{"c":12,"q":"Quel examen d'imagerie explore l'insuffisance veineuse des membres inférieurs ?","x":"Examens complémentaires : bilan sanguin standard, échodoppler veineux.","mn":"Doppler = voir le sang couler.","kid":"Une échographie spéciale regarde le sang circuler dans les veines.","t":"open","r":"Échodoppler veineux","acc":["Échodoppler veineux","echodoppler","doppler veineux","echo doppler","doppler"]},{"c":12,"q":"Quels facteurs de risque relève-t-on ?","x":"Facteurs : hérédité, âge, obésité, diabète, grossesse, vêtements serrés, chaussures inadaptées, position debout ou assise prolongée, chaleur.","mn":"Debout + enceinte = varices.","kid":"Rester debout toute la journée et être enceinte fatiguent les veines.","s":"Mme F., 45 ans, coiffeuse debout toute la journée, enceinte de son 3e enfant, se plaint de jambes lourdes le soir.","t":"qcm","o":["Position debout prolongée et grossesse","Tabagisme et diabète uniquement","Aucun","Contraception orale seule"],"a":0},{"c":12,"q":"De quelle complication s'agit-il ?","x":"Complications : jambite, dermite, eczéma, ulcère variqueux.","mn":"Varice + plaie = ulcère variqueux.","kid":"La peau mal nourrie par le sang stagnant finit par s'ouvrir.","s":"M. L., varices anciennes, présente une plaie chronique à la cheville qui ne cicatrise pas.","t":"qcm","o":["Ulcère variqueux","Gangrène sèche artérielle","Phlyctène de brûlure","Érythème noueux"],"a":0},{"c":13,"q":"Comment se définit la thrombose veineuse profonde ?","x":"La TVP est l'oblitération plus ou moins complète d'une veine profonde par un thrombus résultant d'une coagulation intravasculaire localisée.","mn":"TVP = caillot dans la veine profonde.","kid":"Un bouchon de sang se forme dans une grosse veine de la jambe.","t":"qcm","o":["Oblitération plus ou moins complète d'une veine profonde par un thrombus","Obstruction d'une artère par une plaque d'athérome","Dilatation d'une veine superficielle","Inflammation de la plèvre"],"a":0},{"c":13,"q":"Comment s'appelle la douleur du mollet provoquée par la dorsiflexion du pied ?","x":"Douleurs du mollet provoquées par la dorsiflexion du pied : c'est le signe de Homans.","mn":"Homans = Hausser le pied.","kid":"Quand on relève le pied vers le genou, le mollet fait mal.","t":"qcm","o":["Signe de Homans","Signe de Murphy","Signe de Harzer","Signe de Kussmaul"],"a":0},{"c":13,"q":"Quel examen biologique domine le bilan de la TVP ?","x":"Bilan sanguin dominé par les D-dimères ; dosage protéines C et S, antithrombine III ; échodoppler veineux.","mn":"D-dimères = débris de caillot.","kid":"On cherche dans le sang des petits morceaux de caillot.","t":"qcm","o":["Les D-dimères","La lipasémie","La bilirubine","La glycosurie"],"a":0},{"c":13,"q":"Devant une TVP, l'infirmier impose un repos strict au lit, les membres inférieurs surélevés.","x":"Prévenir l'extension et la migration : repos strict au lit, membres inférieurs surélevés ; éviter la marche.","mn":"Repos + jambes en l'air.","kid":"On garde la jambe au repos et en hauteur pour que le caillot ne parte pas.","t":"vf","v":1},{"c":13,"q":"L'œdème de la TVP est mou, bilatéral et prend le godet.","x":"TVP = œdème unilatéral dur.","mn":"TVP : une seule jambe, dure.","kid":"Une seule jambe gonfle et elle est dure.","t":"vf","v":0},{"c":13,"q":"Quel examen biologique (en plus du TP) surveille l'efficacité des AVK ?","x":"Surveillance biologique : TP, TCA, anti-Xa, INR, NFS, plaquettes ; éducation sur le rôle du TP et de l'INR.","mn":"AVK = INR.","kid":"On mesure un chiffre dans le sang pour savoir si le sang est assez fluide.","t":"open","r":"INR","acc":["INR","l INR","international normalized ratio","inr"]},{"c":13,"q":"Quel diagnostic évoquer ?","x":"Facteurs : voyage > 3 h, contraception orale, tabac ; signes : douleur, chaleur, œdème unilatéral.","mn":"Avion + pilule + mollet = TVP.","kid":"Rester assise longtemps a fait se former un caillot dans la jambe.","s":"Mme R., 32 ans, fumeuse sous pilule, revient d'un vol de 9 heures. Son mollet gauche est douloureux, chaud, augmenté de volume.","t":"qcm","o":["Thrombose veineuse profonde","Insuffisance veineuse simple","AOMI stade II","Érysipèle"],"a":0},{"c":13,"q":"Quelle conduite infirmière ?","x":"Surveillance générale des risques hémorragiques : épistaxis, gingivorragie, hématomes spontanés, méléna, hématurie.","mn":"Saignement sous AVK = INR !","kid":"Le sang est devenu trop fluide : il faut vérifier la prise de sang et prévenir le médecin.","s":"M. P., sous AVK pour TVP, signale des saignements de gencives et des hématomes spontanés.","t":"qcm","o":["Évoquer un surdosage : prévenir le médecin et contrôler TP/INR","Augmenter la dose d'AVK","Masser les hématomes","Ignorer, c'est normal"],"a":0},{"c":14,"q":"Comment se définit l'AOMI ?","x":"L'AOMI est l'obstruction de la lumière de l'artère du membre inférieur par une plaque d'athérome, réduisant le flux sanguin et l'oxygène.","mn":"AOMI = Athérome Obstrue le MI.","kid":"Du gras bouche le tuyau qui amène le sang à la jambe.","t":"qcm","o":["Obstruction de la lumière d'une artère du membre inférieur par une plaque d'athérome","Thrombus dans une veine profonde","Dilatation des veines superficielles","Inflammation de la plèvre"],"a":0},{"c":14,"q":"Quel stade de Leriche et Fontaine correspond à la claudication intermittente ?","x":"Stade I latence ; II claudication intermittente ; III douleurs de repos ; IV troubles trophiques.","mn":"I silence, II marche, III repos, IV plaie.","kid":"Au stade 2, la jambe fait mal quand on marche et ça passe à l'arrêt.","t":"qcm","o":["Stade II","Stade I","Stade III","Stade IV"],"a":0},{"c":14,"q":"Comment l'infirmier installe-t-il un patient souffrant d'AOMI ?","x":"Installer le patient jambe pendante (favorise l'arrivée du sang artériel) ; au stade III le patient garde spontanément le pied pendant hors du lit.","mn":"Artère = pendre ; veine = surélever.","kid":"On laisse la jambe pendre pour que le sang descende plus facilement.","t":"qcm","o":["Jambe pendante","Jambes surélevées","Décubitus ventral","Position de Trendelenburg"],"a":0},{"c":14,"q":"Dans la claudication intermittente, la douleur cède en 1 à 3 minutes après l'arrêt de la marche.","x":"Douleurs provoquées par une marche d'environ 200 à 500 m (périmètre de marche), cessant après arrêt en 1 à 3 min.","mn":"Marche → crampe → arrêt → ça passe.","kid":"Après quelques centaines de mètres, le mollet fait une crampe ; on s'arrête et ça passe.","t":"vf","v":1},{"c":14,"q":"L'âge ≥ 50 ans, le tabagisme et le diabète sont des facteurs de risque de l'AOMI.","x":"Facteurs de risque cités : tabagisme, diabète, âge ≥ 50 ans.","mn":"TDA : Tabac, Diabète, Âge.","kid":"Fumer, avoir du sucre dans le sang et vieillir abîment les artères.","t":"vf","v":1},{"c":14,"q":"Citez la complication majeure de l'AOMI au stade IV, pouvant être sèche ou infectée.","x":"Stade IV : troubles trophiques (peau sèche, ulcérations, gangrène sèche ou infectée) ; complications : gangrène, occlusion artérielle aiguë, embolie de cholestérol.","mn":"IV = gangrène.","kid":"Sans sang, les tissus meurent et noircissent.","t":"open","r":"Gangrène","acc":["Gangrène","la gangrene","gangrene seche","gangrene"]},{"c":14,"q":"À quel stade est son AOMI ?","x":"Stade III : douleurs permanentes, au repos, souvent la nuit, obligeant à garder le pied pendant hors du lit.","mn":"III = douleur nocturne de repos.","kid":"Même allongé, le pied manque de sang et fait mal.","s":"M. D., 66 ans, fumeur et diabétique, se réveille la nuit à cause de douleurs du pied et dort le pied pendant hors du lit.","t":"qcm","o":["Stade III (douleurs de repos)","Stade I","Stade II","Ce n'est pas une AOMI"],"a":0},{"c":14,"q":"Que recherche l'examen clinique selon le cours ?","x":"Examen bilatéral et comparatif : palpation des pouls pédieux, poplité, tibial ; chaleur locale (dos de la main) ; auscultation des trajets artériels (souffle systolique).","mn":"Pouls abolis + souffle.","kid":"On cherche si le sang bat encore dans les artères du pied.","s":"À l'examen d'un patient suspect d'AOMI, l'infirmier assiste le médecin.","t":"qcm","o":["Pouls pédieux, poplité et tibial diminués ou abolis, souffle systolique, chaleur locale (bilatéral et comparatif)","Signe de Homans","Matité thoracique","Reflux hépato-jugulaire"],"a":0},{"c":15,"q":"Quel est le point de départ habituel de l'embolie pulmonaire ?","x":"L'EP est l'oblitération brutale de l'artère pulmonaire ou d'une branche par un corps étranger circulant, dont le point de départ habituel est une TVP des MI.","mn":"Phlébite → embolie.","kid":"Un caillot de la jambe remonte jusqu'au poumon.","t":"qcm","o":["Une thrombose veineuse profonde des membres inférieurs","Une plaque d'athérome coronaire","Un ulcère gastrique","Une lithiase urinaire"],"a":0},{"c":15,"q":"Quel est le signe dominant de l'embolie pulmonaire ?","x":"Signes dominés par une douleur à type de point de côté basithoracique, brutale, majorée à l'inspiration, avec toux, crachats hématiques, dyspnée, angoisse.","mn":"EP = point de côté brutal + dyspnée.","kid":"D'un coup, une douleur dans la poitrine et on n'arrive plus à respirer.","t":"qcm","o":["Douleur thoracique type point de côté, brutale, augmentée à l'inspiration","Céphalées occipitales","Claudication intermittente","Ictère"],"a":0},{"c":15,"q":"Comment s'appelle l'ablation chirurgicale de l'embole sous circulation extracorporelle ?","x":"Traitement chirurgical : ablation de l'embole sous CEC, c'est l'embolectomie.","mn":"Embol-ectomie = enlever l'embole.","kid":"Le chirurgien retire le caillot du poumon.","t":"qcm","o":["Embolectomie","Thrombolyse","Pontage","Coronaroplastie"],"a":0},{"c":15,"q":"Le liquide amniotique et l'air peuvent constituer un embole.","x":"Nature de l'embole : caillot, plaque d'athérome, gaz (air), liquide amniotique (embolie amniotique).","mn":"Caillot, Gras, Gaz, Liquide.","kid":"Le bouchon peut être du sang, du gras, de l'air ou du liquide de la poche des eaux.","t":"vf","v":1},{"c":15,"q":"Dans l'embolie pulmonaire, la pression artérielle est toujours élevée.","x":"L'hypotension est un signe de gravité.","mn":"EP grave = PA basse.","kid":"Si le caillot est gros, la tension peut chuter.","t":"vf","v":0},{"c":15,"q":"Quel examen d'imagerie confirme l'embolie pulmonaire dans le bilan spécifique ?","x":"Bilan spécifique : gazométrie, D-dimères, protéines C/S, radio, ECG, échodoppler veineux, angioscanner pulmonaire.","mn":"Angio = voir les vaisseaux.","kid":"Un scanner avec produit montre le caillot dans l'artère du poumon.","t":"open","r":"Angioscanner pulmonaire","acc":["Angioscanner pulmonaire","angioscanner","angio-scanner thoracique","angiocanner pulmonaire","angioscanner","angiocanner","angio"]},{"c":15,"q":"Quel diagnostic ?","x":"Post-opératoire orthopédique (risque de TVP) + point de côté brutal + dyspnée + tachycardie + crachats hématiques = EP.","mn":"Opérée + point de côté brutal = EP.","kid":"Un caillot de la jambe opérée est monté dans le poumon.","s":"Mme V., opérée de la hanche il y a 5 jours, présente brutalement une douleur basithoracique droite majorée à l'inspiration, une dyspnée, une tachycardie et des crachats striés de sang.","t":"qcm","o":["Embolie pulmonaire","PFLA","Angor stable","Pneumothorax spontané du jeune"],"a":0},{"c":15,"q":"Quelle surveillance biologique est spécifique ?","x":"Surveiller les plaquettes 2 fois par semaine (200 000 à 400 000/mm³) ; HBPM agissent sur le facteur Xa → doser l'anti-Xa ; risques : thrombopénie, hémorragie.","mn":"Héparine = Plaquettes.","kid":"On compte les plaquettes car l'héparine peut les faire baisser.","s":"M. B., sous HBPM (Lovenox) pour embolie pulmonaire, est en J7.","t":"qcm","o":["Plaquettes 2 fois par semaine (risque de thrombopénie) et anti-Xa","Lipasémie quotidienne","Glycosurie","Calcémie seule"],"a":0},{"c":16,"q":"Selon le chapitre cardiologique, l'OAP est la conséquence de :","x":"L'OAP est la conséquence de la diffusion de liquide plasmatique dans les espaces extravasculaires du poumon, consécutive à une hyperpression capillaire pulmonaire ou à une lésion de la membrane alvéolo-capillaire (selon p. 82 ; la p. 44 le définit comme une insuffisance cardiaque gauche aiguë).","mn":"Pression ou lésion → plasma dehors.","kid":"L'eau des vaisseaux sort et envahit le poumon.","t":"qcm","o":["La diffusion de liquide plasmatique dans les espaces extravasculaires du poumon par hyperpression capillaire ou lésion de la membrane","Une obstruction de l'artère pulmonaire","Une infection pleurale","Une dilatation des bronches"],"a":0},{"c":16,"q":"Comment débute classiquement l'OAP cardiogénique ?","x":"Début souvent brutal et nocturne, précédé de grésillements laryngés et de toux irritative ; polypnée obligeant le patient à s'asseoir.","mn":"Nuit + gorge qui grésille.","kid":"La nuit, la gorge chatouille, puis on étouffe et on doit s'asseoir.","t":"qcm","o":["Brutalement, la nuit, précédé de grésillements laryngés et de toux irritative","Progressivement sur des mois","Par une fièvre à 40 °C","Par une claudication"],"a":0},{"c":16,"q":"Quel soluté le cours interdit-il de passer chez un patient en OAP ?","x":"Prendre une voie veineuse de gros calibre pour passer un soluté (pas de sérum salé isotonique) : le sel aggrave la rétention hydrique.","mn":"OAP : pas de sel.","kid":"Le sel garde l'eau dans le corps et noierait encore plus les poumons.","t":"qcm","o":["Le sérum salé isotonique","Le sérum glucosé","Aucun soluté","Le Ringer lactate uniquement"],"a":0},{"c":16,"q":"L'expectoration de l'OAP peut être saumonée ou hémoptoïque.","x":"Expectoration mousseuse abondante blanche comme un blanc d'œuf battu, parfois teintée de sang (saumonée ou hémoptoïque).","mn":"Mousse rosée possible.","kid":"La mousse peut devenir un peu rose à cause du sang.","t":"vf","v":1},{"c":16,"q":"La crise d'asthme n'est jamais un diagnostic différentiel de l'OAP.","x":"Les deux donnent une dyspnée aiguë.","mn":"Asthme cardiaque vs asthme bronchique.","kid":"Les deux font étouffer : il faut demander les antécédents.","t":"vf","v":0},{"c":16,"q":"Quel dispositif l'infirmier met-il en place pour surveiller précisément la diurèse dans l'OAP (citez-en un) ?","x":"Mettre en place une sonde vésicale à demeure ou un péniflow pour surveiller la diurèse sous diurétiques.","mn":"Diurèse précise = sonde.","kid":"On met un tuyau pour mesurer exactement le pipi.","t":"open","r":"Sonde vésicale à demeure","acc":["Sonde vésicale à demeure","sonde urinaire","penilex","peniflow","sonde vesicale","sonde","peniflow"]},{"c":16,"q":"Quelle est la première installation et quelles actions ?","x":"Rôle infirmier : ½ assis jambes pendantes, repos strict, prescriptions, PA, oxygène, VVP gros calibre (pas de sérum salé), prélèvements (gaz, enzymes, TP…), sonde vésicale, ECG.","mn":"Assis – O2 – Veine – ECG – Sonde.","kid":"On l'assoit jambes pendantes, on lui donne de l'oxygène et on prépare tout pour le médecin.","s":"M. E., 70 ans, cardiaque, arrive en OAP avec PA 190/110.","t":"qcm","o":["Position ½ assise jambes pendantes, repos strict, O2, VVP gros calibre, prélèvements, ECG","Décubitus à plat et remplissage au sérum salé","Marche immédiate","Attendre sans voie veineuse"],"a":0},{"c":16,"q":"À quoi correspondent ces signes ?","x":"L'inspection note une dyspnée à type de polypnée avec battement des ailes du nez et sueurs abondantes.","mn":"Ailes du nez = lutte respiratoire.","kid":"Le nez bouge très fort parce qu'il a du mal à respirer.","s":"Lors d'un OAP, l'infirmier observe un battement des ailes du nez et des sueurs abondantes.","t":"qcm","o":["Signes d'inspection de la polypnée intense de l'OAP","Signes d'hypoglycémie isolée","Signes normaux sans valeur","Signes de déshydratation"],"a":0},{"c":17,"q":"Comment se définit l'IVG ?","x":"IVG : incapacité du ventricule gauche à assurer un débit sanguin nécessaire aux besoins métaboliques et fonctionnels de l'organisme, en cas d'effort puis au repos.","mn":"VG fatigué = débit insuffisant.","kid":"La pompe gauche du cœur n'envoie plus assez de sang.","t":"qcm","o":["Incapacité du VG à assurer le débit nécessaire aux besoins de l'organisme, à l'effort puis au repos","Élévation de la pression veineuse centrale > 15 cm d'eau","Inflammation du péricarde","Obstruction coronaire complète"],"a":0},{"c":17,"q":"Quel est le retentissement en amont de l'IVG ?","x":"En amont, les veines pulmonaires drainent mal vers l'OG : les poumons sont inondés, d'où la dyspnée ; en aval, hypoperfusion (oligurie).","mn":"Gauche = poumons.","kid":"Le sang reste bloqué dans les poumons, on respire mal.","t":"qcm","o":["Stase pulmonaire avec dyspnée","Hépatomégalie isolée","Turgescence jugulaire isolée","Ascite isolée"],"a":0},{"c":17,"q":"Selon la NYHA, une dyspnée permanente de repos correspond au stade :","x":"Stade I : efforts importants inhabituels ; II : efforts importants habituels ; III : efforts peu intenses ; IV : dyspnée permanente de repos.","mn":"NYHA IV = au lit.","kid":"Au stade 4, on est essoufflé même sans bouger.","t":"qcm","o":["IV","I","II","III"],"a":0},{"c":17,"q":"Les diurétiques peuvent entraîner une hypokaliémie et/ou une hypomagnésémie, d'où l'intérêt d'une supplémentation.","x":"N.B. du cours : diurétiques → hypokaliémie/hypomagnésémie → supplémentation.","mn":"Diurétique = perte de K+.","kid":"En faisant beaucoup uriner, on perd aussi du potassium.","t":"vf","v":1},{"c":17,"q":"Dans l'IVG, il est conseillé d'augmenter les excitants comme le thé et le café.","x":"Les excitants accélèrent le cœur.","mn":"IVG = pas d'excitants.","kid":"Le café fait battre le cœur plus vite, il faut l'éviter.","t":"vf","v":0},{"c":17,"q":"Quelle anomalie de la silhouette cardiaque la radiographie montre-t-elle dans l'IVG ?","x":"La radiographie pulmonaire met en évidence une cardiomégalie et des signes d'œdème pulmonaire.","mn":"Gros cœur = cardiomégalie.","kid":"Sur la photo, le cœur paraît trop gros.","t":"open","r":"Cardiomégalie","acc":["Cardiomégalie","cardiomegalie","gros coeur","cardiomegalie"]},{"c":17,"q":"Quel stade NYHA ?","x":"Stade III : dyspnée pour des efforts peu intenses de la vie courante (marche normale en terrain plat, montée de deux étages).","mn":"III = vie courante.","kid":"Elle est essoufflée pour des choses de tous les jours.","s":"Mme H., 60 ans, hypertendue, s'essouffle désormais en marchant normalement sur terrain plat et en montant deux étages.","t":"qcm","o":["Stade III","Stade I","Stade II","Stade IV"],"a":0},{"c":17,"q":"Quelle conduite infirmière est conforme au cours ?","x":"Imposer un repos strict lors des poussées, ½ assis, oxygénothérapie, voie veineuse, prélèvements, ECG, CCC en insistant sur le régime hyposodé.","mn":"IVG : Repos, ½ assis, O2, sans sel.","kid":"On le laisse se reposer assis, avec de l'oxygène, et on lui apprend à manger sans sel.","s":"M. J., en poussée d'IVG, est hospitalisé.","t":"qcm","o":["Repos strict, position ½ assise, O2, VVP, bilans, ECG, CCC sur régime hyposodé","Régime riche en sel","Position couchée à plat","Sport intensif"],"a":0},{"c":18,"q":"Lequel de ces signes est un signe d'hypertension veineuse de l'IVD ?","x":"Signes d'hypertension veineuse : hépatomégalie avec expansion systolique, reflux hépato-jugulaire, turgescence spontanée des jugulaires, oligurie, OMI.","mn":"Droit = Jugulaires + Foie + Jambes.","kid":"Le sang reste bloqué avant le cœur droit : le cou gonfle, le foie grossit, les jambes enflent.","t":"qcm","o":["Reflux hépato-jugulaire","Râles crépitants isolés","Claudication intermittente","Signe de Homans"],"a":0},{"c":18,"q":"Laquelle est une cause d'insuffisance cardiaque droite selon le cours ?","x":"Causes : cœur pulmonaire aigu et chronique, cardiopathie gauche (rétrécissement/insuffisance mitrale), amylose, cardiopathies congénitales (CIA, CIV).","mn":"Poumon malade → cœur droit fatigué.","kid":"Quand les poumons sont abîmés longtemps, le cœur droit s'épuise à pousser.","t":"qcm","o":["Cœur pulmonaire chronique","Ulcère gastrique","Lithiase biliaire","Hépatite A"],"a":0},{"c":18,"q":"Au-delà de quelle valeur de pression veineuse centrale le cours parle-t-il d'IVD ?","x":"L'IVD traduit une élévation de la pression veineuse centrale supérieure à 15 cm d'eau.","mn":"PVC > 15.","kid":"La pression dans les grosses veines devient trop forte.","t":"qcm","o":["15 cm d'eau","5 cm d'eau","30 mmHg","2 cm d'eau"],"a":0},{"c":18,"q":"Dans l'IVD, les hépatalgies peuvent s'accompagner de troubles digestifs (dyspepsie, ballonnements, nausées).","x":"Signes fonctionnels : hépatalgies associées à des troubles digestifs, dyspnée d'effort.","mn":"Foie congestif = ventre gêné.","kid":"Le foie gonflé fait mal et dérange la digestion.","t":"vf","v":1},{"c":18,"q":"Dans l'IVD, l'ECG montre typiquement un bloc de branche gauche.","x":"Droite = bloc de branche droit.","mn":"IVD → BBD.","kid":"Le cœur droit souffrant laisse sa trace côté droit sur l'ECG.","t":"vf","v":0},{"c":18,"q":"Quel signe, perçu à la palpation sous l'appendice xiphoïde, correspond aux battements du VD dilaté ?","x":"Les signes cardiaques de l'IVD comprennent le signe de Harzer, la tachycardie, l'arythmie, le souffle d'insuffisance tricuspidienne, le bruit de galop.","mn":"Harzer = cœur droit sous le sternum.","kid":"On sent le cœur droit battre sous la pointe du sternum.","t":"open","r":"Signe de Harzer","acc":["Signe de Harzer","harzer","signe de harzer","harzer"]},{"c":18,"q":"Quel diagnostic ?","x":"Cœur pulmonaire chronique → IVD : hypertension veineuse (jugulaires, hépatomégalie, OMI).","mn":"BPCO + jugulaires + foie = IVD.","kid":"Ses poumons malades ont fatigué le côté droit de son cœur.","s":"M. Z., BPCO ancien, présente des œdèmes des jambes, un gros foie douloureux et des jugulaires turgescentes.","t":"qcm","o":["Insuffisance ventriculaire droite","IVG isolée","AOMI","Thrombose veineuse profonde"],"a":0},{"c":18,"q":"Quelles classes figurent dans le cours ?","x":"Traitement symptomatique : diurétiques (Lasilix, Burinex, Aldactone), IEC (Lopril, Renitec, enalapril), digitaliques.","mn":"IVD : Diurétique, IEC, Digitalique (3 D/I).","kid":"On fait uriner, on détend les vaisseaux et on aide le cœur à battre plus fort.","s":"Le médecin prescrit un traitement symptomatique de l'IVD.","t":"qcm","o":["Diurétiques (Lasilix, Aldactone), IEC, digitaliques","Antibiotiques seuls","Antituberculeux","Antipaludéens"],"a":0},{"c":19,"q":"L'insuffisance cardiaque globale touche :","x":"L'ICG est l'incapacité du cœur à assurer le débit nécessaire suite à une maladie qui touche les deux ventricules en même temps, mais surtout le ventricule gauche.","mn":"Globale = gauche + droite.","kid":"Les deux pompes du cœur sont fatiguées.","t":"qcm","o":["Les deux ventricules, surtout le gauche","Uniquement l'oreillette droite","Uniquement le péricarde","Uniquement les valves aortiques"],"a":0},{"c":19,"q":"Quel signe traduit un œdème généralisé dans l'ICG ?","x":"Signes : dyspnée de repos, turgescence jugulaire, hépatomégalie douloureuse, œdème généralisé ou anasarque, cyanose, toux avec crachats hématiques, oligo-anurie.","mn":"Anasarque = eau partout.","kid":"Le corps entier gonfle d'eau.","t":"qcm","o":["L'anasarque","L'hippocratisme digital","Le signe de Homans","La claudication"],"a":0},{"c":19,"q":"Lequel est un but du traitement de l'ICG ?","x":"Buts : réduire les besoins en O2 (supprimer l'effort cardiaque), réduire la rétention d'eau et de sel, renforcer la contraction cardiaque.","mn":"Repos, sans sel, cœur plus fort.","kid":"On fait reposer le cœur, on enlève l'eau en trop et on l'aide à pomper.","t":"qcm","o":["Réduire la rétention d'eau et de sel","Augmenter l'effort cardiaque","Augmenter l'apport en sel","Supprimer la contraction cardiaque"],"a":0},{"c":19,"q":"L'ICG associe les signes des insuffisances droite et gauche.","x":"Les signes cliniques associent ceux des insuffisances droites et gauches.","mn":"Globale = tout.","kid":"On a à la fois les poumons pleins et les jambes gonflées.","t":"vf","v":1},{"c":19,"q":"Dans l'ICG, la diurèse est augmentée.","x":"Le débit rénal baisse.","mn":"Cœur faible = peu d'urine.","kid":"Le cœur envoie moins de sang aux reins, donc moins de pipi.","t":"vf","v":0},{"c":19,"q":"Comment appelle-t-on la diminution importante voire l'arrêt de la production d'urine observée dans l'ICG ?","x":"Oligo-anurie : signe d'hypoperfusion rénale dans l'ICG.","mn":"Oligo = peu ; an = pas.","kid":"Le corps fait très peu ou plus du tout de pipi.","t":"open","r":"Oligo-anurie","acc":["Oligo-anurie","oligoanurie","oligurie","anurie","anurie","oligurie"]},{"c":19,"q":"Quel diagnostic ?","x":"Association de signes gauches (dyspnée de repos) et droits (jugulaires, hépatomégalie, anasarque) = ICG.","mn":"Tout le corps gonflé + dyspnée = ICG.","kid":"Les deux côtés du cœur sont fatigués.","s":"Mme W., 75 ans, cardiaque connue, est essoufflée au repos, cyanosée, avec un œdème de tout le corps, un gros foie douloureux et des jugulaires turgescentes.","t":"qcm","o":["Insuffisance cardiaque globale","Embolie pulmonaire","Asthme","Bronchite aiguë"],"a":0},{"c":19,"q":"Quelle mesure infirmière correspond aux buts du traitement ?","x":"Réduire au minimum les besoins en oxygène en supprimant la demande d'effort du muscle cardiaque, réduire la rétention d'eau et de sel.","mn":"Repos + sans sel.","kid":"Le cœur doit se reposer et le corps garder moins d'eau.","s":"Un patient en ICG est hospitalisé.","t":"qcm","o":["Repos au lit pour réduire l'effort cardiaque et régime hyposodé","Marche rapide quotidienne","Perfusion abondante de sérum salé","Supprimer la surveillance de la diurèse"],"a":0},{"c":20,"q":"Comment cède la douleur angineuse ?","x":"La douleur cesse à l'arrêt de l'effort et après trinitrine sublinguale en 1 à 2 minutes : test diagnostique à la trinitrine.","mn":"Angor = cède à la trinitrine.","kid":"Quand on s'arrête ou qu'on met le petit médicament sous la langue, la douleur part vite.","t":"qcm","o":["À l'arrêt de l'effort et en 1 à 2 min après trinitrine sublinguale","Uniquement après 6 heures","Jamais, elle est permanente","Après la prise d'un antibiotique"],"a":0},{"c":20,"q":"Quel est le siège typique de la douleur angineuse ?","x":"Siège médian rétrosternal en barre ; irradiation au membre supérieur gauche, doigts, mâchoires ; type constrictive en étau.","mn":"Barre derrière le sternum.","kid":"Ça serre au milieu de la poitrine comme une ceinture trop serrée.","t":"qcm","o":["Rétrosternal médian, en barre","Fosse iliaque droite","Hypochondre droit","Lombaire unilatéral"],"a":0},{"c":20,"q":"Sur quel terrain survient typiquement l'angine de poitrine selon le cours ?","x":"L'angine de poitrine survient chez un sujet à partir de 50 à 60 ans avec une prédominance masculine.","mn":"Homme de 50-60 ans.","kid":"Ça touche surtout les hommes un peu âgés.","t":"qcm","o":["Sujet de 50 à 60 ans, à prédominance masculine","Enfant de moins de 5 ans","Femme enceinte uniquement","Adolescent sportif"],"a":0},{"c":20,"q":"L'angine de poitrine est liée à une diminution du débit sanguin coronaire par plaque d'athérome.","x":"Physiopathologie : plaque d'athérome dans une coronaire (accumulation de LDL-cholestérol) réduisant l'apport d'O2 au myocarde.","mn":"Athérome coronaire = angor.","kid":"Du gras dans les tuyaux du cœur l'empêche d'avoir assez d'oxygène.","t":"vf","v":1},{"c":20,"q":"L'infarctus du myocarde ne fait pas partie des complications de l'angor.","x":"L'angor peut évoluer vers l'IDM.","mn":"Angor non contrôlé → IDM.","kid":"Si le tuyau finit par se boucher complètement, une partie du cœur meurt.","t":"vf","v":0},{"c":20,"q":"Quel médicament, pris par voie sublinguale, constitue le test diagnostique de l'angor ?","x":"La douleur cesse après une prise sublinguale de trinitrine en 1 à 2 minutes.","mn":"Trinitrine sous la langue.","kid":"Un médicament sous la langue ouvre les tuyaux du cœur.","t":"open","r":"Trinitrine","acc":["Trinitrine","trinitrine sublinguale","derive nitre","natispray","trinitrine","nitre"]},{"c":20,"q":"Que fait l'infirmier selon le cours ?","x":"En centre de santé : accueil, installation, constantes, heure d'arrivée, VVP de bon calibre, antalgique (1 g aspirine ou paracétamol), CCC, adresser à un centre plus qualifié.","mn":"Périphérie : stabiliser puis référer.","kid":"On le soigne d'abord puis on l'envoie à l'hôpital mieux équipé.","s":"M. Q., 58 ans, arrive dans un centre de santé périphérique avec une douleur thoracique d'effort.","t":"qcm","o":["Accueillir, installer, constantes, noter l'heure, VVP, calmer la douleur (1 g aspirine ou paracétamol), CCC puis référer","Le renvoyer à domicile","Lui faire monter les escaliers","Lui donner un antibiotique"],"a":0},{"c":20,"q":"Quelles mesures le cours propose-t-il ?","x":"Prévention : pratique du sport, correction du surpoids, réduction du sel et des graisses, arrêt du tabac.","mn":"Sport, sel ↓, gras ↓, tabac 0.","kid":"Bouger, manger moins gras et salé, arrêter de fumer.","s":"Après un épisode d'angor, M. X. demande comment éviter les récidives.","t":"qcm","o":["Sport, correction du surpoids, réduction du sel et des graisses, arrêt du tabac","Régime riche en graisses","Sédentarité complète","Tabac modéré autorisé"],"a":0},{"c":21,"q":"Au-delà de quel délai la partie du myocarde non vascularisée se nécrose-t-elle (infarctus) selon le cours ?","x":"Au-delà de six heures, la partie du myocarde non vascularisée se nécrose : infarctus du myocarde.","mn":"6 h = nécrose.","kid":"Si le tuyau reste bouché plus de 6 heures, une partie du cœur meurt.","t":"qcm","o":["6 heures","30 minutes","24 heures","7 jours"],"a":0},{"c":21,"q":"Quel marqueur cardiaque est dosé dans le SCA ?","x":"Examens : ECG, marqueurs cardiaques (troponine I ou T, CPK, CPK-MB), coronarographie.","mn":"Troponine = cœur abîmé.","kid":"Une protéine sort du cœur quand il souffre ; on la mesure dans le sang.","t":"qcm","o":["Troponine I ou T","Lipase","Amylase","PSA"],"a":0},{"c":21,"q":"Quel est le délai et le but du thrombolytique (ténectéplase) dans le SCA ?","x":"Thrombolytique (ténectéplase) : délai inférieur à 8 h ; but : lyser le caillot ; CI : délai > 12 h, âge > 80 ans, hémorragie cérébrale.","mn":"Thrombolyse < 8 h.","kid":"Le médicament dissout le caillot s'il est donné vite.","t":"qcm","o":["Délai < 8 h, lyser le caillot","Délai > 12 h, dilater les bronches","Délai < 48 h, baisser la glycémie","Aucun délai, anticoaguler"],"a":0},{"c":21,"q":"Le SCA se distingue de l'angor stable par la persistance de la douleur malgré l'arrêt de l'effort ou la prise de dérivés nitrés.","x":"Le cours le précise dans la définition du SCA.","mn":"SCA = ne cède pas.","kid":"La douleur ne part pas, même au repos ou avec le médicament.","t":"vf","v":1},{"c":21,"q":"Un SCA peut se présenter sans douleur ou avec des douleurs épigastriques faisant penser à un ulcère.","x":"Formes atypiques : sans douleur chez le diabétique, douleurs épigastriques type ulcère, vomissements, sueurs, diarrhée.","mn":"Diabétique = infarctus muet.","kid":"Parfois le cœur souffre mais on a seulement mal au ventre, ou rien.","t":"vf","v":1},{"c":21,"q":"Citez un médicament antiagrégant plaquettaire du traitement au long cours du SCA.","x":"Traitement à vie : hygiène de vie, réadaptation, bêtabloquant, IEC, antiagrégant plaquettaire (aspirine, Plavix).","mn":"Aspirine à vie.","kid":"Un petit médicament empêche les plaquettes de refaire un caillot.","t":"open","r":"Aspirine","acc":["Aspirine","aspirine","clopidogrel","plavix","aspirine","plavix","clopidogrel"]},{"c":21,"q":"Quel diagnostic ?","x":"Douleur prolongée, intense, pan-radiante, résistante à la trinitrine, avec sueurs froides, pâleur, nausées = SCA.","mn":"40 min + trinitrine inefficace = SCA.","kid":"Un tuyau du cœur est complètement bouché.","s":"M. R., 55 ans, ressent au réveil une douleur rétrosternale violente en étau irradiant à la mâchoire et au bras gauche, durant depuis 40 minutes, avec sueurs froides et nausées, non soulagée par la trinitrine.","t":"qcm","o":["Syndrome coronarien aigu","Angor stable","Péricardite","Reflux gastro-œsophagien"],"a":0},{"c":21,"q":"Quels sont les soins prioritaires ?","x":"Soins prioritaires : accueillir, rassurer, repos strict en ½ assis, oxygénothérapie, monitorage continu du rythme, de la TA et de la température.","mn":"USIC : Repos – O2 – Scope.","kid":"On le fait reposer, on lui donne de l'oxygène et on surveille son cœur sur l'écran.","s":"Un patient en SCA arrive en USIC.","t":"qcm","o":["Accueillir, rassurer, repos strict ½ assis, O2, monitorage continu (rythme, TA, T°)","Marche précoce immédiate","Bain chaud","Repas copieux"],"a":0},{"c":22,"q":"Comment se définit la péricardite aiguë ?","x":"La péricardite aiguë est une inflammation des deux feuillets du péricarde, associée ou non à un épanchement liquidien.","mn":"Péricarde enflammé.","kid":"L'enveloppe du cœur est irritée.","t":"qcm","o":["Inflammation des deux feuillets du péricarde, avec ou sans épanchement","Inflammation de la plèvre","Obstruction d'une coronaire","Dilatation du ventricule droit"],"a":0},{"c":22,"q":"Comment varie la douleur de la péricardite avec la position ?","x":"La douleur augmente en décubitus et diminue en position assise penchée en avant ; elle augmente à l'inspiration et à la toux.","mn":"Péricardite = penché en avant soulage.","kid":"Assis et penché en avant, ça fait moins mal.","t":"qcm","o":["Augmente en décubitus, diminue en position assise penchée en avant","Diminue en décubitus","Ne varie jamais","Disparaît à la marche"],"a":0},{"c":22,"q":"Quel signe est pathognomonique de la péricardite ?","x":"Le frottement péricardique est pathognomonique : bruit surajouté, superficiel, aux 2 temps, de va-et-vient ou de cuir neuf, « il naît et meurt sur place ».","mn":"Frottement = signature.","kid":"On entend les deux couches de l'enveloppe du cœur se frotter.","t":"qcm","o":["Le frottement péricardique","Le signe de Homans","Le reflux hépato-jugulaire","Le bruit de galop"],"a":0},{"c":22,"q":"À la radiographie, la péricardite avec épanchement montre une cardiomégalie avec un rapport cardio-thoracique supérieur à 0,5.","x":"La radio montre une cardiomégalie avec RCT > 0,5 ; elle peut visualiser un épanchement pleural.","mn":"RCT > 0,5.","kid":"Le cœur paraît gros parce que le liquide l'entoure.","t":"vf","v":1},{"c":22,"q":"Le pouls paradoxal de Kussmaul est un pouls qui augmente à l'inspiration.","x":"Signe de compression cardiaque.","mn":"Paradoxal = baisse à l'inspiration.","kid":"Quand on inspire, le pouls devient plus faible.","t":"vf","v":0},{"c":22,"q":"Quelle complication grave par compression du cœur par l'épanchement le cours cite-t-il ?","x":"Évolution : favorable sous traitement, rechutes, tamponnade, constriction, mort ; hypotension + turgescence jugulaire = signes de complications.","mn":"Tamponnade = cœur écrasé.","kid":"Trop de liquide autour du cœur l'empêche de se remplir.","t":"open","r":"Tamponnade","acc":["Tamponnade","la tamponnade","tamponade","tamponnade","tamponade"]},{"c":22,"q":"Quel diagnostic ?","x":"Syndrome grippal préalable, douleur posturale et frottement péricardique = péricardite aiguë.","mn":"Grippe + penché en avant + frottement = péricardite.","kid":"Un virus a irrité l'enveloppe de son cœur.","s":"M. U., 30 ans, a eu un syndrome grippal il y a une semaine. Il présente une douleur thoracique majorée en décubitus et soulagée assis penché en avant ; on entend un bruit de va-et-vient.","t":"qcm","o":["Péricardite aiguë","Infarctus du myocarde","Embolie pulmonaire","OAP"],"a":0},{"c":22,"q":"Quelle préparation infirmière est prioritaire ?","x":"CAT : repos ½ assis, O2, VVP gros calibre, surveiller les paramètres, réunir le matériel de ponction et réanimation, préparer le site ; la ponction péricardique peut retirer jusqu'à 1 litre.","mn":"Tamponnade → ponction.","kid":"Il faut vite enlever le liquide autour du cœur.","s":"Un patient en péricardite avec épanchement abondant devient hypotendu avec des jugulaires turgescentes.","t":"qcm","o":["Réunir le matériel de ponction et de réanimation, VVP de gros calibre, O2, préparer le site de ponction","Faire marcher le patient","Allonger à plat sans surveillance","Donner un repas"],"a":0},{"c":23,"q":"En combien de régions l'abdomen est-il découpé pour l'examen clinique ?","x":"L'abdomen est découpé en 9 régions distinctes facilitant l'examen clinique et l'interprétation topographique des symptômes.","mn":"3 × 3 = 9.","kid":"On dessine une grille de morpion sur le ventre.","t":"qcm","o":["9","4","6","12"],"a":0},{"c":23,"q":"Qu'est-ce que le méléna ?","x":"Méléna : émission par l'anus de sang digéré noir et fétide, témoignant d'un saignement en amont du côlon droit.","mn":"Méléna = noir comme Mélanine.","kid":"Le sang qui a voyagé dans l'intestin devient noir et sent très mauvais.","t":"qcm","o":["Émission par l'anus de sang digéré, noir et fétide","Vomissement de sang rouge","Sang rouge vif dans les selles","Urines foncées"],"a":0},{"c":23,"q":"Quelle est la triade de l'occlusion intestinale ?","x":"Triade : douleur abdominale (coliques), vomissements, arrêt des matières et des gaz (l'arrêt des gaz précède celui des matières).","mn":"Douleur – Vomit – Rien ne sort.","kid":"L'intestin est bouché : ça fait mal, on vomit et rien ne sort.","t":"qcm","o":["Douleur abdominale, vomissements, arrêt des matières et des gaz","Fièvre, ictère, prurit","Toux, dyspnée, hémoptysie","Diarrhée, fièvre, éruption"],"a":0},{"c":23,"q":"L'hématémèse est l'extériorisation de sang par la bouche lors d'efforts de vomissement, traduisant une hémorragie digestive haute.","x":"Hématémèse : sang rouge ou noir rejeté par la bouche lors de vomissements ; causes : ulcère, rupture de varices œsophagiennes, Mallory-Weiss.","mn":"Hémat-émèse = sang vomi.","kid":"On vomit du sang parce que ça saigne en haut du tube digestif.","t":"vf","v":1},{"c":23,"q":"Le syndrome cholériforme se caractérise par une diarrhée glairo-sanglante fébrile avec ténesme.","x":"Toxine = eau ; invasion = sang + glaires.","mn":"Choléra = eau ; dysenterie = sang.","kid":"Dans le choléra, on perd beaucoup d'eau ; dans la dysenterie, il y a du sang.","t":"vf","v":0},{"c":23,"q":"À partir de quel poids quotidien de selles parle-t-on de diarrhée selon le cours (en g/24 h) ?","x":"Diarrhée : émission quotidienne trop fréquente de selles molles ou liquides, en quantité trop abondante (> 300 g/24 h).","mn":"Diarrhée > 300 g.","kid":"Quand on fait trop de selles liquides, plus de 300 grammes par jour.","t":"open","r":"300 g/24 h","acc":["300 g/24 h","300","300 g","300"]},{"c":23,"q":"Quel diagnostic sémiologique ?","x":"Colique hépatique : enclavement d'un calcul, douleur de l'HCD/épigastre, paroxystique, irradiant à l'omoplate/épaule droite, inhibition respiratoire, 2 à 4 h, sans fièvre ni ictère.","mn":"Colique hépatique = HCD → omoplate droite.","kid":"Un caillou bloque la sortie de la vésicule et ça fait très mal à droite.","s":"Mme N., 50 ans, obèse, présente après un repas copieux une douleur paroxystique de l'hypochondre droit irradiant vers l'omoplate droite, qui l'empêche de respirer profondément, depuis 3 heures. Pas de fièvre, pas d'ictère.","t":"qcm","o":["Colique hépatique","Colique néphrétique","Pancréatite aiguë","Appendicite"],"a":0},{"c":23,"q":"De quel syndrome s'agit-il ?","x":"L'hypertension portale (bloc intrahépatique le plus souvent dû à une cirrhose) associe circulation collatérale, splénomégalie, varices œsophagiennes.","mn":"HTP = CVC + rate + varices.","kid":"Le sang ne passe plus bien dans le foie et cherche d'autres chemins.","s":"M. C., cirrhotique, présente une circulation veineuse collatérale abdominale, une splénomégalie et des varices œsophagiennes.","t":"qcm","o":["Hypertension portale","Insuffisance rénale","Péricardite","Occlusion intestinale"],"a":0},{"c":24,"q":"Quel est le symptôme typique du RGO ?","x":"Manifestations typiques : pyrosis post-prandial, pyrosis postural, régurgitations.","mn":"RGO = brûlure qui monte.","kid":"L'acide de l'estomac remonte et brûle derrière le sternum.","t":"qcm","o":["Le pyrosis (brûlure rétrosternale ascendante) post-prandial","La claudication intermittente","L'hémoptysie","L'hématurie"],"a":0},{"c":24,"q":"Comment s'appelle le pyrosis déclenché par l'antéflexion du tronc ?","x":"Pyrosis déclenché par le décubitus ou l'antéflexion du tronc : signe du lacet (survient au laçage des chaussures).","mn":"Lacet = se pencher.","kid":"Quand on se penche pour lacer ses chaussures, l'acide remonte.","t":"qcm","o":["Signe du lacet","Signe de Murphy","Signe de Homans","Signe de Harzer"],"a":0},{"c":24,"q":"Quels médicaments sont aujourd'hui souvent conseillés en première intention dans le RGO symptomatique sévère ?","x":"Antiacides à la demande si symptômes peu fréquents ; si sévères : anti-H2 ou IPP ; les IPP sont souvent conseillés en première intention.","mn":"RGO sévère = IPP.","kid":"Un médicament ferme le robinet d'acide de l'estomac.","t":"qcm","o":["Les IPP","Les antibiotiques","Les diurétiques","Les anticoagulants"],"a":0},{"c":24,"q":"L'œsophagite peptique siège dans la partie inférieure de l'œsophage (5 derniers centimètres).","x":"L'œsophagite peptique, quel que soit son grade, siège dans la partie inférieure de l'œsophage.","mn":"L'acide brûle en bas.","kid":"L'acide abîme le bas du tuyau, juste au-dessus de l'estomac.","t":"vf","v":1},{"c":24,"q":"La hernie hiatale est une protrusion d'une partie de l'intestin grêle dans l'abdomen.","x":"Estomac → thorax.","mn":"Hernie hiatale = estomac qui monte.","kid":"Un petit bout de l'estomac passe au-dessus du diaphragme.","t":"vf","v":0},{"c":24,"q":"Quelle complication du RGO se traduit par une dysphagie, siège en bas de l'œsophage et nécessite des biopsies pour la différencier d'un cancer ?","x":"La sténose peptique siège à la partie inférieure de l'œsophage, régulière et centrée ; biopsies nécessaires pour la différencier d'un cancer.","mn":"Sténose = rétrécissement.","kid":"À force de brûlures, le tuyau se rétrécit et les aliments passent mal.","t":"open","r":"Sténose peptique","acc":["Sténose peptique","stenose peptique","stenose","stenose"]},{"c":24,"q":"Que retient le cours ?","x":"Étiologies particulières : pyrosis de la femme enceinte, sclérodermie, chirurgie… Pyrosis post-prandial et postural typiques.","mn":"Grossesse = pyrosis.","kid":"Le bébé pousse sur l'estomac et l'acide remonte.","s":"Mme A., enceinte de 7 mois, se plaint de brûlures rétrosternales après les repas et en position couchée.","t":"qcm","o":["Pyrosis de la femme enceinte : forme particulière de RGO","Infarctus du myocarde","Embolie pulmonaire","Hépatite virale"],"a":0},{"c":24,"q":"Que faut-il évoquer ?","x":"Manifestations atypiques : brûlures épigastriques isolées, syndrome respiratoire (toux, asthmatiforme), ORL, douleur thoracique pseudo-angineuse à bilan cardiaque négatif.","mn":"Toux nocturne + cœur normal = penser RGO.","kid":"L'acide qui remonte la nuit peut faire tousser.","s":"M. O., 45 ans, a une toux nocturne chronique et une douleur thoracique pseudo-angineuse ; le bilan cardiaque est normal.","t":"qcm","o":["Une manifestation atypique de RGO","Une angine de poitrine certaine","Une TVP","Une lithiase urinaire"],"a":0},{"c":25,"q":"Quel germe est impliqué dans la maladie ulcéreuse gastroduodénale ?","x":"H. pylori, bacille Gram négatif résistant à l'acidité grâce à son uréase, colonise la muqueuse antrale ; contracté surtout dans l'enfance.","mn":"HP = ulcère.","kid":"Un microbe qui vit dans l'estomac malgré l'acide.","t":"qcm","o":["Helicobacter pylori","Bacille de Koch","Pneumocoque","Escherichia coli"],"a":0},{"c":25,"q":"Quelle est la caractéristique du syndrome ulcéreux typique ?","x":"Douleur épigastrique sans irradiation, crampe ou faim douloureuse, calmée par les aliments ou antiacides, rythmée par les repas avec intervalle libre de 1 à 3 h.","mn":"Ulcère = faim douloureuse.","kid":"Ça fait mal comme une grosse faim, et manger soulage.","t":"qcm","o":["Douleur épigastrique en crampe calmée par les aliments, rythmée par les repas (intervalle libre 1-3 h)","Douleur de la fosse iliaque droite à la marche","Douleur thoracique à l'effort","Douleur lombaire irradiant aux organes génitaux"],"a":0},{"c":25,"q":"Combien de temps dure la trithérapie d'éradication de première ligne de H. pylori selon le cours ?","x":"Trithérapie d'une semaine : IPP matin et soir + 2 antibiotiques parmi amoxicilline, clarithromycine, métronidazole.","mn":"HP : 1 semaine, 1 IPP + 2 ATB.","kid":"On prend trois médicaments pendant une semaine pour tuer le microbe.","t":"qcm","o":["1 semaine","1 mois","3 mois","1 jour"],"a":0},{"c":25,"q":"Selon le cours, le stress et les facteurs psychologiques ont un rôle démontré dans la physiopathologie de l'ulcère.","x":"Les causes démontrées sont H. pylori et les AINS.","mn":"Stress ≠ cause démontrée.","kid":"Ce n'est pas le stress qui fait l'ulcère, c'est surtout un microbe ou certains médicaments.","t":"vf","v":0},{"c":25,"q":"Les ulcères duodénaux ne deviennent jamais cancéreux.","x":"Le cours : les UD ne deviennent jamais cancéreux ; biopsies systématiques pour les UG.","mn":"UD jamais cancer ; UG → biopsier.","kid":"Seul l'ulcère de l'estomac doit être surveillé pour le cancer.","t":"vf","v":1},{"c":25,"q":"Quelle classe de médicaments, en inhibant les prostaglandines, favorise les ulcères gastroduodénaux ?","x":"Les AINS inhibent les COX 1 et 2, réduisent les prostaglandines protectrices et favorisent ulcères et complications, plus souvent gastriques.","mn":"AINS = estomac fragile.","kid":"Certains médicaments contre la douleur enlèvent la protection de l'estomac.","t":"open","r":"AINS","acc":["AINS","anti-inflammatoires non steroidiens","anti inflammatoires","ains","anti-inflammatoire","anti inflammatoire"]},{"c":25,"q":"Quel traitement prévoit le cours ?","x":"Éradication de première ligne : trithérapie d'une semaine IPP + 2 antibiotiques.","mn":"Ulcère HP+ → trithérapie.","kid":"On tue le microbe et on calme l'acide.","s":"M. F. a un ulcère duodénal avec H. pylori positif.","t":"qcm","o":["IPP matin et soir + 2 antibiotiques (amoxicilline, clarithromycine ou métronidazole) pendant 1 semaine","Chirurgie d'emblée","Corticoïdes","AINS"],"a":0},{"c":25,"q":"Que rappelle le cours ?","x":"Complication ulcéreuse inaugurale : hémorragie ou perforation d'emblée, sans signe préalable d'alarme, notamment sous AINS.","mn":"AINS + coup de poignard = perforation.","kid":"L'ulcère a percé la paroi de l'estomac d'un coup.","s":"M. S., sous AINS, présente brutalement une douleur épigastrique en coup de poignard sans aucun antécédent ulcéreux.","t":"qcm","o":["Un UGD peut se révéler d'emblée par une complication (perforation ou hémorragie) sans signe d'alarme","Un ulcère est toujours précédé de douleurs typiques","Les AINS protègent l'estomac","C'est forcément un infarctus"],"a":0},{"c":26,"q":"À partir de quelle durée parle-t-on d'hépatite chronique ?","x":"L'hépatite chronique est une inflammation évolutive du foie durant depuis plus de six mois ; en dessous, le processus est aigu.","mn":"Chronique = 6 mois.","kid":"Si le foie reste malade plus de six mois, c'est chronique.","t":"qcm","o":["Plus de 6 mois","Plus de 15 jours","Plus de 1 mois","Plus de 5 ans"],"a":0},{"c":26,"q":"Quel est le mode de transmission de l'hépatite A ?","x":"Le VHA se transmet par voie féco-orale, habituellement par l'eau contaminée ; survient dans l'enfance ou chez l'adulte jeune.","mn":"A et E = Eau (Alimentaire, Entérique).","kid":"On l'attrape en buvant de l'eau sale.","t":"qcm","o":["Féco-oral, par l'eau contaminée","Sexuel exclusivement","Transfusionnel exclusivement","Par piqûre de moustique"],"a":0},{"c":26,"q":"Quel est le mode de contamination principal de l'hépatite C ?","x":"Le mode de contamination du VHC est principalement parentéral ; pas de vaccin ; 6 génotypes.","mn":"C = Contact sang.","kid":"On l'attrape surtout par le sang (aiguilles, transfusions).","t":"qcm","o":["Parentéral","Féco-oral","Aérien","Cutané par simple contact"],"a":0},{"c":26,"q":"Il existe un vaccin contre l'hépatite C.","x":"Vaccins : A et B (E en Chine), pas C.","mn":"C = Cauchemar : pas de vaccin.","kid":"Pour l'hépatite C, on ne peut pas encore se faire vacciner.","t":"vf","v":0},{"c":26,"q":"L'infection chronique par le VHB est définie par un antigène HBs positif persistant plus de 6 mois.","x":"Le cours le précise ; souvent asymptomatique jusqu'aux complications (cirrhose, CHC).","mn":"AgHBs > 6 mois = chronique.","kid":"Si le marqueur du virus reste dans le sang plus de six mois, c'est chronique.","t":"vf","v":1},{"c":26,"q":"Quel signe cutanéo-muqueux apparaît 7 à 10 jours après les signes aspécifiques de l'hépatite aiguë (A, B, E) ?","x":"Les symptômes aspécifiques précèdent d'environ 7 à 10 jours l'apparition d'un ictère cutanéo-muqueux.","mn":"Hépatite = jaunisse.","kid":"La peau et le blanc des yeux deviennent jaunes.","t":"open","r":"Ictère","acc":["Ictère","ictere","jaunisse","ictere","jaunisse"]},{"c":26,"q":"Que recommande le cours ?","x":"L'hépatite B fait partie des IST et doit faire rechercher systématiquement le VIH et les autres IST (syphilis).","mn":"VHB = IST → VIH.","kid":"Ce virus se transmet comme d'autres infections sexuelles, donc on les cherche aussi.","s":"M. B., 25 ans, découvre une hépatite B lors d'un bilan.","t":"qcm","o":["Rechercher systématiquement le VIH et les autres IST (syphilis)","Aucun autre bilan","Vacciner contre l'hépatite C","Rechercher uniquement le paludisme"],"a":0},{"c":26,"q":"Quel risque évolutif rappelle le cours ?","x":"L'hépatite chronique C évolue vers la cirrhose dans 10-20 % des cas en 20 ans ; incidence du CHC de l'ordre de 1-3 %.","mn":"C → Cirrhose → Cancer.","kid":"Le virus abîme lentement le foie pendant des années.","s":"Mme K. a une hépatite C chronique depuis 20 ans.","t":"qcm","o":["Évolution vers la cirrhose dans 10-20 % des cas en 20 ans, puis carcinome hépatocellulaire","Guérison spontanée toujours","Aucun risque","Évolution vers l'asthme"],"a":0},{"c":27,"q":"Comment l'infirmier accueille-t-il un malade atteint d'hépatite virale selon le cours ?","x":"Accueil : isoler le malade en chambre individuelle, préparer le matériel individuel (thermomètre, couverture, draps, seau, bassin), feuille de surveillance.","mn":"Hépatite = chambre seule + matériel perso.","kid":"Le malade a sa chambre et ses propres affaires pour ne pas contaminer les autres.","t":"qcm","o":["En chambre individuelle avec matériel d'usage courant individuel","En salle commune sans précaution","En réanimation systématiquement","À domicile sans suivi"],"a":0},{"c":27,"q":"Quel régime alimentaire le cours prescrit-il dans l'hépatite virale ?","x":"Régime riche en glucides, en protides mais pauvre en graisses ; supprimer l'alcool ; repos absolu.","mn":"Foie malade : sucre et protéines oui, gras non, alcool jamais.","kid":"On mange léger, sans gras, et surtout pas d'alcool.","t":"qcm","o":["Riche en glucides et protides, pauvre en graisses, sans alcool","Riche en graisses","Sans glucides","Riche en alcool"],"a":0},{"c":27,"q":"Selon le cours, l'immunité du vaccin Hevac B est conférée :","x":"Hevac B : immunité 1 mois après la 3e injection à 1 mois d'intervalle, rappel 1 an après puis tous les 5 ans (schéma daté du cours).","mn":"3 doses → 1 mois → protégé.","kid":"Après trois piqûres, le corps est protégé.","t":"qcm","o":["1 mois après la 3e injection (injections à 1 mois d'intervalle), rappel à 1 an puis tous les 5 ans","Immédiatement après 1 injection","Après 10 injections","Jamais"],"a":0},{"c":27,"q":"Selon le cours, l'hépatite B est une maladie à déclaration obligatoire.","x":"N.B. du cours : l'hépatite B est une maladie à déclaration obligatoire.","mn":"VHB = déclaration.","kid":"Le médecin doit signaler la maladie aux autorités.","t":"vf","v":1},{"c":27,"q":"Dans l'hépatite virale, les médicaments hormonaux et progestatifs sont conseillés.","x":"Ils sont métabolisés par le foie.","mn":"Foie malade = pas d'hormones.","kid":"On évite des médicaments que le foie devrait encore travailler.","t":"vf","v":0},{"c":27,"q":"Citez un signe de danger annonçant une complication de l'hépatite que l'infirmier doit guetter.","x":"Signes de danger : persistance de l'ictère, trouble de la conscience, coma.","mn":"Jaune qui reste, tête qui part = danger.","kid":"S'il reste jaune ou devient confus, c'est grave.","t":"open","r":"Trouble de la conscience","acc":["Trouble de la conscience","persistance de l ictere","coma","troubles de la conscience","conscience","coma","ictere"]},{"c":27,"q":"Quelle surveillance est conforme au cours ?","x":"Surveillance : TA, pouls, respiration, courbe de poids, urines/diurèse, transit et coloration des selles/urines, jaunissement, reprise de l'appétit, signes de danger.","mn":"Poids – Urines – Selles – Peau – Appétit.","kid":"On regarde son poids, la couleur de son pipi, de ses selles et de sa peau.","s":"Une infirmière prend en charge M. T., hospitalisé pour hépatite virale aiguë.","t":"qcm","o":["Constantes, courbe de poids, diurèse, coloration des selles et urines, jaunissement des téguments, appétit","Uniquement la glycémie","Uniquement la température une fois par semaine","Aucune surveillance"],"a":0},{"c":27,"q":"Quel diagnostic le cours décrit-il dans ce contexte ?","x":"Pathologie fonctionnelle très répandue (15-30 %), douleur sans lésion, diagnostic d'élimination ; coloscopie totale = examen le plus important.","mn":"Fonctionnel = pas de lésion.","kid":"Le ventre est sensible mais les organes ne sont pas abîmés.","s":"Mme E., 35 ans, consulte pour des douleurs abdominales fluctuantes avec ballonnements depuis des années, sans altération de l'état général, ni anémie ni syndrome inflammatoire. (Notion présente p. 126-127, non annoncée au sommaire.)","t":"qcm","o":["Colopathie fonctionnelle (syndrome de l'intestin irritable)","Cancer du côlon certain","Hépatite virale","Lithiase urinaire"],"a":0},{"c":28,"q":"Quelle est la cause essentielle de la cirrhose (80 % des cas) selon le cours ?","x":"L'alcool ingéré en quantité abondante est la cause essentielle dans 80 % des cas ; facteurs adjuvants : terrain et carence protidique.","mn":"Cirrhose = alcool (80 %).","kid":"Boire beaucoup d'alcool longtemps abîme le foie pour toujours.","t":"qcm","o":["L'alcool","L'hépatite A","Le tabac","Le paludisme"],"a":0},{"c":28,"q":"Qu'est-ce que l'ascite ?","x":"L'ascite est un épanchement de liquide dans le péritoine qui augmente le volume de l'abdomen, contrastant avec l'amaigrissement du visage et des membres.","mn":"Ascite = eau dans le ventre.","kid":"Le ventre se remplit d'eau et devient très gros.","t":"qcm","o":["Épanchement de liquide dans le péritoine","Sang dans les urines","Liquide dans la plèvre","Liquide dans le péricarde"],"a":0},{"c":28,"q":"Quel volume maximal le cours autorise-t-il par ponction évacuatrice d'ascite dans la cirrhose ?","x":"Les ponctions évacuatrices ne sont indiquées que lors d'une gêne fonctionnelle importante et ne doivent jamais dépasser 1500 cc par ponction (selon le cours).","mn":"1,5 l maximum.","kid":"On ne retire pas trop d'eau d'un coup.","t":"qcm","o":["1500 cc","500 cc","5 litres","10 litres"],"a":0},{"c":28,"q":"Le traitement de la cirrhose repose sur le repos, le régime sans sel strict et le sevrage alcoolique définitif.","x":"Conduite du traitement : repos au lit, régime sans sel strict (supprimer pain, charcuterie, conserves, eaux sodées…), sevrage alcoolique définitif.","mn":"Repos – Sans sel – Sans alcool.","kid":"Il doit se reposer, manger sans sel et ne plus jamais boire d'alcool.","t":"vf","v":1},{"c":28,"q":"Chez le cirrhotique, les hémorragies digestives sont rares car le sang coagule très bien.","x":"Insuffisance hépatique → défaut de coagulation.","mn":"Foie malade = sang qui ne coagule pas.","kid":"Le foie fabrique moins de facteurs de coagulation, alors ça saigne facilement.","t":"vf","v":0},{"c":28,"q":"Quel médicament réduit la production et l'absorption des substances neurotoxiques intestinales dans l'encéphalopathie hépatique ?","x":"En cas d'encéphalopathie : réduction des protides < 20 g/24 h, néomycine 1-2 g/24 h, lactulose 15-30 g/24 h.","mn":"Lactulose = intestin nettoyé.","kid":"Un sirop aide à évacuer les poisons de l'intestin qui embrument le cerveau.","t":"open","r":"Lactulose","acc":["Lactulose","lactalose","lactulose","lactulose","lactalose"]},{"c":28,"q":"À quel stade est sa cirrhose ?","x":"Décompensation : ascite, OMI, oligurie, ictère, hémorragie, AEG ; abdomen volumineux contrastant avec l'amaigrissement, circulation collatérale.","mn":"Gros ventre + maigre = cirrhose décompensée.","kid":"Son foie ne fonctionne plus et l'eau s'accumule dans son ventre.","s":"M. K., 52 ans, buveur, présente un gros ventre avec matité des flancs, un visage et des membres amaigris, une circulation collatérale abdominale et des OMI.","t":"qcm","o":["Cirrhose décompensée (période ascitique)","Cirrhose compensée sans signe","Hépatite A aiguë","Lithiase biliaire"],"a":0},{"c":28,"q":"Quelle intervention infirmière est conforme au cours ?","x":"Ictère : observer les degrés ; soulager le prurit par des soins de la peau, bains sans savon, massages émollients ; garder les ongles courts.","mn":"Prurit : doux, sans savon, ongles courts.","kid":"On adoucit la peau et on coupe les ongles pour éviter les griffures.","s":"Mme R., cirrhotique ictérique, se plaint d'un prurit intense.","t":"qcm","o":["Soins de peau, bains sans savon, lotions émollientes, ongles courts","Bains très chauds savonneux","Alcool à 90° sur la peau","Ne rien faire"],"a":0},{"c":29,"q":"Comment se définit la ponction d'ascite ?","x":"La ponction d'ascite (paracentèse) est l'évacuation des épanchements contenus en abondance dans la cavité péritonéale.","mn":"Paracentèse = péritoine.","kid":"On retire l'eau du ventre avec une aiguille.","t":"qcm","o":["L'évacuation des épanchements contenus en abondance dans la cavité péritonéale","L'évacuation du liquide pleural","Le drainage du péricarde","Le prélèvement de sang artériel"],"a":0},{"c":29,"q":"Où se fait la ponction d'ascite selon le cours ?","x":"La ponction se fait dans la fosse iliaque gauche pour éviter une blessure du foie ou du cœur ; décubitus avec inclinaison à gauche, oreiller sous la fesse droite.","mn":"Ascite = gauche (loin du foie).","kid":"On pique en bas à gauche du ventre, loin du foie.","t":"qcm","o":["Dans la fosse iliaque gauche","Dans la fosse iliaque droite au point de McBurney","Dans l'hypochondre droit","En sus-ombilical médian"],"a":0},{"c":29,"q":"Quel accident peut provoquer une décompression trop brusque lors d'une ponction d'ascite ?","x":"Surveiller le débit : une décompression trop brusque peut entraîner un collapsus cardiovasculaire ; autres accidents : piqûre de paroi/vaisseaux, écoulement persistant (infection).","mn":"Trop vite = collapsus.","kid":"Si on vide trop vite, la tension chute d'un coup.","t":"qcm","o":["Un collapsus cardiovasculaire","Un OAP","Une embolie gazeuse","Une hyperglycémie"],"a":0},{"c":29,"q":"Aujourd'hui, la paracentèse sert d'abord à l'examen diagnostique du liquide et au traitement de l'ascite importante résistante.","x":"Le cours le précise dans le but de la paracentèse.","mn":"Diagnostic + ascite rebelle.","kid":"On ponctionne pour analyser le liquide ou soulager une très grosse ascite.","t":"vf","v":1},{"c":29,"q":"La péricardite et les péritonites tuberculeuses ne sont jamais des indications de ponction d'ascite.","x":"Le cours les cite comme indications.","mn":"CPTFC : Cirrhose, Péritonite TB, Tumeur, Foie, Cœur.","kid":"Plusieurs maladies peuvent remplir le ventre d'eau.","t":"vf","v":0},{"c":29,"q":"Quelle pince sert à régler le débit lors de la ponction d'ascite ?","x":"Matériel spécifique : aiguille de Kuss/Juffer ou trocart, raccord caoutchouc, pince de Mohr pour régler le débit, tube stérile, bocal gradué…","mn":"Mohr = Modère.","kid":"Une petite pince serre le tuyau pour que le liquide coule doucement.","t":"open","r":"Pince de Mohr","acc":["Pince de Mohr","mohr","pince de mohr","mohr"]},{"c":29,"q":"Quelle conduite ?","x":"Pendant la ponction : surveiller réactions, pouls, faciès, température, aspect et débit du liquide ; décompression brusque = collapsus.","mn":"Pâleur + pouls rapide = clamp.","kid":"On ferme le tuyau pour que la tension remonte.","s":"Pendant une ponction d'ascite, le patient devient pâle, son pouls s'accélère et s'affaiblit.","t":"qcm","o":["Ralentir/arrêter l'écoulement avec la pince et prévenir : risque de collapsus","Accélérer l'écoulement","Faire lever le patient","Ignorer"],"a":0},{"c":29,"q":"Quel risque le cours signale-t-il ?","x":"Accidents : piqûre de paroi et vaisseaux, collapsus, écoulement persistant = risque d'infection ; après la ponction s'assurer que le malade ne reste pas mouillé.","mn":"Suintement = infection.","kid":"Le liquide qui coule peut laisser entrer des microbes.","s":"Après une ponction d'ascite, le point de ponction continue de suinter.","t":"qcm","o":["Risque d'infection par écoulement persistant","Aucun risque","Risque d'OAP","Risque d'hypertension"],"a":0},{"c":30,"q":"Quel est le but de l'aspiration gastrique ?","x":"L'aspiration gastrique est l'évacuation de l'estomac par un dispositif d'aspiration, pour éviter l'inhalation du contenu gastrique.","mn":"Aspirer pour ne pas inhaler.","kid":"On vide l'estomac pour que le patient ne respire pas son contenu.","t":"qcm","o":["Évacuer l'estomac pour éviter l'inhalation du contenu gastrique","Nourrir le patient","Mesurer la glycémie","Injecter un produit de contraste"],"a":0},{"c":30,"q":"Quelle force d'aspiration doit atteindre l'aspiration gastrique selon le cours ?","x":"Mettre le moteur en marche : la force d'aspiration doit atteindre 40 à 50 cm d'eau, réglée avec une pince presse-tube.","mn":"40-50 cm H2O.","kid":"On aspire doucement, pas trop fort.","t":"qcm","o":["40 à 50 cm d'eau","200 cm d'eau","5 cm d'eau","1000 cm d'eau"],"a":0},{"c":30,"q":"Quelle est la contre-indication de l'aspiration gastrique citée dans le cours ?","x":"Indications : perforation de l'estomac (traitement médical), avant/après chirurgie gastrique ou abdominale, lavage ; contre-indication : cancers de l'estomac.","mn":"Cancer gastrique = CI.","kid":"On ne met pas ce tuyau si l'estomac a une tumeur.","t":"qcm","o":["Les cancers de l'estomac","La perforation gastrique","La chirurgie abdominale","L'occlusion"],"a":0},{"c":30,"q":"Le syndrome de sub-occlusion ou d'occlusion est une indication de l'aspiration duodénale continue.","x":"Indications de l'aspiration duodénale : sub-occlusion/occlusion, chirurgies intestinales, préventif ou post-opératoire (évite la distension, soulage les sutures).","mn":"Occlusion = aspirer.","kid":"Si l'intestin est bouché, on aspire pour le soulager.","t":"vf","v":1},{"c":30,"q":"Les accidents de l'aspiration duodénale continue sont fréquents et comprennent surtout des perforations coliques.","x":"Accidents rares et locaux.","mn":"Rare : gorge et œsophage.","kid":"Le tuyau peut parfois irriter la gorge.","t":"vf","v":0},{"c":30,"q":"Quel volume quotidien de soluté le cours cite-t-il pour la réhydratation pendant l'aspiration (en litres/jour) ?","x":"Mesurer la quantité aspirée et réhydrater correctement (2 litres par jour de soluté) selon l'état du malade.","mn":"Aspirer = compenser (2 l).","kid":"On remplace ce qu'on enlève par des perfusions.","t":"open","r":"2 litres par jour","acc":["2 litres par jour","2","2 l","2"]},{"c":30,"q":"Que vérifier en premier selon le cours ?","x":"Si l'aspirateur ne fonctionne pas : vérifier la sonde ou les tuyaux qui se collent, la tubulure non coudée, le fonctionnement du moteur, ajuster la pression.","mn":"Tuyau → coude → moteur.","kid":"On regarde d'abord si le tuyau est plié ou bouché.","s":"Pendant une aspiration gastrique, le bocal ne se remplit plus.","t":"qcm","o":["La sonde ou les tuyaux (collés, coudés), puis le moteur et la pression","Augmenter la pression au maximum sans vérifier","Retirer la sonde immédiatement","Rien"],"a":0},{"c":30,"q":"Quelle technique est conforme ?","x":"Retrait : dégonfler le ballonnet, retirer très lentement 5 ou 6 mm, ne pas forcer surtout s'il s'agit de la sonde d'Eudel.","mn":"Dégonfler – lentement – sans forcer.","kid":"On dégonfle le petit ballon et on tire tout doucement.","s":"L'infirmier doit retirer une sonde d'aspiration duodénale à ballonnet.","t":"qcm","o":["Dégonfler le ballonnet et retirer très lentement, sans forcer","Tirer d'un coup sec","Retirer ballonnet gonflé","Couper la sonde"],"a":0},{"c":31,"q":"Selon le cours, quelle est la place du cancer primitif du foie en Afrique noire ?","x":"Les CPF représentent la 1re cause de décès par cancer en Afrique noire ; en Afrique, souvent sur cirrhose d'origine virale.","mn":"CPF = 1er tueur en Afrique.","kid":"En Afrique, c'est le cancer qui tue le plus.","t":"qcm","o":["1re cause de décès par cancer","Cancer exceptionnel","Uniquement chez l'enfant","Sans lien avec les hépatites"],"a":0},{"c":31,"q":"Quelle toxine contaminant les arachides est un facteur de CPF en Afrique ?","x":"L'aflatoxine : toxine mycélienne contaminant les arachides ; autres causes : cirrhose virale, alcoolique, hémochromatose, parasites, chimiques.","mn":"Aflatoxine = Arachides moisies.","kid":"Un champignon qui pousse sur les arachides mal conservées fabrique un poison pour le foie.","t":"qcm","o":["L'aflatoxine","La toxine botulique","La toxine cholérique","L'endotoxine"],"a":0},{"c":31,"q":"Comment est le foie à la palpation dans le CPF sur foie non cirrhotique ?","x":"Examen : gros foie occupant l'abdomen, de dureté pierreuse, sensible, moins mobile ; ictère obstructif possible ; ascite rare.","mn":"CPF = foie de pierre.","kid":"Le foie devient énorme et dur comme un caillou.","t":"qcm","o":["Gros foie de dureté pierreuse, sensible","Foie petit et mou","Foie normal","Foie impalpable toujours"],"a":0},{"c":31,"q":"Dans le CPF, le délai de survie à partir du 1er symptôme dépasse exceptionnellement 6 mois selon le cours.","x":"Le CPF évolue rapidement vers la mort ; survie dépassant exceptionnellement 6 mois (donnée du cours, à remettre en perspective avec les progrès récents).","mn":"CPF : 6 mois.","kid":"Ce cancer va très vite.","t":"vf","v":1},{"c":31,"q":"L'exérèse chirurgicale du CPF est envisageable même en présence de cirrhose et de métastases.","x":"Conditions strictes.","mn":"Opérer seulement si foie sain et pas de métastase.","kid":"On n'opère que si le cancer est petit et n'est pas parti ailleurs.","t":"vf","v":0},{"c":31,"q":"Comment appelle-t-on le cancer formé dans un organe par migration de cellules d'un foyer primitif ?","x":"Des cellules cancéreuses migrent par voie lymphatique ou sanguine et colonisent un autre organe : métastase ou cancer secondaire ; le foie en est souvent le siège.","mn":"Méta = ailleurs.","kid":"Des cellules malades voyagent et forment une nouvelle tumeur ailleurs.","t":"open","r":"Métastase","acc":["Métastase","cancer secondaire","metastase","metastase","secondaire"]},{"c":31,"q":"Que suspecter ?","x":"Cancer massif touchant davantage l'homme vers la quarantaine ; asthénie, amaigrissement, douleur du foie, hépatomégalie pierreuse ; en Afrique souvent sur cirrhose virale.","mn":"Homme 40 ans + VHB + foie de pierre = CPF.","kid":"Le virus a abîmé son foie pendant des années et une tumeur est apparue.","s":"M. Y., 40 ans, porteur ancien du VHB, présente un amaigrissement, une asthénie, une douleur de l'hypochondre droit et un foie très gros et dur.","t":"qcm","o":["Un cancer primitif du foie","Une hépatite A","Une lithiase biliaire simple","Un RGO"],"a":0},{"c":31,"q":"Quel rôle infirmier le cours prévoit-il ?","x":"Rôle de l'infirmier : soins d'hygiène et de propreté, surveillance du traitement et des résultats, état général, constantes, IEC/CCC.","mn":"Hygiène – Surveillance – Communication.","kid":"On le soigne, on le surveille et on lui parle, ainsi qu'à sa famille.","s":"Un patient en phase avancée de CPF est hospitalisé.","t":"qcm","o":["Soins d'hygiène, surveillance du traitement et des examens, de l'état général, constantes, IEC/CCC","Aucun soin","Uniquement la chirurgie","Régime riche en alcool"],"a":0},{"c":32,"q":"Quels facteurs sont fréquemment associés à la lithiase biliaire selon le cours ?","x":"Le sexe féminin, l'âge avancé, les nombreuses grossesses, l'obésité sont des facteurs très fréquemment présents ; la stase biliaire joue un rôle.","mn":"4 F (en français : Femme, Âgée, Féconde, Forte).","kid":"Ça touche surtout les femmes, plus âgées, qui ont eu plusieurs enfants et en surpoids.","t":"qcm","o":["Sexe féminin, âge avancé, grossesses nombreuses, obésité","Sexe masculin jeune sportif","Enfant de moins de 2 ans","Végétarisme strict"],"a":0},{"c":32,"q":"Où irradie la colique hépatique ?","x":"Colique hépatique : douleur aiguë paroxystique, crampe, HCD et épigastre, irradiant à l'épaule droite et entre les omoplates.","mn":"Foie → épaule droite.","kid":"La douleur part à droite sous les côtes et monte à l'épaule.","t":"qcm","o":["Vers l'épaule droite et entre les omoplates","Vers les organes génitaux","Vers le bras gauche","Vers la fosse iliaque gauche"],"a":0},{"c":32,"q":"Quelle conduite à tenir le cours propose-t-il devant une colique hépatique ?","x":"Cas de colique hépatique : mettre le malade à jeun, compresses chaudes sur la région vésiculaire, antispasmodiques et antalgiques.","mn":"Jeûne – Chaud – Antispasmodique.","kid":"On arrête de manger, on met du chaud et on donne un médicament contre les spasmes.","t":"qcm","o":["Mettre à jeun, compresses chaudes sur la vésicule, antispasmodiques et antalgiques","Repas copieux et gras","Glace sur les lombes","Marche rapide"],"a":0},{"c":32,"q":"Lorsqu'une complication survient (fièvre avec hyperleucocytose), la cholécystectomie s'impose dans les plus brefs délais.","x":"N.B. du cours : complication (fièvre + hyperleucocytose) → cholécystectomie ou cholécystostomie dans les plus brefs délais.","mn":"Fièvre + calcul = bloc.","kid":"Si la vésicule s'infecte, il faut l'enlever vite.","t":"vf","v":1},{"c":32,"q":"Le traitement médical de la lithiase biliaire fait disparaître les calculs par dissolution.","x":"Le régime met au repos, il ne dissout pas.","mn":"Médical = calme, pas efface.","kid":"Les médicaments calment les crises mais ne font pas fondre les cailloux.","t":"vf","v":0},{"c":32,"q":"Comment s'appelle l'ablation chirurgicale de la vésicule biliaire ?","x":"La cholécystectomie (ou cholécystostomie) s'impose lors d'une complication.","mn":"Cholécyst-ectomie = enlever la vésicule.","kid":"Le chirurgien enlève le petit sac de la bile.","t":"open","r":"Cholécystectomie","acc":["Cholécystectomie","cholecystectomie","cholecystectomie"]},{"c":32,"q":"Quelle complication suspecter ?","x":"Les cholécystites calculeuses surviennent après un long passé bilio-hépatique, avec T° 39-39,5 °C, douleurs vésiculaires intenses, frissons.","mn":"Calcul + fièvre = cholécystite.","kid":"La vésicule bloquée par le caillou s'est infectée.","s":"Mme G., lithiasique connue, présente une fièvre à 39,5 °C avec frissons et une douleur intense de la région vésiculaire.","t":"qcm","o":["Cholécystite calculeuse","Colique néphrétique","Embolie pulmonaire","Angor"],"a":0},{"c":32,"q":"Que conseille le cours ?","x":"Régime : éviter les aliments riches en cholestérol et trop indigestes.","mn":"Moins de gras, moins de sauces.","kid":"On mange léger pour ne pas réveiller la vésicule.","s":"M. B., lithiasique, demande quoi éviter dans son alimentation.","t":"qcm","o":["Éviter les aliments riches en cholestérol (viandes et poissons gras, œufs) et indigestes (ragoûts, sauces, fromages fermentés)","Manger plus de sauces et d'œufs","Supprimer toute boisson","Manger uniquement du fromage fermenté"],"a":0},{"c":33,"q":"Quel est le tableau révélateur le plus fréquent de la lithiase urinaire ?","x":"Le tableau révélateur le plus fréquent est la crise de colique néphrétique : douleur lombaire brutale irradiant le long de l'uretère vers la vessie et les organes génitaux.","mn":"Calcul urinaire = colique néphrétique.","kid":"Un caillou bloque le tuyau qui va du rein à la vessie et ça fait très mal.","t":"qcm","o":["La colique néphrétique","L'hématémèse","La claudication","L'ictère"],"a":0},{"c":33,"q":"Quel examen le cours qualifie-t-il d'examen capital pour le diagnostic positif de la lithiase urinaire ?","x":"L'UIV en urgence, de préférence en période douloureuse, est l'examen capital du diagnostic positif (notion du cours, aujourd'hui souvent remplacée par le scanner).","mn":"UIV = examen capital (selon le cours).","kid":"On injecte un produit qui rend les voies urinaires visibles à la radio.","t":"qcm","o":["L'urographie intraveineuse en urgence","La radiographie pulmonaire","L'ECG","La fibroscopie bronchique"],"a":0},{"c":33,"q":"Dans quel pourcentage de cas la lithiase est-elle éliminée spontanément ?","x":"Dans 70 à 80 % des cas, la lithiase est éliminée spontanément ; elle doit alors être analysée pour guider le traitement.","mn":"3/4 sortent seuls.","kid":"La plupart des cailloux sortent tout seuls avec le pipi.","t":"qcm","o":["70 à 80 %","5 %","20 %","100 %"],"a":0},{"c":33,"q":"Selon le cours, la lithiase urinaire est plus fréquente chez l'homme, avec un pic entre 25 et 40 ans.","x":"Facteurs : climat chaud et sec, hydratation insuffisante, produits laitiers, purines, sexe masculin, âge 25-40 ans.","mn":"Homme jeune + chaleur + peu d'eau.","kid":"Les hommes qui boivent peu quand il fait chaud font plus de cailloux.","t":"vf","v":1},{"c":33,"q":"Une infection urinaire acidifie les urines et favorise la précipitation des phosphates.","x":"Infection → alcalin → phosphates ; viande → acide → urates.","mn":"Infection Alcalinise.","kid":"Les microbes rendent le pipi moins acide, et certains sels se transforment en cristaux.","t":"vf","v":0},{"c":33,"q":"Après élimination spontanée, quel examen est réalisé sur le calcul pour guider le traitement ?","x":"La lithiase éliminée sera complètement analysée (analyse cristallographique) pour connaître sa structure chimique.","mn":"Analyser le caillou.","kid":"On étudie de quoi est fait le caillou pour éviter qu'il revienne.","t":"open","r":"Analyse cristallographique","acc":["Analyse cristallographique","analyse chimique","analyse du calcul","cristallographie","analyse","cristallo"]},{"c":33,"q":"Quel diagnostic ?","x":"Douleur lombaire brutale, unilatérale, irradiant le long de l'uretère vers la vessie et les organes génitaux, pollakiurie de quelques cc.","mn":"Lombes → organes génitaux = colique néphrétique.","kid":"Un caillou descend dans le tuyau du rein.","s":"M. A., 32 ans, ressent brutalement une douleur lombaire droite atroce irradiant vers la vessie et les organes génitaux, avec envies fréquentes d'uriner de quelques cc, agité, ne trouvant aucune position.","t":"qcm","o":["Colique néphrétique","Colique hépatique","Appendicite","Infarctus"],"a":0},{"c":33,"q":"Quelle conduite infirmière ?","x":"Soulager : analgésiques narcotiques IV/IM sur prescription (prévenir le choc), chaleur humide, position antalgique ; intensification → avertir immédiatement le médecin ; préparer à une extraction si besoin.","mn":"Douleur ↑ = appeler.","kid":"On le soulage vite et on prévient le médecin si ça empire.","s":"Un patient en colique néphrétique souffre intensément malgré un premier antalgique.","t":"qcm","o":["Administrer les analgésiques prescrits (IV/IM), chaleur humide, position antalgique ; signaler immédiatement toute intensification au médecin","Attendre le lendemain","Restreindre totalement les boissons sans avis","Faire courir le patient"],"a":0},{"c":34,"q":"Comment le cours définit-il l'infection urinaire ?","x":"L'infection urinaire est la présence de germes pathogènes dans l'urine à l'intérieur des voies excrétrices ; elle peut être aiguë, chronique ou asymptomatique.","mn":"IU = microbes dans l'urine.","kid":"Des microbes se mettent dans le pipi et les tuyaux urinaires.","t":"qcm","o":["Présence de germes pathogènes dans l'urine à l'intérieur des voies excrétrices","Présence de sang dans les urines","Présence de calculs dans le rein","Augmentation de la créatinine"],"a":0},{"c":34,"q":"À l'âge adulte, chez qui les infections urinaires sont-elles plus fréquentes ?","x":"À l'âge adulte, plus fréquentes chez la femme (rapports, grossesses) ; chez l'homme elles augmentent après 50 ans (prostate) ; chez le petit enfant plus fréquentes chez le garçon.","mn":"Femme adulte, homme > 50 ans.","kid":"Les femmes ont un tuyau urinaire plus court, les microbes montent plus facilement.","t":"qcm","o":["Chez la femme, en rapport avec l'activité génitale","Chez l'homme jeune","Chez le nourrisson fille uniquement","Elles sont égales dans les deux sexes"],"a":0},{"c":34,"q":"Quel traitement le cours propose-t-il pour une infection urinaire basse non compliquée ?","x":"Amoxicilline 3 g ou cotrimoxazole ou fluoroquinolone en une dose unique pour les infections urinaires basses non compliquées ; récidive : 3 jours.","mn":"Cystite simple = dose unique.","kid":"Un seul gros comprimé peut suffire pour une infection simple de la vessie.","t":"qcm","o":["Dose unique : amoxicilline 3 g ou cotrimoxazole ou fluoroquinolone","Antibiotique pendant 6 mois","Aucun traitement","Corticoïdes"],"a":0},{"c":34,"q":"Il est conseillé d'uriner toutes les 2 à 3 heures et immédiatement après les rapports sexuels pour prévenir les infections urinaires.","x":"Prévention : uriner toutes les 2-3 h, vider complètement la vessie, uriner après les rapports, boire abondamment, éviter les irritants (thé, café, cola).","mn":"Boire, uriner souvent, uriner après.","kid":"Faire souvent pipi chasse les microbes.","t":"vf","v":1},{"c":34,"q":"La cystite se traduit par une fièvre élevée avec douleur lombaire.","x":"Cystite = vessie = signes bas.","mn":"Cystite = brûle et presse.","kid":"Ça brûle en faisant pipi et on a envie d'y aller tout le temps.","t":"vf","v":0},{"c":34,"q":"Comment appelle-t-on la présence de pus dans les urines ?","x":"L'analyse d'urine dans la cystite révèle une pyurie, des bactéries et souvent des globules rouges (hématurie).","mn":"Pyo = pus.","kid":"Il y a des globules blancs (du pus) dans le pipi.","t":"open","r":"Pyurie","acc":["Pyurie","pyurie","leucocyturie","pyurie","leucocyturie"]},{"c":34,"q":"Quels conseils l'infirmier donne-t-il ?","x":"Boire de grandes quantités en évitant les irritants vésicaux, uriner souvent, vider complètement la vessie, uriner après les rapports.","mn":"Eau oui, café non, vider souvent.","kid":"Il faut boire beaucoup d'eau et ne jamais se retenir.","s":"Mme L., 28 ans, a une cystite récidivante.","t":"qcm","o":["Boire beaucoup en évitant thé/café/cola, uriner toutes les 2-3 h et après les rapports","Boire très peu pour uriner moins","Retenir les urines le plus longtemps possible","Boire beaucoup de café"],"a":0},{"c":34,"q":"Quel facteur le cours évoque-t-il chez l'homme de plus de 50 ans ?","x":"Chez les hommes, la fréquence de l'IU augmente après 50 ans du fait de l'hypertrophie de la prostate ; tout obstacle prédispose à l'infection.","mn":"Homme > 50 ans = prostate.","kid":"La prostate grossit et empêche la vessie de bien se vider.","s":"M. V., 65 ans, présente des infections urinaires répétées et une dysurie.","t":"qcm","o":["L'hypertrophie de la prostate","La grossesse","L'activité génitale de la femme","L'âge scolaire"],"a":0},{"c":35,"q":"Comment se définit l'infection urinaire chronique ?","x":"Infection persistante ou récidivante des voies urinaires inférieures et/ou supérieures.","mn":"Chronique = persiste ou revient.","kid":"L'infection ne part jamais vraiment ou revient sans cesse.","t":"qcm","o":["Infection persistante ou récidivante des voies urinaires inférieures et/ou supérieures","Infection unique guérie en 24 h","Lithiase sans infection","Tumeur de la vessie"],"a":0},{"c":35,"q":"Sur quoi est fondé le traitement antibiotique de l'IU chronique ?","x":"Le traitement antibiotique est fondé sur les cultures et l'antibiogramme de deux échantillons au moins donnant des résultats identiques.","mn":"2 cultures concordantes.","kid":"On cultive le microbe deux fois pour choisir le bon médicament.","t":"qcm","o":["Cultures et antibiogramme d'au moins deux échantillons aux résultats identiques","Un traitement au hasard","La couleur des urines","La température seule"],"a":0},{"c":35,"q":"Quelles complications redoutables de la pyélonéphrite chronique cite le cours ?","x":"La pyonéphrose et la paranéphrite sont des complications redoutables.","mn":"Pyo-néphrose = rein plein de pus.","kid":"Le rein peut se remplir de pus.","t":"qcm","o":["Pyonéphrose et paranéphrite","OAP et asthme","Ulcère et RGO","Varices et TVP"],"a":0},{"c":35,"q":"Les infections urinaires chroniques peuvent évoluer pendant des années sans symptôme apparent malgré une bactériurie significative.","x":"Elles évoluent pendant des années sans symptôme apparent alors qu'il existe une bactériurie significative, avec poussées aiguës de cystite ou pyélite.","mn":"Silencieuse mais présente.","kid":"Les microbes sont là depuis longtemps sans faire mal.","t":"vf","v":1},{"c":35,"q":"À l'UIV, une symétrie parfaite des reins est caractéristique de la pyélonéphrite chronique avec insuffisance rénale.","x":"Les cicatrices rétractent un rein.","mn":"Pyélonéphrite chronique = reins asymétriques.","kid":"Un rein devient plus petit à cause des cicatrices.","t":"vf","v":0},{"c":35,"q":"Citez un terrain favorisant l'infection urinaire chronique à rechercher.","x":"Rechercher : diabète, abus d'analgésiques, foyer infectieux gynécologique/vésiculaire/colique, immunosuppresseurs, obstacles.","mn":"Diabète = sucre pour microbes.","kid":"Certaines maladies comme le diabète aident les microbes à rester.","t":"open","r":"Diabète","acc":["Diabète","diabete","abus d analgesiques","immunosuppresseurs","diabete","analgesique","immunosuppress","obstacle"]},{"c":35,"q":"Quels examens prévoit le cours ?","x":"Diagnostic : examen des urines (leucocyturie, cylindres leucocytaires, bactériologie répétée), recherche d'un terrain favorisant, examen urologique complet.","mn":"Urines + terrain + urologie.","kid":"On analyse le pipi plusieurs fois et on cherche pourquoi ça revient.","s":"Mme D., diabétique, a des infections urinaires à répétition depuis 3 ans.","t":"qcm","o":["Sédiment urinaire (leucocyturie, cylindres), bactériologie répétée, recherche d'un terrain, examen urologique complet","Aucun examen","Uniquement une radio pulmonaire","Une gazométrie"],"a":0},{"c":35,"q":"Quelles molécules le cours propose-t-il ?","x":"Pyocyanique, Proteus, Klebsiella, entérocoques peuvent nécessiter une céphalosporine, la gentamicine ou d'autres aminoglycosides, seuls ou combinés.","mn":"Germe difficile = céphalo/aminoside.","kid":"Pour les microbes résistants, on utilise des antibiotiques plus forts.","s":"Une IU chronique à Proteus résiste aux antibiotiques usuels.","t":"qcm","o":["Céphalosporine, gentamicine ou autres aminosides","Paracétamol seul","Antituberculeux","IPP"],"a":0},{"c":36,"q":"Par quelle voie le rein est-il infecté dans la tuberculose uro-génitale ?","x":"C'est une infection tuberculeuse du rein par voie hématogène à partir d'un foyer pulmonaire, pleural, lymphatique ou indéterminé ; les organes génitaux sont atteints par voie descendante ou hématogène.","mn":"TB rénale = sang depuis le poumon.","kid":"Le microbe voyage dans le sang du poumon vers le rein.","t":"qcm","o":["Voie hématogène à partir d'un foyer pulmonaire, pleural, lymphatique ou indéterminé","Voie ascendante urétrale","Voie cutanée","Voie digestive"],"a":0},{"c":36,"q":"Quel résultat urinaire doit toujours évoquer la tuberculose rénale ?","x":"Une leucocyturie abondante (pyurie) stérile sur milieux de culture usuels doit toujours évoquer la tuberculose rénale ; recherche du BK répétée au moins 3 fois.","mn":"Pyurie stérile = BK.","kid":"Il y a du pus dans le pipi mais les cultures habituelles ne trouvent pas de microbe.","t":"qcm","o":["Leucocyturie abondante stérile sur milieux usuels","Glycosurie","Cétonurie","Urines parfaitement normales"],"a":0},{"c":36,"q":"Quelle est la durée initiale de la trithérapie dans la TB uro-génitale selon le cours ?","x":"Trithérapie jusqu'à stabilisation des lésions et stérilisation des urines (2 à 3 mois), puis bithérapie (selon ce chapitre ; le chapitre Tuberculose p. 57 décrit une quadrithérapie de 2 mois).","mn":"Uro-TB : tri puis bi.","kid":"On prend trois médicaments 2-3 mois, puis deux.","t":"qcm","o":["2 à 3 mois, jusqu'à stabilisation et stérilisation des urines, puis bithérapie","1 semaine","10 ans","Aucun traitement médical"],"a":0},{"c":36,"q":"La tuberculose rénale débute de façon insidieuse par fatigue, fébricule vespérale et sueurs nocturnes.","x":"Le cours le précise ; quand la vessie est atteinte : cystite avec dysurie, pollakiurie, hématurie terminale.","mn":"TB = soir fiévreux, nuit en sueur.","kid":"On est fatigué, un peu chaud le soir et on transpire la nuit.","t":"vf","v":1},{"c":36,"q":"La tuberculose génitale chez la femme ne cause jamais de stérilité.","x":"Atteinte des trompes → stérilité.","mn":"TB génitale = trompes bouchées.","kid":"Le microbe abîme les trompes et empêche d'avoir des enfants.","t":"vf","v":0},{"c":36,"q":"Quelle intervention chirurgicale est indiquée en cas de destruction étendue du rein tuberculeux ?","x":"La néphrectomie totale ou partielle est indiquée dans la destruction étendue du rein ; épididymectomie si infection récidivante ; réimplantation urétérale si sténose.","mn":"Néphr-ectomie = enlever le rein.","kid":"Si le rein est détruit, on l'enlève.","t":"open","r":"Néphrectomie","acc":["Néphrectomie","nephrectomie totale","nephrectomie partielle","nephrectomie","nephrectomie"]},{"c":36,"q":"Quel diagnostic évoquer ?","x":"Antécédent de TB + cystite + hématurie terminale + pyurie stérile = tuberculose urinaire ; rechercher le BK au moins 3 fois.","mn":"TB ancienne + pyurie stérile = TB rénale.","kid":"Le microbe de la tuberculose s'est installé dans ses voies urinaires.","s":"M. H., ancien tuberculeux pulmonaire, présente une pollakiurie, une dysurie et une hématurie en fin de miction ; ECBU : leucocyturie, culture stérile.","t":"qcm","o":["Tuberculose uro-génitale","Lithiase biliaire","Cystite à E. coli banale","Syndrome néphrotique"],"a":0},{"c":36,"q":"Quel prélèvement réaliser ?","x":"Le chapitre Tuberculose (p. 56) : TB rénale → prélever la totalité de la miction du matin 3 jours ; le chapitre uro-génital (p. 166) : recherche du BK répétée au moins 3 fois.","mn":"Urines du matin × 3.","kid":"On garde tout le pipi du matin trois jours de suite.","s":"On suspecte une tuberculose rénale chez Mme J.","t":"qcm","o":["Totalité de la miction du matin, 3 jours de suite, pour recherche de BK","Une seule urine en fin de journée","Un prélèvement de crachat unique","Une gazométrie"],"a":0},{"c":37,"q":"Comment se définit l'insuffisance rénale aiguë ?","x":"L'IRA est la défaillance rapidement progressive, souvent transitoire, de la fonction excrétrice rénale empêchant le maintien de l'équilibre interne.","mn":"Aiguë = rapide et souvent réversible.","kid":"Les reins arrêtent brusquement de bien filtrer, mais ça peut revenir.","t":"qcm","o":["Défaillance rapidement progressive, souvent transitoire, de la fonction excrétrice rénale","Détérioration lente et irréversible de la fonction rénale","Infection de la vessie","Calcul du rein"],"a":0},{"c":37,"q":"Comment classe-t-on les causes de l'IRA ?","x":"Causes pré-rénales (hypovolémie, choc), rénales (ischémie prolongée, néphrotoxiques, AINS), post-rénales (calcul, tumeur, prostate, rétrécissement).","mn":"Avant – Dans – Après le rein.","kid":"Le problème peut être avant le rein, dans le rein ou après le rein.","t":"qcm","o":["Pré-rénales, rénales, post-rénales","Hautes et basses","Virales et bactériennes uniquement","Congénitales seulement"],"a":0},{"c":37,"q":"Quelle valeur de kaliémie menace la vie du malade en IRA selon le cours ?","x":"La kaliémie peut augmenter rapidement, surtout en cas d'acidose, et atteindre un seuil menaçant la vie (> 6,5 mmol/l).","mn":"K+ > 6,5 = danger cardiaque.","kid":"Trop de potassium peut arrêter le cœur.","t":"qcm","o":["Plus de 6,5 mmol/l","3,5 mmol/l","2 mmol/l","4 mmol/l"],"a":0},{"c":37,"q":"Les AINS peuvent provoquer une IRA, surtout chez la personne âgée, en altérant l'irrigation rénale.","x":"Les AINS interfèrent avec les prostaglandines qui protègent le flux sanguin rénal.","mn":"AINS + vieux = reins en danger.","kid":"Ces médicaments réduisent le sang qui arrive aux reins.","t":"vf","v":1},{"c":37,"q":"Pendant la phase diurétique de l'IRA, le patient n'est plus exposé aux infections.","x":"Vigilance infectieuse maintenue.","mn":"Phase diurétique = fragile.","kid":"Même quand il recommence à uriner, il attrape facilement des microbes.","t":"vf","v":0},{"c":37,"q":"Selon le cours, en dessous de quel volume urinaire quotidien parle-t-on d'oligurie dans la phase oligo-anurique de l'IRA (en ml) ?","x":"Phase oligo-anurique : débit urinaire journalier < 400 ml (p. 168, rubrique symptômes) ; la physiopathologie de la même page cite < 500 ml : divergence interne signalée.","mn":"Oligurie < 400-500 ml.","kid":"Le corps fait moins d'un demi-litre de pipi par jour.","t":"open","r":"400 ml","acc":["400 ml","400","500 ml","400","500"]},{"c":37,"q":"Quelle vigilance infirmière est conforme au cours ?","x":"L'infirmière vérifie minutieusement solutions parentérales, substances ingérées et médicaments pour s'assurer qu'ils ne contiennent pas de potassium ; à l'affût des signes cardiaques et musculo-squelettiques d'hyperkaliémie.","mn":"IRA = zéro potassium ajouté.","kid":"Il ne faut rien lui donner qui contient du potassium.","s":"M. W., en IRA oligo-anurique, a une kaliémie à 6,2 mmol/l.","t":"qcm","o":["Vérifier qu'aucune perfusion, aliment ou médicament ne contient de potassium et guetter les signes cardiaques d'hyperkaliémie","Donner des bananes","Perfuser du KCl","Ignorer la kaliémie"],"a":0},{"c":37,"q":"Que traduit ce tableau et que faire ?","x":"Pour dépister les déséquilibres hydriques : apports, débit urinaire, poids, œdèmes, jugulaires, bruits anormaux ; informer immédiatement le médecin de toute détérioration.","mn":"Poids ↑ + œdèmes + jugulaires = surcharge.","kid":"Son corps garde trop d'eau, ce qui peut noyer les poumons.","s":"Mme P., en IRA, prend 2 kg en 24 h, a des œdèmes et des jugulaires turgescentes.","t":"qcm","o":["Une surcharge hydrique : informer immédiatement le médecin","Une déshydratation : faire boire","Un tableau normal","Une hypoglycémie"],"a":0},{"c":38,"q":"Comment se définit l'insuffisance rénale chronique ?","x":"IRC : détérioration progressive et irréversible de la fonction rénale, avec déséquilibres hydroélectrolytiques, conduisant à l'urémie.","mn":"Chronique = irréversible.","kid":"Les reins s'abîment lentement et ne se réparent plus.","t":"qcm","o":["Détérioration progressive et irréversible de la fonction rénale conduisant à l'urémie","Défaillance brutale et réversible","Infection rénale aiguë","Calcul rénal"],"a":0},{"c":38,"q":"Pourquoi l'insuffisant rénal chronique est-il anémique ?","x":"Anémie par production inadéquate d'érythropoïétine, faible longévité des globules rouges, carences et saignements digestifs.","mn":"Rein = EPO = globules rouges.","kid":"Les reins fabriquent une hormone qui fait les globules rouges ; malades, ils en font moins.","t":"qcm","o":["Production inadéquate d'érythropoïétine (et faible longévité des GR, carences, saignements)","Excès de fer","Excès d'érythropoïétine","Hyperactivité de la moelle"],"a":0},{"c":38,"q":"Quels traitements sont nécessaires pour maintenir en vie le patient en IRC terminale ?","x":"L'atteinte rénale étant irréversible, la dialyse ou la greffe du rein sont nécessaires pour garder le patient en vie.","mn":"IRC terminale = dialyse ou greffe.","kid":"Une machine ou un nouveau rein doit faire le travail.","t":"qcm","o":["La dialyse ou la greffe du rein","Les antibiotiques seuls","Les IPP","La kinésithérapie seule"],"a":0},{"c":38,"q":"Le « givre d'urée » est une poudre blanche de cristaux d'urée qui se dépose sur la peau au stade avancé de l'IRC.","x":"Au stade avancé : somnolence, respiration de Kussmaul, coma, convulsions, givre d'urée sur la peau.","mn":"Givre = urée sur la peau.","kid":"L'urée s'accumule tellement qu'elle sort par la peau comme de la poudre blanche.","t":"vf","v":1},{"c":38,"q":"Chez l'IRC, la banane, l'avocat et le chocolat sont des aliments recommandés.","x":"Aliments riches en potassium à éviter.","mn":"Banane-avocat-chocolat = potassium.","kid":"Ces aliments contiennent beaucoup de potassium que les reins malades ne peuvent pas éliminer.","t":"vf","v":0},{"c":38,"q":"Quel type de dialyse utilise un cathéter intrapéritonéal et la membrane péritonéale ?","x":"Deux méthodes : dialyse péritonéale (liquide injecté par cathéter intrapéritonéal, échanges à travers le péritoine) et dialyse rénale/hémodialyse (membrane semi-perméable).","mn":"Péritonéale = ventre filtre.","kid":"On met du liquide dans le ventre qui nettoie le sang à travers une fine peau.","t":"open","r":"Dialyse péritonéale","acc":["Dialyse péritonéale","dialyse peritoneale","peritoneale"]},{"c":38,"q":"Que lui conseille le cours ?","x":"Éducation : se peser quotidiennement et tenir une courbe ; prise de poids, œdèmes, diminution de la diurèse = contacter un médecin ; restriction hydrique ; posologies adaptées ; vaccination hépatite B.","mn":"Poids quotidien = sentinelle.","kid":"Il se pèse tous les jours pour savoir s'il garde trop d'eau.","s":"M. N., IRC sous dialyse, demande comment se surveiller à domicile.","t":"qcm","o":["Se peser chaque jour, tenir une courbe, contacter le médecin si poids ↑, œdèmes ou diurèse ↓","Boire sans limite","Arrêter la dialyse s'il se sent bien","Manger des bananes chaque jour"],"a":0},{"c":38,"q":"Quelle complication le cours décrit-il ?","x":"Baisse du calcium → ↑ parathormone → perte osseuse = ostéodystrophie ; déficit en vitamine D active → ostéomalacie.","mn":"Rein ↓ → Ca ↓ → PTH ↑ → os ↓.","kid":"Le corps prend le calcium des os parce que les reins ne gardent plus l'équilibre.","s":"Mme T., IRC évoluée, présente des douleurs osseuses ; on note une hypocalcémie et une hyperparathyroïdie.","t":"qcm","o":["Ostéodystrophie rénale par perte osseuse de calcium","Ostéoporose post-ménopausique isolée","Fracture traumatique","Arthrose"],"a":0},{"c":39,"q":"Quelle association caractérise le syndrome néphrotique ?","x":"Le SN se caractérise par une protéinurie marquée, une hypoalbuminémie, un œdème et une hypercholestérolémie ; toujours associé à une atteinte glomérulaire grave.","mn":"PHOH : Protéinurie, Hypoalbuminémie, Œdème, Hypercholestérolémie.","kid":"Les reins laissent fuir les protéines et le corps gonfle.","t":"qcm","o":["Protéinurie marquée, hypoalbuminémie, œdème, hypercholestérolémie","Hématurie, HTA, oligurie isolées","Fièvre, toux, hémoptysie","Ictère, prurit, ascite"],"a":0},{"c":39,"q":"Quelles sont les caractéristiques de l'œdème du syndrome néphrotique ?","x":"Le SN s'accompagne d'une rétention liquidienne évoluant lentement vers un œdème qui prend le godet.","mn":"Néphrotique = godet.","kid":"Quand on appuie sur la jambe gonflée, le doigt laisse un creux.","t":"qcm","o":["Œdème qui prend le godet, d'évolution lente","Œdème dur unilatéral sans godet","Absence d'œdème","Œdème uniquement pulmonaire"],"a":0},{"c":39,"q":"Quel médicament est prescrit pour réduire la protéinurie dans le syndrome néphrotique ?","x":"Œdème grave : régime pauvre en sodium, diurétiques, stéroïdes (prednisone) pour réduire la protéinurie ; ciclosporine si corticorésistance.","mn":"SN = cortisone.","kid":"Un médicament anti-inflammatoire puissant ferme un peu les fuites du rein.","t":"qcm","o":["Prednisone (corticoïde)","Amoxicilline","Furosémide seul","Héparine"],"a":0},{"c":39,"q":"Dans le syndrome néphrotique, le cours prescrit un régime à haute teneur en protéines.","x":"On prescrit un régime à haute teneur en protéines afin de régénérer les tissus et de reconstituer la réserve de protéines (notion du cours).","mn":"Fuite de protéines → apport de protéines.","kid":"Comme on perd des protéines, on en mange plus.","t":"vf","v":1},{"c":39,"q":"Le syndrome néphrotique ne survient que chez l'enfant.","x":"Fréquent chez l'enfant mais pas exclusif.","mn":"Tout âge.","kid":"Les enfants l'ont souvent, mais les adultes aussi.","t":"vf","v":0},{"c":39,"q":"Citez une complication du syndrome néphrotique.","x":"Complications : infection, hypercoagulabilité, accélération de l'athérogenèse ; risque d'insuffisance rénale terminale si protéinurie + créatinine élevée.","mn":"SN : infection, caillot, athérome.","kid":"Le corps se défend moins bien et le sang coagule trop.","t":"open","r":"Infection","acc":["Infection","hypercoagulabilite","atherogenese","infections","thrombose","infection","coagul","atherog","thrombo","insuffisance"]},{"c":39,"q":"Quel diagnostic ?","x":"Protéinurie + hypoalbuminémie + œdèmes + hypercholestérolémie = syndrome néphrotique, fréquent chez l'enfant.","mn":"Œdèmes + protéinurie = SN.","kid":"Ses reins laissent passer les protéines et son corps gonfle d'eau.","s":"Un enfant de 6 ans présente des œdèmes des paupières et des jambes prenant le godet ; protéinurie massive, albumine basse, cholestérol élevé.","t":"qcm","o":["Syndrome néphrotique","Néphropathie gravidique","Lithiase urinaire","Cystite"],"a":0},{"c":39,"q":"Quel rôle infirmier ?","x":"Le patient sous stéroïdes ou ciclosporine doit recevoir de l'information sur ce traitement ; stade avancé : soins de l'IRC ; régime pauvre en sodium si œdème grave.","mn":"Cortisone = informer + surveiller.","kid":"On lui explique son médicament et on surveille son poids et ses œdèmes.","s":"Mme U. reçoit de la prednisone au long cours pour un syndrome néphrotique.","t":"qcm","o":["Informer sur les effets du traitement et surveiller œdèmes, poids, régime pauvre en sel","Arrêter brusquement les corticoïdes","Régime très salé","Aucune information"],"a":0},{"c":40,"q":"Quelle triade caractérise la néphropathie gravidique vraie (toxémie gravidique) ?","x":"Elle se traduit par l'apparition, au cours d'une grossesse, d'un ou plusieurs signes de la triade : protéinurie, œdèmes des MI, HTA.","mn":"POH : Protéinurie, Œdèmes, HTA.","kid":"Pendant la grossesse : tension trop forte, jambes gonflées et protéines dans le pipi.","t":"qcm","o":["Protéinurie, œdèmes des membres inférieurs, HTA","Fièvre, toux, dyspnée","Ictère, prurit, ascite","Hématurie, colique, fièvre"],"a":0},{"c":40,"q":"Quelle proportion des femmes enceintes est affectée par la néphropathie gravidique selon le cours ?","x":"La néphropathie gravidique affecte environ 5 % des femmes enceintes.","mn":"1 sur 20.","kid":"Environ une femme enceinte sur vingt.","t":"qcm","o":["Environ 5 %","50 %","0,01 %","25 %"],"a":0},{"c":40,"q":"Quelle position de repos est préconisée en cas de néphropathie gravidique ?","x":"Mesures immédiates : repos en décubitus gauche, hypotenseurs éventuels (clonidine, alphaméthyldopa, hydralazine ; bêtabloquants si échec), hospitalisation obstétricale près du terme.","mn":"Enceinte = côté gauche.","kid":"Couchée sur le côté gauche, le sang circule mieux vers le bébé.","t":"qcm","o":["Décubitus latéral gauche","Décubitus dorsal strict","Position de Trendelenburg","Décubitus ventral"],"a":0},{"c":40,"q":"La néphropathie gravidique vraie survient électivement chez la primipare, surtout au 3e trimestre, et régresse après l'accouchement sans séquelles.","x":"Critères typiques : primipare, 3e trimestre, régression rapide après l'accouchement sans séquelles, pas de récidive habituelle.","mn":"Vraie = 1re grossesse, 3e trimestre, guérit.","kid":"Ça arrive surtout à la première grossesse, en fin de grossesse, et ça part après.","t":"vf","v":1},{"c":40,"q":"La néphropathie gravidique « ajoutée » guérit toujours complètement après l'accouchement et ne récidive jamais.","x":"Ajoutée = maladie préexistante.","mn":"Ajoutée = tôt, persiste, récidive.","kid":"Quand les reins étaient déjà malades avant, ça ne guérit pas complètement.","t":"vf","v":0},{"c":40,"q":"Citez un antihypertenseur utilisable chez la femme enceinte selon le cours.","x":"Hypotenseurs utilisables : clonidine (Catapressan), alphaméthyldopa (Aldomet), hydralazine ; bêtabloquants en cas d'échec.","mn":"Grossesse : Méthyldopa, Clonidine, Hydralazine.","kid":"Certains médicaments contre la tension sont sans danger pour le bébé.","t":"open","r":"Alphaméthyldopa (Aldomet)","acc":["Alphaméthyldopa (Aldomet)","methyldopa","aldomet","clonidine","hydralazine","catapressan","methyldopa","aldomet","clonidine","catapressan","hydralazine"]},{"c":40,"q":"Quelle complication ?","x":"Complications de la néphropathie gravidique : mort fœtale in utero, hématome rétroplacentaire, éclampsie (accidents convulsifs).","mn":"Convulsions + HTA de grossesse = éclampsie.","kid":"La tension trop forte pendant la grossesse provoque une crise convulsive.","s":"Mme Z., primipare à 34 SA, a une PA à 165/110, des œdèmes et une protéinurie ; elle présente brutalement des convulsions.","t":"qcm","o":["Éclampsie","Épilepsie connue","Hypoglycémie","Tétanie simple"],"a":0},{"c":40,"q":"Que recommande le cours ?","x":"Facteurs de risque : antécédents de surpoids, hypercholestérolémie, diabète, HTA, tabagisme → surveillance particulièrement étroite.","mn":"Facteurs de risque = surveillance serrée.","kid":"Comme elle a plusieurs risques, on la suit de très près.","s":"Une femme enceinte en surpoids, diabétique et fumeuse débute sa grossesse.","t":"qcm","o":["Une surveillance particulièrement étroite de la grossesse (femme à risque de néphropathie gravidique)","Aucune surveillance particulière","Arrêter le suivi prénatal","Un régime très salé"],"a":0}],"cards":[{"c":0,"f":"Citez les éléments constituant les voies aériennes supérieures et inférieures.","b":"Supérieures : **fosses nasales**, **pharynx** (rhino-, oro-, hypopharynx), **larynx** · Inférieures : **trachée** et **bronches**","mn":"Nez → Pharynx → Larynx | Trachée → Bronches"},{"c":0,"f":"Définissez le médiastin et citez 5 éléments qu'il contient.","b":"**Définition** : région médiane du thorax séparant les deux régions pleuro-pulmonaires · **Cœur** (en avant et en bas) · **Gros vaisseaux** sanguins · **Trachée** · **Œsophage** · **Canal thoracique**, nerfs, vaisseaux et ganglions lymphatiques"},{"c":0,"f":"Citez les volumes pulmonaires et leurs valeurs selon le cours.","b":"**Volume courant** ≈ 0,5 l · **Volume de réserve inspiratoire** ≈ 2 l · **Volume de réserve expiratoire** ≈ 1,5 l · **Volume résiduel** : air restant après une expiration forcée","mn":"Courant ½ – Inspi 2 – Expi 1,5"},{"c":0,"f":"Décrivez les deux mouvements respiratoires.","b":"**Inspiration** : phénomène **actif**, muscles inspirateurs, augmente la cage thoracique dans tous ses diamètres · **Expiration** : phénomène **passif**, la cage thoracique revient sur elle-même"},{"c":1,"f":"Définissez la PFLA et citez son principal germe et les populations à risque.","b":"Infection pulmonaire aiguë touchant un lobe, due principalement (**80-90 %**) au **pneumocoque** · Populations à risque : **jeunes enfants**, **personnes âgées**, **immunodéprimés**"},{"c":1,"f":"Citez 6 signes de la phase d'état de la PFLA.","b":"**Fièvre en plateau à 40 °C** · **Tachycardie** · **Oligurie**, urines foncées · **Asthénie** intense, AEG · **Langue saburrale**, anorexie · Signes physiques : **matité** franche, **râles crépitants**"},{"c":1,"f":"Citez les examens complémentaires de la PFLA et leurs résultats.","b":"**Radiographie pulmonaire** face et profil : opacité dense, homogène, systématisée + **bronchogramme aérien** · **Examen des crachats** : présence du germe · **NFS** : **hyperleucocytose** à polynucléaires"},{"c":1,"f":"Citez 6 actions de l'infirmier devant une PFLA.","b":"Accueillir et **installer** le malade · **Recueillir les expectorations** à jeun, 3 jours de suite, labo dans l'heure · Faire les **prélèvements sanguins** prescrits · **Administrer les traitements** prescrits (ATB, antipyrétique, fluidifiant) · Faire **boire 2 à 3 l/jour** pour fluidifier les sécrétions · Établir une **feuille de surveillance** (T°, pouls, FR)"},{"c":2,"f":"Définissez la bronchite aiguë.","b":"Infection aiguë des **voies aériennes inférieures** · **Inflammation de la muqueuse** des bronches et bronchioles **sans atteinte parenchymateuse** · Œdème et **augmentation des sécrétions** bronchiques · Origine **principalement virale**"},{"c":2,"f":"Décrivez les deux phases de la bronchite aiguë.","b":"**Phase sèche** : fièvre rarement > 38 °C, **toux sèche quinteuse**, brûlure rétrosternale, précédée de signes ORL · **Phase humide** : toux devenant **grasse/productive**, expectoration muqueuse puis muco-purulente"},{"c":2,"f":"Citez les 3 critères qui justifient une antibiothérapie dans la bronchite aiguë.","b":"**Tabagisme** · **Toux persistante** et **expectoration purulente au-delà de J7** · **Râles bronchiques diffus** à l'auscultation","mn":"Tabac – Toux J7 – Râles"},{"c":2,"f":"Citez 4 facteurs favorisants de la bronchite aiguë.","b":"**Jeunes enfants** et **personnes âgées** · **Déficit immunitaire** d'origine génétique · **Défaut génétique des cils** bronchiques · Infection préalable des **voies respiratoires supérieures**"},{"c":3,"f":"Citez les signes fonctionnels et physiques de la pleurésie.","b":"Fonctionnels : **point de côté** majoré par la toux et l'inspiration, **toux sèche**, **dyspnée**, fièvre selon l'étiologie · Physiques : **abolition des vibrations vocales**, **abolition du murmure vésiculaire**, **matité** · Au début : **frottement pleural** (cuir neuf)"},{"c":3,"f":"Citez les buts de la ponction pleurale.","b":"**Diagnostique** : ponction exploratrice, ponction-biopsie · **Évacuatrice** · **Thérapeutique** : lavage de la plèvre, injection médicamenteuse","mn":"D-E-T"},{"c":3,"f":"Citez les éléments de surveillance pendant une ponction pleurale.","b":"**Pouls**, **faciès**, **malaises** · **Perméabilité** du système de drainage · **Débit**, **quantité**, **aspect** du liquide · Malaise, sueur, dyspnée, toux → **arrêter la ponction** · **Noter la quantité** ponctionnée"},{"c":3,"f":"Citez les incidents et accidents de la ponction pleurale.","b":"Incidents : **ponction blanche**, **lipothymie** · Accidents : **œdème aigu du poumon**, **embolie gazeuse**"},{"c":4,"f":"Citez les 3 catégories d'insuffisance respiratoire selon l'origine du dysfonctionnement.","b":"**Syndrome obstructif** : bronchite chronique, asthme (anomalie du diffuseur gazeux) · **Syndrome restrictif** : affections neuromusculaires, cyphoscoliose (anomalie de la pompe) · **Syndrome mixte** : association des deux","mn":"O-R-M"},{"c":4,"f":"Citez 6 causes d'insuffisance respiratoire aiguë.","b":"**Noyade** · **Inhalation d'un corps étranger** · **État de mal asthmatique** · **Intoxication à l'oxyde de carbone** · **Intoxication médicamenteuse** (barbituriques, somnifères) · Atteinte neurologique (**poliomyélite**), altération de la membrane alvéolo-capillaire"},{"c":4,"f":"Citez le bilan paraclinique de l'insuffisance respiratoire chronique.","b":"**Gazométrie** · **Radiographie pulmonaire** · **ECG** · **NFS, ionogramme sanguin** · **Exploration fonctionnelle respiratoire**"},{"c":4,"f":"Citez le traitement de l'insuffisance respiratoire chronique.","b":"**Kinésithérapie respiratoire** · **Fluidifiants / mucolytiques** · **Antibiotiques** · **Oxygénothérapie** · **Ventilation assistée** en réanimation · **Éviction des pollutions** toxiques"},{"c":5,"f":"Donnez les valeurs normales de la gazométrie artérielle.","b":"**pH** : 7,38 à 7,42 · **PaCO2** : 38 à 42 mmHg · **PaO2** : 90 ± 5 mmHg · **HCO3-** : 22 à 25 mmol/l · **Saturation** : 97 à 100 %"},{"c":5,"f":"Citez les sites de prélèvement pour la gazométrie.","b":"Sang artériel : **artère radiale**, **humérale**, **fémorale** · Sang capillaire : **extrémité d'un doigt**, **lobe de l'oreille**"},{"c":5,"f":"Décrivez le test d'Allen.","b":"Bras en l'air, **comprimer radiale et cubitale** pour vider la main · Quand la main est **blanche**, baisser le bras et **relâcher la cubitale** · Si la main **se recolore** : la cubitale prend le relais → ponction possible"},{"c":5,"f":"Citez 5 incidents de la gazométrie.","b":"**Douleur / fourmillement** · **Hématome** (mauvaise compression) · **Thrombose artérielle** (ponctions répétées) · **Ischémie**, piqûre du **nerf radial** · **Résultats erronés** (prélèvement veineux, retard, bulles d'air)"},{"c":6,"f":"Citez les 4 affections regroupées sous le terme BPCO selon le cours.","b":"**Dilatation des bronches** (DDB) · **Bronchite chronique** · **Asthme** · **Emphysème**","mn":"DBAE"},{"c":6,"f":"Citez les signes d'une crise d'asthme.","b":"**Prodromes** : éternuements, céphalées, prurit, rhinorrhée, anxiété · **Bradypnée expiratoire sifflante**, sensation d'étouffement, angoisse · **Toux** inefficace, souvent **nocturne** · Examen : **tachycardie**, **thorax distendu**, **râles sibilants**"},{"c":6,"f":"Décrivez le traitement de la crise d'asthme.","b":"**Aérosols de bêta-2 mimétiques** (salbutamol, Bricanyl) + **bromure d'ipratropium** · Échec : **bêta-2 IV ou SC** + **corticoïde** (HSHC) · **Antibiotique** (bétalactamine, macrolide), **mucolytique** · **Oxygénothérapie** 3 à 5 l/min dans les formes sévères"},{"c":6,"f":"Citez les mesures générales de l'infirmier devant une crise d'asthme.","b":"Installer en position **assise ou ½ assise** · **Ouvrir** portes et fenêtres, **aérer** · **Desserrer** les vêtements · **Rassurer**, **appeler le médecin** · Placer la **sonnette** à portée"},{"c":6,"f":"Citez 4 complications de l'emphysème.","b":"**Insuffisance respiratoire chronique** avec poussées aiguës · **Surinfections** bronchiques · **Pneumothorax** (rupture d'une bulle) · **Insuffisance cardiaque droite**"},{"c":7,"f":"Citez les causes de l'OAP selon le cours.","b":"**Cardiaques** : insuffisance cardiaque gauche, **HTA**, **rétrécissement mitral** · **Infectieuses** : grippe, rougeole · **Toxiques** : gaz irritants, **monoxyde de carbone** · **Iatrogènes** : **perfusions/transfusions** trop abondantes et rapides · **Neurologiques** : tumeurs cérébrales, traumatisme crânien"},{"c":7,"f":"Citez 4 signes de gravité de l'OAP.","b":"**Troubles de la conscience** · **Cyanose**, **sueurs** · **PA < 100 mmHg** · **Bradycardie < 70/min**"},{"c":7,"f":"Décrivez le traitement d'urgence de l'OAP.","b":"Position **assise, jambes pendantes** · **Diurétique IV** (Lasilix®) · **Dérivés nitrés** (trinitrine) · **Oxygène à fort débit** (6 l/min) · Formes graves : **transfert** en service spécialisé"},{"c":7,"f":"Citez les examens paracliniques de l'OAP.","b":"**Radiographie thoracique** · **ECG** · **Gaz du sang** · **Enzymes cardiaques**"},{"c":8,"f":"Définissez le cancer bronchopulmonaire.","b":"**Tumeur maligne primitive** dont le point de départ est une **bronche** · Développée à partir des **cellules tapissant la paroi bronchique** · Limitée aux bronches : **cancer bronchique** ; envahit le poumon : **cancer bronchopulmonaire**"},{"c":8,"f":"Citez 5 facteurs de risque du cancer bronchopulmonaire.","b":"**Tabagisme actif** (80-90 %) · **Tabagisme passif** (20 % des cancers des non-fumeurs) · **Sexe féminin** à tabagisme égal · **Facteurs professionnels** : mines (fer, uranium, or, arsenic, nickel), **amiante** · **Pollution atmosphérique**"},{"c":8,"f":"Citez les éléments du choix et les méthodes de traitement du cancer bronchique.","b":"Choix selon : **état général**, **extension locale**, **extension générale**, **type histologique** · Méthodes : **chimiothérapie**, **radiothérapie**, **chirurgie**"},{"c":8,"f":"Citez le bilan biologique auquel participe l'infirmier dans le cancer bronchique.","b":"**NFS** · **Vitesse de sédimentation** · **Ionogramme sanguin** · **Bilan hépatique** (transaminases, bilirubine) et **rénal** (créatinine)"},{"c":9,"f":"Citez les règles du traitement antituberculeux.","b":"Jamais un seul médicament : **au moins deux** · **Respecter les doses** prescrites · Traitement **régulier** · Traitement **long : au moins 6 mois** · **Une prise le matin à jeun**"},{"c":9,"f":"Citez les médicaments de la quadrithérapie et leur posologie.","b":"**Isoniazide** (Rimifon®) 5 mg/kg/j · **Rifampicine** (Rifadine®) 10 mg/kg/j · **Éthambutol** (Myambutol®) 20 mg/kg/j · **Pyrazinamide** (Pirilène®) 25 mg/kg/j · Pendant **2 mois**, puis **INH + RMP** 4 à 10 mois","mn":"I-R-E-P : 5-10-20-25"},{"c":9,"f":"Citez les signes évocateurs de la tuberculose pulmonaire.","b":"Généraux : **asthénie**, **anorexie**, **amaigrissement**, fièvre, sueurs · **Toux** s'aggravant avec le temps · **Expectoration** muqueuse → muco-purulente → purulente · **Hémoptysie** ou expectoration hémoptoïque · Douleur thoracique, dyspnée"},{"c":9,"f":"Citez les éléments de surveillance du traitement antituberculeux.","b":"**Observance** : couleur orangée des urines (rifampicine), dosages · **Tolérance** : allergie cutanée, **hépatotoxicité** (transaminases), **troubles visuels** (champ visuel, couleurs) · **Efficacité** : radio (J15, J30, M2, M4, M6), bactériologie (J10-J20) · **Isolement respiratoire** jusqu'à négativation de l'examen direct"},{"c":9,"f":"Définissez : primo-infection, ITL et tuberculose maladie.","b":"**Primo-infection** : premier contact avec le BK, symptomatique ou non, suivi du **virage de l'IDR** · **ITL** : infection **sans signe** clinique, bactériologique ou radiologique, **test tuberculinique positif** · **Tuberculose maladie** : infection **active** avec signes cliniques, radiologiques et bactériologiques"},{"c":10,"f":"Décrivez la technique d'injection de la tuberculine.","b":"Reconstituer la solution et **injecter immédiatement** · Gants, **asepsie**, laisser sécher · **10 UI en intradermique**, face **antéro-externe de l'avant-bras** · Peau tendue, **biseau vers le haut**, angle de **15°** · Injecter lentement → **peau d'orange**"},{"c":10,"f":"Expliquez la lecture et l'interprétation de l'IDR.","b":"Lecture entre **J2 et J4**, de préférence à **72 h** · Mesurer l'**induration** dans son **diamètre transversal** · **Positive** : nodule érythémateux **≥ 5 mm** · **Négative** : simple rougeur ou induration < seuil · **Faux négatif** possible après virose ou vaccin vivant"},{"c":10,"f":"Donnez la signification d'une IDR positive.","b":"**Contact avec le BK** · ou **vaccination par le BCG**"},{"c":11,"f":"Citez les circonstances de découverte de l'HTA.","b":"**Découverte fortuite** lors d'un examen de routine · **Signes fonctionnels** : céphalées occipitales matinales, acouphènes, phosphènes, pollakiurie nocturne · **Complications** : hémorragie sous-conjonctivale, épistaxis, AVC, OAP, HTA maligne, toxémie gravidique, dissection aortique"},{"c":11,"f":"Citez les causes de l'HTA secondaire.","b":"**Maladies rénales** · **Maladies endocriniennes** : hyperthyroïdie, phéochromocytome · **Coarctation de l'aorte** · **Médicaments** : anti-inflammatoires, bronchodilatateurs, décongestionnants nasaux, drogues"},{"c":11,"f":"Citez les classes médicamenteuses de l'HTA selon le cours.","b":"**Diurétiques** (Lasilix®) · **Bêtabloquants** (nébivolol) · **Inhibiteurs calciques** · **IEC** · **Antagonistes de l'angiotensine II**"},{"c":11,"f":"Citez les complications cardiaques de l'HTA.","b":"**Hypertrophie ventriculaire gauche** · **Hypertrophie auriculaire gauche** · **IVG** · **Insuffisance coronaire** (angor, IDM) · **Insuffisance cardiaque globale**, **dissection aortique**"},{"c":11,"f":"Décrivez les conditions de mesure de la pression artérielle.","b":"Patient au **repos ≥ 10 min**, assis ou couché, **sans café/tabac 30 min** avant · Salle **calme**, propre, aérée · Personnel : bonne vue/audition, tenue correcte, **traçabilité**, intimité · Matériel **adapté**, en bon état, propre · Mesure **aux deux bras**"},{"c":12,"f":"Citez 6 facteurs de risque de l'insuffisance veineuse.","b":"**Hérédité** · **Âge** · **Obésité**, diabète · **Grossesse** · **Vêtements serrés**, chaussures inadaptées · **Position debout ou assise prolongée**, chaleur"},{"c":12,"f":"Citez les signes fonctionnels de l'insuffisance veineuse.","b":"**Jambes lourdes** avec **œdème vespéral** · **Crampes**, paresthésies nocturnes · **Douleurs** majorées par l'orthostatisme, la chaleur, les règles · **Démangeaisons**"},{"c":12,"f":"Citez le traitement de l'insuffisance veineuse.","b":"**Contention veineuse** (bas, collants) · **Veinotoniques** · **Sclérose** (injection intra-variqueuse) · **Kinésithérapie** · **Chirurgie**"},{"c":12,"f":"Citez 4 complications de l'insuffisance veineuse.","b":"**Jambite** (infection aiguë fébrile) · **Dermite** · **Eczéma** suintant prurigineux · **Ulcère variqueux**"},{"c":13,"f":"Citez 6 facteurs favorisants de la TVP.","b":"**Immobilisation**, **alitement > 24 h** · **Voyage > 3 h** (avion, voiture) · **Chirurgie** (pelvienne, orthopédique) · **Grossesse** et **post-partum** · **Contraception orale**, tabagisme · **Obésité**, âge, cancers, déficits en protéine C/S, antithrombine III"},{"c":13,"f":"Citez les signes cliniques de la TVP.","b":"Généraux : **fièvre**, **tachycardie** · Fonctionnels : fourmillements, **douleur du mollet**, **signe de Homans** · Inspection : **œdème unilatéral dur** sans godet, tuméfaction · Palpation : **chaleur locale**, **diminution du ballottement** du mollet"},{"c":13,"f":"Citez les buts et moyens du traitement de la TVP.","b":"**Prévenir l'extension et la migration** : repos strict, MI surélevés · **Lyser le thrombus** : **anticoagulants** (héparines, AVK) · **Prévenir les récidives** : **bas de contention** · Autre : ablation chirurgicale du caillot"},{"c":13,"f":"Citez les points d'éducation d'un patient sous AVK.","b":"Prise **quotidienne, régulière, à heure fixe** · Rôle du **TP** et de l'**INR** · Bilan **régulier** dans le **même laboratoire** · Savoir **apprécier les résultats** et **appeler** en cas d'anomalie · Reconnaître les **signes hémorragiques**"},{"c":14,"f":"Décrivez les 4 stades de Leriche et Fontaine.","b":"**Stade I** : latence, asymptomatique · **Stade II** : **claudication intermittente** (200-500 m, cède en 1-3 min) · **Stade III** : **douleurs de repos**, nocturnes, pied pendant · **Stade IV** : **troubles trophiques** (ulcérations, **gangrène**)"},{"c":14,"f":"Citez 5 examens paracliniques de l'AOMI.","b":"**Bilan biologique** : groupe-Rh, hémogramme, TP, TCA, ionogramme, urée, créatinine, glycémie, bilan lipidique · **Échographie-doppler vasculaire** · **Angioscanner** · **ECG** · **Radiographie pulmonaire**"},{"c":14,"f":"Citez le traitement de l'AOMI.","b":"**Suppression des facteurs de risque** (tabac, diabète) · **Rééducation** : marche ≥ 1 h/jour · **Antiagrégant plaquettaire** (aspirine) · **Vasodilatateur**, **IEC**, **héparine** · **Antalgiques**"},{"c":14,"f":"Citez les complications de l'AOMI.","b":"**Gangrène** · **Occlusion artérielle aiguë** · **Embolie distale de cholestérol** (insuffisance rénale)"},{"c":15,"f":"Définissez l'embolie pulmonaire.","b":"**Urgence médicale** · **Oblitération brutale**, totale ou partielle, du **tronc de l'artère pulmonaire** ou d'une branche · Par un **corps étranger circulant** (embole) · Point de départ habituel : **TVP des membres inférieurs**"},{"c":15,"f":"Citez les signes cliniques de l'embolie pulmonaire.","b":"**Douleur** type **point de côté** basithoracique, brutale, ↑ à l'inspiration · **Toux** irritative, **crachats hématiques** · **Dyspnée**, **angoisse** · **Fièvre** 38-38,5 °C, **tachycardie** · **Syncope** ou **état de choc**"},{"c":15,"f":"Citez les mesures de prévention de l'embolie pulmonaire.","b":"**Mobilisation active**, **lever précoce** · **Kinésithérapie** au lit · **Anticoagulants préventifs** (HBPM, AVK, Calciparine) · **Bas de contention** · **Dépistage et traitement des phlébites**"},{"c":15,"f":"Citez le bilan spécifique de l'embolie pulmonaire.","b":"**Gazométrie** artérielle · **D-dimères** · Protéines **C, S**, **antithrombine III** · **Radio**, **ECG** · **Échodoppler veineux** des MI, **angioscanner** pulmonaire"},{"c":16,"f":"Décrivez le tableau clinique de l'OAP cardiogénique.","b":"Début **brutal, nocturne**, grésillements laryngés, toux irritative · **Polypnée** intense, angoissante, patient **assis** · **Toux** puis **expectoration mousseuse** (blanc d'œuf battu, parfois saumonée) · Inspection : **battement des ailes du nez**, **sueurs** · PA normale, basse ou très élevée"},{"c":16,"f":"Citez 6 actions de l'infirmier dans l'OAP cardiogénique.","b":"**½ assis jambes pendantes**, **repos strict** · **Oxygénothérapie** · **VVP de gros calibre** (pas de sérum salé) · **Prélèvements** : gazométrie, enzymes cardiaques, TP, TCK · **Sonde vésicale** ou péniflow (diurèse) · **ECG**, contrôle de la **PA**"},{"c":16,"f":"Citez le diagnostic différentiel de l'OAP cité dans le cours et l'élément qui l'oriente.","b":"**Crise d'asthme** · Orientée par l'**interrogatoire** : antécédents d'asthme bronchique"},{"c":16,"f":"Citez les buts du traitement de l'OAP cardiogénique.","b":"**Calmer les douleurs** · **Oxygéner le myocarde** · Mise en route **urgente** = chance de survie"},{"c":17,"f":"Décrivez la physiopathologie de l'IVG.","b":"**En aval** : ↓ débit de perfusion des tissus, notamment des **reins** → **oligurie** · **En amont** : veines pulmonaires mal drainées → **poumons inondés** → **dyspnée**"},{"c":17,"f":"Donnez la classification NYHA de la dyspnée.","b":"**I** : efforts importants **inhabituels**, aucune gêne · **II** : efforts importants **habituels** (marche rapide, côte, > 2 étages) · **III** : efforts **peu intenses** (marche à plat, 2 étages) · **IV** : dyspnée **permanente de repos**"},{"c":17,"f":"Citez les médicaments de l'IVG et leur action.","b":"**IEC** (Lopril®, Renitec®) : vasodilatation, ↓ PA, ↓ rétention d'eau · **Bêtabloquants** : ↓ fréquence cardiaque · **Diurétiques** : éliminent le surplus de liquide (risque **hypokaliémie**)"},{"c":17,"f":"Citez les anomalies de l'ECG dans l'IVG.","b":"**Tachycardie sinusale** · **Hypertrophie ventriculaire gauche** · **Troubles du rythme** (extrasystoles) · **Bloc de branche gauche**"},{"c":18,"f":"Définissez l'IVD et décrivez son retentissement.","b":"**Élévation des pressions de remplissage** du VD ; VD incapable d'adapter son débit au retour veineux · **PVC > 15 cm d'eau** · **En amont** : jugulaires turgescentes, gros foie, OMI · **En aval** : mauvaise perfusion pulmonaire → dyspnée"},{"c":18,"f":"Citez les signes d'hypertension veineuse de l'IVD.","b":"**Hépatomégalie** avec expansion systolique · **Reflux hépato-jugulaire** · **Turgescence spontanée des jugulaires** · **Oligurie** · **Œdèmes des membres inférieurs**"},{"c":18,"f":"Citez les causes de l'insuffisance cardiaque droite.","b":"**Cœur pulmonaire aigu** et **chronique** · **Cardiopathie gauche** (rétrécissement, insuffisance mitrale) · **Cardiomyopathie** (amylose) · **Cardiopathie congénitale** (CIA, CIV)"},{"c":18,"f":"Citez les examens paracliniques de l'IVD.","b":"**Radio** : HTAP, dilatation du VD · **ECG** : surcharge droite, **BBD** · **Échodoppler cardiaque** : cavités droites, IT, HTAP, VCI · **Cathétérisme cardiaque** · Gaz du sang, fonction hépatique, EFR"},{"c":19,"f":"Définissez l'insuffisance cardiaque globale.","b":"**Incapacité du cœur** à assurer le débit nécessaire aux besoins de l'organisme · Maladie touchant **les deux ventricules** en même temps · Mais **surtout le ventricule gauche**"},{"c":19,"f":"Citez 6 signes de l'ICG.","b":"**Dyspnée de repos** · **Turgescence des jugulaires** · **Hépatomégalie douloureuse** · **Anasarque** · **Cyanose**, toux avec crachats hématiques · **Oligo-anurie**"},{"c":19,"f":"Citez les buts du traitement de l'ICG.","b":"**Réduire les besoins en O2** en supprimant l'effort cardiaque · **Réduire la rétention d'eau et de sel** · **Renforcer la contraction cardiaque**"},{"c":20,"f":"Décrivez les caractéristiques de la douleur angineuse.","b":"Circonstance : **à l'effort** · Siège : **rétrosternal médian en barre** · Irradiation : **membre supérieur gauche**, doigts, **mâchoires** · Type : **constrictive** (étau, serrement, broiement) · Durée **brève**, cède à l'arrêt de l'effort et à la **trinitrine** en 1-2 min"},{"c":20,"f":"Citez 6 facteurs de risque de l'angine de poitrine.","b":"**Hérédité** · **HTA** · **Dyslipidémie** · **Tabagisme** · **Diabète** · **Obésité**, sédentarité, contraception orale"},{"c":20,"f":"Citez la CAT infirmière devant un angor en centre de soins qualifié.","b":"Accueillir, installer, **rassurer** · **ECG systématique** · **Constantes** (TA, pouls, T°) · **Noter l'heure** d'arrivée · **Transmettre sans délai** au médecin, exécuter la prescription"},{"c":20,"f":"Citez les examens paracliniques de l'angor.","b":"**Bilan standard** : NFS, glycémie, créatinine, TP, TCA, ionogramme, cholestérol · **ECG** · **Coronarographie**"},{"c":21,"f":"Définissez le syndrome coronarien aigu.","b":"**Obstruction complète** d'une ou plusieurs **artères coronaires** · Douleur **persistante** malgré l'arrêt de l'effort ou les **dérivés nitrés** · Au-delà de **6 heures** : **nécrose** = infarctus du myocarde"},{"c":21,"f":"Décrivez la douleur et les signes d'accompagnement du SCA.","b":"Douleur **rétrosternale**, **violente** (étau), **prolongée** · **Pan-radiante** : dos, mâchoire, épaules, bras/main gauche, épigastre · Apparition **brutale**, matin au réveil ou début d'après-midi · Accompagnement : **sueurs froides**, **pâleur**, fatigue, **nausées**, vomissements"},{"c":21,"f":"Citez la prise en charge initiale du SCA.","b":"**Hospitalisation urgente** (SAMU) · **Perfusion de sérum glucosé** · **Oxygénothérapie** · **Antalgiques** · **Thrombolytique** (ténectéplase, < 8 h) + **anticoagulant** (héparine) · Désobstruction : **fibrinolyse**, **angioplastie + stent**, **pontage**"},{"c":21,"f":"Citez les contre-indications de la thrombolyse selon le cours.","b":"**Délai > 12 heures** · **Âge > 80 ans** · **Hémorragie cérébrale**"},{"c":22,"f":"Citez les caractéristiques de la douleur et les signes physiques de la péricardite.","b":"Douleur ↑ à l'**inspiration** et à la **toux** · ↑ en **décubitus**, ↓ **assis penché en avant** · Contexte de **syndrome grippal** préalable · **Frottement péricardique** (pathognomonique) · **Pouls paradoxal de Kussmaul**"},{"c":22,"f":"Citez les examens paracliniques de la péricardite.","b":"**Biologie** : NFS, VS, CRP, troponine, CPK… · **ECG** : perturbé dans toutes les dérivations, **microvoltage**, alternance électrique · **Radiographie** : **cardiomégalie**, RCT > 0,5"},{"c":22,"f":"Citez les modes évolutifs de la péricardite.","b":"**Favorable** en quelques semaines · **Rechutes** · **Tamponnade** · **Constriction** · **Mort**"},{"c":22,"f":"Citez 6 éléments de la CAT infirmière devant une péricardite aiguë.","b":"**Repos strict** ½ assis ou assis · **Rassurer**, expliquer · **Oxygène**, **VVP de gros calibre** · **Surveiller** les paramètres vitaux · **Matériel de ponction et réanimation** · Lutter contre la **fièvre** et la **constipation**, éviter les mobilisations brutales"},{"c":23,"f":"Définissez : hématémèse et méléna.","b":"**Hématémèse** : sang rouge ou noir **rejeté par la bouche** lors d'efforts de vomissement (hémorragie digestive haute) · **Méléna** : émission par l'anus de **sang digéré noir et fétide** (saignement en amont du côlon droit)"},{"c":23,"f":"Comparez syndrome cholériforme et syndrome dysentérique.","b":"**Cholériforme** : germes **toxinogènes**, diarrhée **aqueuse abondante**, vomissements, **sans fièvre** (ex. choléra) · **Dysentérique** : germes **entéro-invasifs**, diarrhée **fébrile, glaireuse, sanglante**, douleurs, **épreintes, ténesme**"},{"c":23,"f":"Citez les caractéristiques de la colique hépatique.","b":"Cause : **enclavement d'un calcul** (infundibulum, canal cystique) · Siège : **hypochondre droit** et **épigastre** · Irradiation : **omoplate et épaule droites** · **Inhibition respiratoire**, crise de **2 à 4 h** · Vomissements fréquents, **ni fièvre ni ictère**"},{"c":23,"f":"Citez les manifestations de l'hypertension portale et ses 3 types de bloc.","b":"Manifestations : **circulation veineuse collatérale**, **splénomégalie**, **varices œsophagiennes** · Blocs : **intrahépatique** (cirrhose), **suprahépatique** (veines sus-hépatiques), **sous-hépatique** (thrombose porte)"},{"c":24,"f":"Citez les mécanismes physiopathologiques du RGO.","b":"**Faible pression du SIO** · **Relaxations transitoires** fréquentes du SIO · **Augmentation de la pression gastrique** ou retard d'évacuation · Facteur favorisant : **hernie hiatale par glissement**"},{"c":24,"f":"Citez les manifestations typiques et atypiques du RGO.","b":"Typiques : **pyrosis post-prandial**, **pyrosis postural**, **régurgitations** · Atypiques : **brûlures épigastriques isolées**, **toux/asthme**, **pharyngite/laryngite**, **douleur pseudo-angineuse**"},{"c":24,"f":"Citez 3 complications du RGO.","b":"**Œsophagite peptique** · **Sténose peptique** · **Endobrachyœsophage** · **Hémorragies**"},{"c":24,"f":"Citez le traitement du RGO selon la sévérité.","b":"**Règles hygiéno-diététiques** · **Antiacides à la demande** si symptômes peu fréquents · **Anti-H2** ou **IPP** si sévères (IPP souvent en 1re intention) · Œsophagite légère : **IPP 4 à 6 semaines** puis entretien selon symptômes"},{"c":25,"f":"Expliquez la physiopathologie de l'UGD.","b":"**Déséquilibre** entre **agression chlorhydropeptique** et **mécanismes de défense** · Barrière muqueuse : **pré-épithéliale** (mucus, bicarbonates), **épithéliale**, **sous-épithéliale** (flux sanguin) · Causes : **H. pylori**, **AINS**"},{"c":25,"f":"Décrivez le syndrome ulcéreux typique.","b":"Douleur **épigastrique**, **sans irradiation** · Type **crampe** ou **faim douloureuse** · **Calmée** par les aliments ou antiacides · **Rythmée par les repas** (intervalle libre 1-3 h) · Évolution par **poussées** de quelques semaines"},{"c":25,"f":"Décrivez le traitement d'éradication de H. pylori.","b":"Durée : **1 semaine** · **IPP matin et soir** · **2 antibiotiques** parmi : **amoxicilline** 1 g × 2/j, **clarithromycine** 500 mg × 2/j, **métronidazole** 500 mg × 2/j"},{"c":25,"f":"Citez les complications de l'ulcère gastroduodénal.","b":"**Hémorragie** · **Perforation** · **Sténose** · **Transformation cancéreuse** (UG seulement, rare)"},{"c":26,"f":"Citez les signes aspécifiques de l'hépatite virale aiguë.","b":"**Asthénie** · **Céphalées** · **Nausées**, douleurs abdominales · **Fièvre** · **Urticaire**, **arthralgies** · Puis **ictère** 7 à 10 jours après"},{"c":26,"f":"Comparez les modes de transmission des hépatites A, B, C et E.","b":"**A** : **féco-orale** (eau contaminée) · **E** : **féco-orale** (eau), réservoir animal possible · **B** : **IST**, sang · **C** : principalement **parentérale**"},{"c":26,"f":"Citez la situation vaccinale des hépatites selon le cours.","b":"**VHA** : vaccin inactivé très efficace · **VHB** : vaccin efficace > 95 % · **VHE** : vaccin recombinant disponible en Chine · **VHC** : **pas de vaccin**"},{"c":26,"f":"Définissez l'hépatite et l'hépatite chronique, et citez les causes.","b":"**Hépatite** : tout processus **inflammatoire du foie** (↑ transaminases) · **Chronique** : inflammation évolutive **> 6 mois** · Causes aiguës : **virus**, **médicaments** · Causes chroniques : **VHB, VHC**, **alcool**, syndrome métabolique"},{"c":27,"f":"Citez les 5 axes du rôle infirmier dans l'hépatite virale.","b":"**Accueil** (chambre individuelle, matériel personnel) · **Soins** (bilan à jeun, repos, régime, traitement) · **Surveillance** · **Prophylaxie** (isolement, désinfection) · **Prévention** (vaccination)"},{"c":27,"f":"Citez les soins infirmiers dans l'hépatite virale.","b":"**Prélèvement à jeun** : cholestérol, prothrombine, transaminases, fer sérique, pigments biliaires · **Repos absolu** · **Régime** riche en glucides et protides, **pauvre en graisses** · **Supprimer l'alcool** · Traitement prescrit ; **éviter hormones/progestatifs**"},{"c":27,"f":"Citez les éléments de surveillance du malade atteint d'hépatite.","b":"**Constantes** (TA, pouls, respiration) · **Courbe de poids** · **Diurèse** · **Coloration des selles et urines**, ictère · **Appétit**, signes de danger (ictère persistant, troubles de conscience, coma)"},{"c":27,"f":"Citez les mesures de prévention de l'hépatite B selon le cours.","b":"**Vaccination** = meilleure mesure · **Hevac B** : 3 injections à 1 mois d'intervalle, rappel à 1 an puis tous les 5 ans · **Vaccination de masse** si risque élevé · **Déclaration obligatoire**"},{"c":28,"f":"Citez les signes de la cirrhose décompensée.","b":"**Ascite** et **OMI** · **Oligurie** · **Ictère** · **Hémorragies** (épistaxis, varices) · **AEG** très sévère, circulation collatérale"},{"c":28,"f":"Citez les circonstances de décompensation d'une cirrhose.","b":"**Ingestion plus importante d'alcool** · **Carence alimentaire** (protides) · **Surmenage** · **Maladie infectieuse** · **Sans cause** décelable"},{"c":28,"f":"Citez le traitement de l'encéphalopathie hépatique selon le cours.","b":"**Protides < 20 g/24 h** · **Néomycine** 1 à 2 g/24 h (flore intestinale) · **Lactulose** 15 à 30 g/24 h"},{"c":28,"f":"Citez les complications de la cirrhose.","b":"**Ascite** / décompensation · **Hémorragies digestives** (rupture de varices œsophagiennes) · **Ictère grave** · **Cachexie** · **Transformation maligne** (CPF)"},{"c":29,"f":"Citez les indications de la ponction d'ascite.","b":"**Cirrhoses** · **Péritonites tuberculeuses** · **Tumeurs abdominales** · **Maladies du foie** · **Maladies du cœur** (péricardites)"},{"c":29,"f":"Décrivez la position du malade pour la ponction d'ascite.","b":"Ponction en **fosse iliaque gauche** (éviter foie et cœur) · **Décubitus dorsal** avec **légère inclinaison à gauche**, **oreiller sous la fesse droite** · **Alèze** jusqu'au sol · Position **assise** possible (intestins flottent)"},{"c":29,"f":"Citez les éléments de surveillance pendant la ponction d'ascite.","b":"**Rassurer**, maintenir la position · **Réactions**, **pouls**, **faciès** · **Température** · **Aspect du liquide** (trouble, citrin) · **Débit** (risque de collapsus)"},{"c":29,"f":"Citez les accidents de la ponction d'ascite.","b":"**Piqûre de la paroi et des vaisseaux** · **Collapsus cardiovasculaire** · **Écoulement persistant** → infection"},{"c":30,"f":"Définissez l'aspiration gastrique et citez ses indications.","b":"**Évacuation de l'estomac** par un dispositif d'aspiration (éviter l'**inhalation**) · **Perforation de l'estomac** (traitement médical) · **Avant** et **après** intervention gastrique/abdominale · **Lavage d'estomac** · CI : **cancer de l'estomac**"},{"c":30,"f":"Décrivez la technique de l'aspiration gastrique.","b":"Installer **couché sur le côté**, rassurer, expliquer · Introduire la sonde **comme pour un gavage** · **Brancher** à l'aspirateur · Force d'aspiration **40 à 50 cm d'eau** · Régler avec **pince presse-tube**"},{"c":30,"f":"Citez les indications de l'aspiration duodénale continue.","b":"**Sub-occlusion** / **occlusion** · **Chirurgies intestinales** · **Préventif** (avant chirurgie) · **Post-opératoire** : évite la distension, soulage les sutures, favorise le retour de la motricité"},{"c":30,"f":"Citez la surveillance pendant une aspiration digestive.","b":"**Quantité** et **couleur** du liquide · **Changer le bocal** avant qu'il soit plein · Vérifier **tuyaux/coudure/moteur** si arrêt · **Calmer** le malade · **Réhydratation** selon les pertes (≈ 2 l/j)"},{"c":31,"f":"Citez les causes du cancer primitif du foie.","b":"Europe/Amérique : **cirrhose alcoolique**, **cirrhose virale**, **hémochromatose** · Afrique : surtout **cirrhose d'origine virale** · **Aflatoxine** (arachides) · **Infestation parasitaire**, **chimique**"},{"c":31,"f":"Citez les signes du CPF sur foie non cirrhotique.","b":"**Asthénie**, **amaigrissement** · **Douleur** de la région du foie irradiant en arrière et en haut · **Fièvre** possible · **Gros foie**, **dureté pierreuse**, sensible, moins mobile · **Ictère obstructif** avec prurit possible"},{"c":31,"f":"Citez les complications du CPF.","b":"**Hémopéritoine aigu** · **Hémorragie** intense avec **collapsus** · **Abcès du foie** · **Métastases** (poumons, ganglions, os, cerveau) · **Mort** rapide"},{"c":31,"f":"Citez les moyens de traitement du CPF.","b":"**Exérèse chirurgicale** (hépatectomie partielle) si localisée, sans cirrhose ni métastase · **Hépatectomie totale + transplantation** · **Chimiothérapie** (effet antalgique)"},{"c":32,"f":"Décrivez les caractéristiques de la colique hépatique.","b":"Caractère : douleur **aiguë paroxystique** · Type : **crampe** · Siège : **hypochondre droit** et **épigastre** · Irradiation : **épaule droite** et **entre les omoplates** · Palpation : vésicule **sensible** avec **défense**"},{"c":32,"f":"Citez 5 diagnostics différentiels de la colique hépatique.","b":"**Appendicite aiguë** · **Pancréatite aiguë** · **Embolie pulmonaire** · **Colique néphrétique** · **Infarctus du myocarde**"},{"c":32,"f":"Citez les complications de la lithiase biliaire.","b":"**Cholécystite** calculeuse (fièvre 39-39,5 °C, frissons) · **Lithiase du cholédoque** (blocage de la voie biliaire) · Complication fébrile avec **hyperleucocytose** → chirurgie"},{"c":32,"f":"Citez les éléments du traitement de la lithiase biliaire.","b":"**Régime** pauvre en cholestérol et aliments indigestes · **Antiseptiques**, cures thermales · Colique : **jeûne**, **compresses chaudes**, **antispasmodiques**, **antalgiques** · Complication : **cholécystectomie** · Cholédoque : **fragmentation** mécanique ou par **ondes de choc**"},{"c":33,"f":"Définissez la lithiase urinaire et citez les facteurs de lithogenèse.","b":"**Formation de calculs** dans les cavités excrétrices **rénales, urétérales ou vésicales** · **Augmentation de la concentration** des substances dissoutes · **Modification du pH** urinaire (infection → alcalin → phosphates ; viande → acide → urates) · **Stagnation** des urines"},{"c":33,"f":"Décrivez la crise de colique néphrétique.","b":"Douleur **brutale** de la **région lombaire**, **unilatérale** · Irradiation le long de l'**uretère** vers la **vessie** et les **organes génitaux** · **Envies fréquentes** d'uriner (quelques cc) · Phénomènes **pseudo-occlusifs** (météorisme, arrêt du transit) · Déclenchée par **effort, voyage**, dure heures à jours"},{"c":33,"f":"Citez les examens complémentaires de la lithiase urinaire.","b":"**Examen clinique** : fosses lombaires, **touchers pelviens** · **Biologie** : urée, créatinine, **pH urinaire**, **ECBU**, bilan phospho-calcique, hémocultures si fièvre · **ASP** : calculs radio-opaques · **UIV en urgence** (examen capital selon le cours)"},{"c":33,"f":"Citez les moyens thérapeutiques de la lithiase urinaire.","b":"**Diétothérapie** (pauvre en calcium/phosphates), **boissons abondantes** · **Antibiotiques** si infection · **Lithotripsie** extracorporelle / électrohydraulique · **Néphrolithotomie percutanée**, voie **endoscopique** · **Chirurgie**"},{"c":34,"f":"Citez les facteurs prédisposant aux infections urinaires.","b":"**Âge et sexe** (femme adulte, homme > 50 ans) · **Niveau socio-économique** / hygiène défavorable · **Obstruction** et **néphropathie** (diabète, abus d'analgésiques) · **Contamination fécale** du méat · **Explorations instrumentales** (cathétérisme)"},{"c":34,"f":"Citez les signes cliniques et biologiques de la cystite.","b":"**Envies fréquentes et impérieuses** d'uriner · **Brûlures** mictionnelles · **Nycturie** · **Douleur sus-pubienne** · Urines : **pyurie**, **bactéries**, **hématurie**"},{"c":34,"f":"Citez les conseils de prévention des infections urinaires.","b":"**Boire abondamment** (éviter thé, café, cola) · **Uriner toutes les 2-3 h**, vider complètement la vessie · **Uriner après les rapports** · Antibiotique post-coïtal si prescrit"},{"c":34,"f":"Citez les 3 catégories d'infections urinaires.","b":"**Non compliquées** (jeune femme en bonne santé) · **Compliquées** (anomalie anatomique ou physiologique) · **Récidivantes** (poussées et rémissions)"},{"c":35,"f":"Définissez l'IU chronique et citez ses facteurs favorisants.","b":"**Infection persistante ou récidivante** des voies urinaires · **Obstacles** organiques ou fonctionnels · **Diabète** · **Foyers infectieux** extra-rénaux · **Immunosuppresseurs**, **néphropathie** (abus d'analgésiques)"},{"c":35,"f":"Citez les éléments du diagnostic de l'IU chronique.","b":"**Sédiment urinaire** : leucocyturie, cylindres leucocytaires · **Bactériologie** minutieuse et **répétée** · Recherche d'un **terrain favorisant** · **Examen urologique** complet (asymétrie rénale à l'UIV)"},{"c":35,"f":"Citez les principes du traitement de l'IU chronique.","b":"Traiter les **causes locales ou générales** · ATB selon **cultures et antibiogramme de 2 échantillons** · Molécules : **cotrimoxazole**, **ampicilline**, **tétracycline** ; germes difficiles : **céphalosporine**, **gentamicine** · **Fluoroquinolones** dans les pyélonéphrites résistantes"},{"c":35,"f":"Citez les complications de la pyélonéphrite chronique.","b":"**Pyonéphrose** · **Paranéphrite** · **Insuffisance rénale**"},{"c":36,"f":"Citez les signes de la tuberculose uro-génitale.","b":"Généraux : **fatigue**, **fébricule vespérale**, **sueurs nocturnes** · Vésicaux : **dysurie**, **pollakiurie**, **hématurie terminale** · Génitaux : **fistules** périnéales ; chez la femme **salpingite**, **stérilité**, règles irrégulières"},{"c":36,"f":"Citez les examens de la tuberculose rénale.","b":"Urines : **leucocyturie stérile**, hématurie microscopique, **BK × 3** (direct + culture) · **VS augmentée** · **ASP** : calcifications rénales et prostatiques · **UIV** : érosions papillaires, sténoses calicielles et urétérales · **Urétrocystographie**, **cystoscopie**"},{"c":36,"f":"Citez le traitement de la tuberculose uro-génitale.","b":"**Trithérapie** 2-3 mois puis **bithérapie** (selon l'antibiogramme) · **Néphrectomie** totale ou partielle si destruction étendue · **Épididymectomie** si récidive · **Réimplantation urétérale** si sténose"},{"c":36,"f":"Citez les diagnostics différentiels de la tuberculose uro-génitale.","b":"**Cancer** du rein, de la vessie, de la prostate · **Nécrose papillaire** · **Cystites interstitielles** (syphilis, mycose, **bilharziose**) · **Urétrites chroniques** non bactériennes"},{"c":37,"f":"Citez les causes de l'IRA par catégorie.","b":"**Pré-rénales** : hypovolémie (hémorragie, déshydratation), choc, septicémie, chirurgie de l'aorte · **Rénales** : ischémie prolongée, hémoglobinurie, myoglobinurie, **néphrotoxiques** (aminosides, métaux lourds, AINS) · **Post-rénales** : **calcul**, **tumeur**, **hypertrophie prostatique**, rétrécissement"},{"c":37,"f":"Citez les phases et manifestations de l'IRA.","b":"**Phase initiale** : dominée par la cause, choc, hypovolémie · **Oligo-anurique** : diurèse < 400 ml, troubles **digestifs**, **neurologiques** (coma urémique), **cardiovasculaires** (HTA, OAP), **sanguins** · **Phase diurétique** : reprise de diurèse, sensibilité aux **infections**"},{"c":37,"f":"Citez les anomalies sanguines de l'IRA.","b":"**Urée** ↑ rapidement · **Créatinine** ↑ · **Natrémie** variable · **Kaliémie** ↑ (danger > 6,5 mmol/l) · **Calcium** abaissé"},{"c":37,"f":"Citez les interventions infirmières dans l'IRA.","b":"**Surveiller les électrolytes** et signes de complications · **Éviter tout apport de potassium** · Surveiller **apports**, **diurèse**, **poids**, **œdèmes**, jugulaires · Informer **immédiatement** le médecin de toute détérioration · **Soutenir** la famille"},{"c":38,"f":"Citez 6 causes de l'IRC.","b":"**Glomérulonéphrite chronique** · **Pyélonéphrite** · **Hypertension artérielle** · **Maladie polykystique** des reins · **Uropathie obstructive** · **Diabète**, infections, **toxiques** (plomb, cadmium, mercure)"},{"c":38,"f":"Citez les manifestations cliniques de l'IRC.","b":"**Fatigue**, léthargie, **céphalées** · Digestifs : **anorexie**, **nausées**, **vomissements**, diarrhées · **Tendance aux saignements**, **confusion** · **Soif**, goût métallique, stomatite · Stade avancé : **Kussmaul**, **coma**, convulsions, **givre d'urée**"},{"c":38,"f":"Citez les complications biologiques et osseuses de l'IRC.","b":"**Rétention d'eau et de sodium** · **Hypocalcémie** + ↑ **parathormone** → **ostéodystrophie** · Déficit en **vitamine D active** → **ostéomalacie** · **Hypermagnésémie** · **Anémie** (déficit en EPO)"},{"c":38,"f":"Citez les points d'éducation du patient IRC.","b":"**Dialyse** à domicile ou autodialyse · **Règles diététiques** + **restriction hydrique** · Éviter : **chocolat, fruits secs, avocat, banane, frites, jus en bouteille** · **Pesée quotidienne** + courbe ; alerter si poids ↑, œdèmes, diurèse ↓ · **Posologies adaptées**, **vaccin hépatite B**"},{"c":39,"f":"Définissez le syndrome néphrotique et citez ses causes.","b":"**Protéinurie marquée**, **hypoalbuminémie**, **œdème**, **hypercholestérolémie** · Causes : **glomérulonéphrite chronique**, **diabète** (glomérulosclérose), **amylose rénale**, **lupus**, **thrombose veineuse rénale**"},{"c":39,"f":"Expliquez la physiopathologie du syndrome néphrotique.","b":"**Perméabilité glomérulaire accrue** aux protéines · Fuite d'**albumine** dans l'urine · Le foie ne compense pas → **hypoalbuminémie** · → **œdèmes**, **hypercholestérolémie**"},{"c":39,"f":"Citez le traitement du syndrome néphrotique.","b":"**Repos au lit** quelques jours · Régime **riche en protéines** · Œdème grave : **régime pauvre en sodium** + **diurétiques** · **Prednisone** (réduire la protéinurie) · **Ciclosporine** si corticorésistance"},{"c":39,"f":"Citez les complications du syndrome néphrotique.","b":"**Infection** · **Hypercoagulabilité** · **Accélération de l'athérogenèse** · **Insuffisance rénale terminale** (si protéinurie + créatinine élevée)"},{"c":40,"f":"Citez les complications de la néphropathie gravidique.","b":"**Mort fœtale in utero** · **Hématome rétroplacentaire** · **Éclampsie**"},{"c":40,"f":"Comparez néphropathie gravidique vraie et « ajoutée ».","b":"**Vraie** : **primipare**, **3e trimestre**, régression **sans séquelles** après l'accouchement, **pas de récidive** · **Ajoutée** : dès les **premiers mois**, à **toute grossesse**, guérison **incomplète**, **récidives aggravées**, pronostic fœtal plus mauvais"},{"c":40,"f":"Citez la conduite à tenir dès la constatation d'œdèmes, de protéinurie ou d'HTA chez une femme enceinte.","b":"**Repos en décubitus gauche** · **Hypotenseurs** : clonidine, alphaméthyldopa, hydralazine (bêtabloquants si échec) · **Hospitalisation obstétricale** près du terme (déclenchement ou césarienne) · HTA sévère : **interruption thérapeutique** de grossesse possible"},{"c":40,"f":"Citez les facteurs de risque de néphropathie gravidique.","b":"**Surpoids** (antécédents personnels ou familiaux) · **Hypercholestérolémie** · **Diabète** · **HTA** · **Tabagisme**"}],"cv":{"d1":["--b1"],"d2":["--b2","--b3"],"a":["--gold"],"bg":["--bg"]},"key":"medecine_ide2_infas_v1"};
